window.VOCAB_DATA=[{"id":1,"category":"고유어","term":"가탈","definition":"일이 순조롭게 나아가는 것을 방해하는 조건.","example":"처음 하는 일이라 여기저기서 가탈이 많이 생긴다.","exampleSource":"표준국어대사전 용례","otherMeanings":["이리저리 트집을 잡아 까다롭게 구는 일.","‘가탈거리다’의 어근."]},{"id":2,"category":"고유어","term":"고샅","definition":"시골 마을의 좁은 골목길. 또는 골목 사이.","example":"마을 고샅으로 접어드는 길.","exampleSource":"표준국어대사전 용례","otherMeanings":["좁은 골짜기의 사이.","‘사타구니’를 비유적으로 이르는 말.","→ 고삿."]},{"id":3,"category":"고유어","term":"골치","definition":"‘머리01’ 또는 ‘머릿골02’을 속되게 이르는 말.","example":"골치가 쑤시다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":4,"category":"고유어","term":"괄괄하다","definition":"목소리 따위가 굵고 거세다.","example":"괄괄한 목소리.","exampleSource":"표준국어대사전 용례","otherMeanings":["성질이 세고 급하다.","풀 따위가 세다."]},{"id":5,"category":"고유어","term":"괴괴하다","definition":"쓸쓸한 느낌이 들 정도로 아주 고요하다.","example":"괴괴한 정적.","exampleSource":"표준국어대사전 용례","otherMeanings":["[怪怪, 하다] 정상적이지 않고 별나며 괴상하다."]},{"id":6,"category":"고유어","term":"깜냥","definition":"스스로 일을 헤아림. 또는 헤아릴 수 있는 능력.","example":"그는 자기의 깜냥을 잘 알고 있었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":7,"category":"고유어","term":"내처","definition":"어떤 일 끝에 더 나아가.","example":"가는 김에 내처 집까지 바래다주었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["줄곧 한결같이.","[乃妻] 그 사람의 아내.","[內處] 안방에 거처함. 또는 그 안방."]},{"id":8,"category":"고유어","term":"노량","definition":"어정어정 놀면서 느릿느릿.","example":"그는 급할 것도 없다는 듯 노량으로 걸어갔다.","exampleSource":"제공 자료 예문","otherMeanings":["[露梁] 경상남도 남해도와 하동 사이에 있는 나루터. 이순신 장군을 기리는 충렬사가 있다.","[露量] 이슬이 내린 양."]},{"id":9,"category":"고유어","term":"되바라지다","definition":"어린 나이에 어수룩한 데가 없고 얄밉도록 지나치게 똑똑하다.","example":"아직 삼십도 안 됐을 텐데? 젊은 놈이 어지간히 되바라졌군.","exampleSource":"표준국어대사전 용례","otherMeanings":["[null] 그릇이 운두가 낮고 위가 벌어져 쉽사리 바닥이 드러나 보이다.","[null] 튀어져 나오고 벌어져서 아늑한 맛이 없다.","[null] 사람됨이 남을 너그럽게 감싸 주지 아니하고 적대적으로 대하다.","[null] 차림이 얌전하지 않아 남의 눈에 잘 띄다."]},{"id":10,"category":"고유어","term":"바투","definition":"시간이나 길이가 아주 짧게.","example":"머리를 바투 깎다.","exampleSource":"표준국어대사전 용례","otherMeanings":["두 대상이나 물체의 사이가 썩 가깝게.","[Batu] 킵차크한국의 시조(1207~1255). 아버지인 주치(Juchi)의 영지를 물려받아, 1241년에 리그니츠(Liegnitz)의 싸움에서 폴란드ㆍ독일 연합군을 격파하였다. 볼가강 하류의 사라이를 수도로 정하고 킵차크한국을 세웠다."]},{"id":11,"category":"고유어","term":"부아","definition":"노엽거나 분한 마음.","example":"부아가 나다.","exampleSource":"표준국어대사전 용례","otherMeanings":["가슴안의 양쪽에 있는, 원뿔을 반 자른 것과 비슷한 모양의 호흡을 하는 기관.","허파나 목줄띠에 붙은 고기.","[副芽] 잎겨드랑이에 생기는 여러 잎눈 가운데 가장 먼저 생긴 것 이외의 잎눈. 정상적인 잎눈의 위 또는 아래나 좌우 양옆에 보통 한 개가 나지만, 때로는 여러 개가 생기기도 한다.","[副衙] 감영(監營)이 있는 곳의 군아(郡衙)."]},{"id":12,"category":"고유어","term":"을씨년스럽다","definition":"보기에 날씨나 분위기 따위가 몹시 스산하고 쓸쓸한 데가 있다.","example":"새벽 가을바람은 한층 을씨년스럽다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[null] 보기에 살림이 매우 가난한 데가 있다."]},{"id":13,"category":"고유어","term":"재겹다","definition":"몹시 지겹다.","example":"아내는 남편의 입에서 얼음이 깨물리는 소리가 참으로 재겹게 들리었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":14,"category":"고유어","term":"주눅","definition":"기운을 제대로 펴지 못하고 움츠러드는 태도나 성질.","example":"주눅이 들다.","exampleSource":"표준국어대사전 용례","otherMeanings":["부끄러움이 없이 언죽번죽한 태도나 성질."]},{"id":15,"category":"고유어","term":"곰실곰실","definition":"작은 벌레 따위가 한데 어우러져 조금씩 자꾸 굼뜨게 움직이는 모양.","example":"벌레가 곰실곰실 움직인다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":16,"category":"고유어","term":"데면데면","definition":"사람을 대하는 태도가 친밀감이 없이 예사로운 모양.","example":"그는 누구를 만나도 데면데면 대한다.","exampleSource":"표준국어대사전 용례","otherMeanings":["성질이 꼼꼼하지 않아 행동이 신중하거나 조심스럽지 않은 모양."]},{"id":17,"category":"고유어","term":"엉기정기","definition":"질서 없이 여기저기 벌여 놓은 모양.","example":"그는 책상 위에 책들을 엉기정기 벌여 놓고 나가 버렸다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":18,"category":"고유어","term":"추렴","definition":"모임이나 놀이 또는 잔치 따위의 비용으로 여럿이 각각 얼마씩의 돈을 내어 거둠.","example":"추렴을 내다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":19,"category":"고유어","term":"해사하다","definition":"얼굴이 희고 곱다랗다.","example":"해사한 얼굴.","exampleSource":"표준국어대사전 용례","otherMeanings":["표정, 웃음소리 따위가 맑고 깨끗하다.","옷차림, 자태 따위가 말끔하고 깨끗하다.","[解事, 하다] 사물을 밝게 알다.","[解絲, 하다] 감겨 있거나 매여 있거나 얽혀 있는 실을 풀다."]},{"id":20,"category":"고유어","term":"해포","definition":"한 해가 조금 넘는 동안.","example":"이 탑의 둘레를 돌고 또 돈 지가 단 며칠이 안 되건만 주민에게는 해포가 넘는 것 같았다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[蟹脯] 농게의 살을 뽑아서 말린 포."]},{"id":21,"category":"고유어","term":"드문드문","definition":"공간적으로 배지 않고 사이가 드문 모양.","example":"드문드문 서 있는 나무.","exampleSource":"표준국어대사전 용례","otherMeanings":["시간적으로 잦지 않고 드문 모양."]},{"id":22,"category":"고유어","term":"티적티적","definition":"남의 흠이나 트집을 잡으면서 자꾸 비위를 거스르는 모양.","example":"그는 사소한 흠을 티적티적 들추어 사람을 불편하게 했다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":23,"category":"고유어","term":"포슬포슬","definition":"덩이진 가루 따위가 물기가 적어 엉기지 못하고 바스러지기 쉬운 모양. ‘보슬보슬01’보다 거센 느낌을 준다.","example":"잘 익은 감자가 포슬포슬 부서졌다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":24,"category":"고유어","term":"할금할금","definition":"곁눈으로 살그머니 계속 할겨 보는 모양.","example":"강아지가 할금할금 내 눈치를 살핀다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":25,"category":"고유어","term":"흐슬부슬","definition":"차진 기가 없고 부스러져 헤어질 듯한 모양.","example":"마른 흙벽에서 모래가 흐슬부슬 흘러내렸다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":26,"category":"고유어","term":"헤실헤실","definition":"사람이 맺고 끊는 것이 확실하지 않아 싱겁고 실속이 없는 모양.","example":"그는 곤란한 질문에도 헤실헤실 웃기만 했다.","exampleSource":"제공 자료 예문","otherMeanings":["어떤 물체가 단단하지 못하여 부스러지거나 헤지기 쉬운 모양.","싱겁고 어설프게 웃는 모양."]},{"id":27,"category":"고유어","term":"조롱조롱","definition":"아이가 많이 딸려 있는 모양.","example":"그는 아이 다섯을 조롱조롱 데리고 나타났다.","exampleSource":"표준국어대사전 용례","otherMeanings":["작은 열매 따위가 많이 매달려 있는 모양."]},{"id":28,"category":"고유어","term":"갈치잠","definition":"비좁은 방에서 여럿이 모로 끼어 자는 잠.","example":"좁은 방 한 칸에 열두 명이 자려니 어쩔 수 없이 모두 갈치잠을 잘 도리밖에 없었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":29,"category":"고유어","term":"결딴","definition":"어떤 일이나 물건 따위가 아주 망가져서 도무지 손을 쓸 수 없게 된 상태.","example":"폭우로 밭이 완전히 결딴이 났다.","exampleSource":"제공 자료 예문","otherMeanings":["살림이 망하여 거덜 난 상태."]},{"id":30,"category":"고유어","term":"섬벅섬벅","definition":"크고 연한 물건이 잘 드는 칼에 쉽게 자꾸 베어지는 소리. 또는 그 모양.","example":"무를 섬벅섬벅 썰다.","exampleSource":"표준국어대사전 용례","otherMeanings":["→ 슴벅슴벅."]},{"id":31,"category":"고유어","term":"노루잠","definition":"깊이 들지 못하고 자꾸 놀라 깨는 잠.","example":"잠을 자도 설핏설핏 노루잠 자던 이가 사발밥을 남김없이 비우고 오랜만에 잠도 달게 자는 것이었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":32,"category":"고유어","term":"야물다","definition":"과실이나 곡식 따위가 알이 들어 단단하게 잘 익다.","example":"초가을의 따가운 햇살에 오곡이 잘 야문다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[null] 일 처리나 언행이 옹골차고 야무지다.","[null] 사람됨이나 씀씀이 따위가 퍽 옹골차고 헤프지 않다."]},{"id":33,"category":"고유어","term":"야무지다","definition":"사람의 성질이나 행동, 생김새 따위가 빈틈이 없이 꽤 단단하고 굳세다.","example":"고 녀석 참 야무지게 생겼군.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":34,"category":"고유어","term":"실팍하다","definition":"사람이나 물건 따위가 보기에 매우 실하다.","example":"그는 실팍한 몸집인데도 쌀 한 가마를 제대로 못 옮겼다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":35,"category":"고유어","term":"발끈","definition":"사소한 일에 걸핏하면 왈칵 성을 내는 모양.","example":"약을 발끈 올리다.","exampleSource":"표준국어대사전 용례","otherMeanings":["뒤집어엎을 듯이 시끄러운 모양.","사람이 앉거나 누워 있다가 갑자기 오뚝 일어나는 모양.","물체 따위가 갑자기 솟아오르거나 가려져 있다가 나타나는 모양."]},{"id":36,"category":"고유어","term":"졸이다","definition":"찌개, 국, 한약 따위의 물을 증발시켜 분량을 적어지게 하다. ‘졸다02「1」’의 사동사.","example":"찌개를 졸이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[null] 속을 태우다시피 초조해하다."]},{"id":37,"category":"고유어","term":"조리다","definition":"양념을 한 고기나 생선, 채소 따위를 국물에 넣고 바짝 끓여서 양념이 배어들게 하다.","example":"생선을 조리다.","exampleSource":"표준국어대사전 용례","otherMeanings":["식물의 열매나 뿌리, 줄기 따위를 꿀이나 설탕물 따위에 넣고 계속 끓여서 단맛이 배어들게 하다."]},{"id":38,"category":"고유어","term":"알차다","definition":"속이 꽉 차 있거나 내용이 아주 실속이 있다.","example":"알찬 내용.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":39,"category":"고유어","term":"옹골차다","definition":"매우 옹골지다.","example":"씨가 옹골차게 영글다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":40,"category":"고유어","term":"욱하다","definition":"앞뒤를 헤아림 없이 격한 마음이 불끈 일어나다.","example":"욱하고 치밀어 오르는 감정.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":41,"category":"고유어","term":"쭈뼛하다","definition":"무섭거나 놀라서 머리카락이 꼿꼿하게 일어서는 듯한 느낌이 들다. ‘주뼛하다[Ⅰ][2]「1」’보다 센 느낌을 준다.","example":"고함 소리에 머리끝이 쭈뼛했다.","exampleSource":"표준국어대사전 용례","otherMeanings":["물건의 끝이 차차 가늘어지면서 삐죽하게 솟다. 또는 그렇게 되게 하다. ‘주뼛하다[Ⅰ][1]’보다 센 느낌을 준다.","어줍거나 부끄러워서 머뭇거리거나 주저하다. ‘주뼛하다[Ⅰ][2]「2」’보다 센 느낌을 준다.","입술 끝을 비죽 내밀다. ‘주뼛하다[Ⅰ][3]’보다 센 느낌을 준다.","물건의 끝이 차차 가늘어지면서 삐죽삐죽하게 솟아 있는 상태이다. ‘주뼛하다[Ⅱ]’보다 센 느낌을 준다."]},{"id":42,"category":"고유어","term":"울컥하다","definition":"격한 감정이 갑자기 일어나다. ‘울걱하다「1」’보다 거센 느낌을 준다.","example":"무슨 일로든지 한번 울컥하기만 하면 당장 칼을 휘둘러 버리고 싶은 충동에 정신을 못 차리는 것이었는데….","exampleSource":"표준국어대사전 용례","otherMeanings":["먹은 것을 갑자기 게우는 소리가 나다. 또는 그런 소리를 내다. ‘울걱하다「2」’보다 거센 느낌을 준다."]},{"id":43,"category":"고유어","term":"사뭇","definition":"마음에 사무치도록 매우.","example":"그녀의 마음에는 사뭇 슬픔이 밀려왔다.","exampleSource":"표준국어대사전 용례","otherMeanings":["거리낌 없이 마구.","내내 끝까지.","아주 딴판으로."]},{"id":44,"category":"고유어","term":"머쓱하다","definition":"무안을 당하거나 흥이 꺾여 어색하고 열없다.","example":"그는 자신의 마음을 들킨 것이 머쓱해서 웃고 말았다.","exampleSource":"표준국어대사전 용례","otherMeanings":["어울리지 않게 키가 크다."]},{"id":45,"category":"고유어","term":"낫잡다","definition":"금액, 나이, 수량, 수효 따위를 계산할 때에, 조금 넉넉하게 치다.","example":"손님이 더 올지 모르니 음식을 낫잡아 준비해라.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":46,"category":"고유어","term":"다그치다","definition":"일이나 행동 따위를 빨리 끝내려고 몰아치다.","example":"일손을 다그치다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[null] 지친 몸을 다시 추스르다.","[null] 일이나 행동 따위를 요구하며 몰아붙이다."]},{"id":47,"category":"고유어","term":"되뇌다","definition":"같은 말을 되풀이하여 말하다.","example":"그는 같은 말을 버릇처럼 늘 되뇐다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":48,"category":"고유어","term":"둘레둘레","definition":"사방을 이리저리 살피는 모양.","example":"이 집 저 집 둘레둘레 돌아다닌다.","exampleSource":"표준국어대사전 용례","otherMeanings":["여러 사람이나 물건이 주위에 둥그렇게 둘러 있는 모양."]},{"id":49,"category":"고유어","term":"몰리다","definition":"여럿이 한곳으로 모여들다.","example":"입구로만 몰리는 청중들.","exampleSource":"표준국어대사전 용례","otherMeanings":["[null] 원하지 않는 처지나 방향으로 떠밀리다. ‘몰다[1]’의 피동사.","[null] 무엇으로 인정되거나 닦아세워져 그렇게 다루어지다. ‘몰다[3]’의 피동사.","[null] 무엇이 한꺼번에 많이 밀리다.","[null] 무엇이 모자라 곤란을 당하다."]},{"id":50,"category":"고유어","term":"뭉텅뭉텅","definition":"잇따라 제법 크게 잘리거나 끊어지는 모양. ‘뭉떵뭉떵01’보다 거센 느낌을 준다.","example":"소리 지를 겨를도 없이 그놈은 내 머리채를 날이 시퍼런 군도로 뭉텅뭉텅 베는 것이었어요.","exampleSource":"표준국어대사전 용례","otherMeanings":["‘뭉텅뭉텅하다’의 어근."]},{"id":51,"category":"고유어","term":"박작거리다","definition":"많은 사람이 좁은 곳에 모여 매우 어수선하게 자꾸 움직이다.","example":"시장에 사람들이 박작거린다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":52,"category":"고유어","term":"벼르다","definition":"어떤 일을 이루려고 마음속으로 준비를 단단히 하고 기회를 엿보다.","example":"결전을 벼르다.","exampleSource":"표준국어대사전 용례","otherMeanings":["일정한 비례에 맞추어서 여러 몫으로 나누다."]},{"id":53,"category":"고유어","term":"본치","definition":"남의 눈에 띄는 태도나 겉모양.","example":"그 여인은 맛깔 있어 보이는 점심상을 본치도 좋게 들여왔다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":54,"category":"고유어","term":"사부작거리다","definition":"별로 힘들이지 않고 계속 가볍게 행동하다.","example":"공원에서 아이들이 사부작거리는 모습이 귀엽다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":55,"category":"고유어","term":"새록새록","definition":"어떤 생각이나 느낌이 거듭하여 새롭게 생기는 모양.","example":"아프고 쓰라렸던 지난 일이 새록새록 떠올랐다.","exampleSource":"표준국어대사전 용례","otherMeanings":["새로운 물건이나 일이 잇따라 생기는 모양.","잠든 어린아이가 숨 쉴 때 나는 소리."]},{"id":56,"category":"고유어","term":"설레설레","definition":"큰 동작으로 몸의 한 부분을 거볍게 잇따라 가로흔드는 모양.","example":"할아버지는 무엇인가 몹시 답답하시다는 듯 고개를 설레설레 흔드시다가 담배를 꺼내 무셨다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":57,"category":"고유어","term":"쏠리다","definition":"물체가 기울어져 한쪽으로 몰리다.","example":"버스가 급정거하자 사람들이 와락 앞으로 쏠려 넘어졌다.","exampleSource":"표준국어대사전 용례","otherMeanings":["마음이나 눈길이 어떤 대상에 끌려서 한쪽으로 기울어지다."]},{"id":58,"category":"고유어","term":"쓰렁쓰렁","definition":"남이 모르게 비밀리 행동하는 모양.","example":"그는 남의 눈을 피해 쓰렁쓰렁 일을 꾸몄다.","exampleSource":"교정 예문","otherMeanings":["일을 건성으로 하는 모양.","사귀는 정이 버성기어 서로의 사이가 소원한 모양."]},{"id":59,"category":"고유어","term":"조곤조곤","definition":"성질이나 태도가 조금 은근하고 끈덕진 모양.","example":"조곤조곤 설명하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":60,"category":"고유어","term":"종종걸음","definition":"발을 가까이 자주 떼며 급히 걷는 걸음.","example":"완자무늬 철문 사이로 낯익은 늙은 가정부가 비탈진 정원 길을 종종걸음으로 내려오는 게 보였다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":61,"category":"고유어","term":"지피다","definition":"아궁이나 화덕 따위에 땔나무를 넣어 불을 붙이다.","example":"군불을 지피다.","exampleSource":"표준국어대사전 용례","otherMeanings":["사람에게 신이 내려서 모든 것을 알아맞히는 신통하고 묘한 힘이 생기다.","한데 엉기어 붙다."]},{"id":62,"category":"고유어","term":"쪼개다","definition":"시간이나 돈 따위를 아끼다.","example":"내일 갈 수 있게 시간을 좀 쪼개 볼게.","exampleSource":"표준국어대사전 용례","otherMeanings":["둘 이상으로 나누다.","(속되게) 소리 없이 입을 벌리고 웃다."]},{"id":63,"category":"고유어","term":"찌릿찌릿","definition":"뼈마디나 몸의 일부가 매우 또는 자꾸 저린 느낌.","example":"벌을 받느라 무릎을 꿇고 오래 앉아 있었더니 다리가 찌릿찌릿 저리다.","exampleSource":"표준국어대사전 용례","otherMeanings":["가슴이나 마음이 매우 저린 느낌."]},{"id":64,"category":"고유어","term":"톺다","definition":"가파른 곳을 오르려고 매우 힘들여 더듬다.","example":"논틀밭틀길도 없는 데를 걸어 본 것은 물론, 눈이 반길이나 쌓인 태산준령을 톺아 넘어갔기 때문에, 실제의 거리로는 천수백 리를 걸었던 것이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["틈이 있는 곳마다 모조리 더듬어 뒤지면서 찾다.","삼 따위를 삼을 때, 짼 삼의 끝을 가늘고 부드럽게 하려고 톱으로 눌러 긁어 훑다."]},{"id":65,"category":"고유어","term":"해찰하다","definition":"일에는 마음을 두지 아니하고 쓸데없이 다른 짓을 하다.","example":"아이들이란 자칫 한눈팔고 해찰하기 일쑤라서 가끔 주의를 환기할 필요가 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":["마음에 썩 내키지 아니하여 물건을 부질없이 이것저것 집적거려 해치다."]},{"id":66,"category":"고유어","term":"휘둥그레지다","definition":"놀라거나 두려워서 눈이 크고 둥그렇게 되다.","example":"사고가 났다는 말에 사람들은 휘둥그레져 사건의 경위를 묻는다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":67,"category":"고유어","term":"기리다","definition":"뛰어난 업적이나 바람직한 정신, 위대한 사람 따위를 칭찬하고 기억하다.","example":"선열의 뜻을 기리다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":68,"category":"고유어","term":"드레","definition":"인격적으로 점잖은 무게.","example":"어린 사람이 퍽 드레가 있어 보인다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":69,"category":"고유어","term":"살갑다","definition":"마음씨가 부드럽고 상냥하다.","example":"형이라고 해도 살가운 정을 느끼기보다는 믿음직스러우면서도 어려웠다.","exampleSource":"표준국어대사전 용례","otherMeanings":["집이나 세간 따위가 겉으로 보기보다는 속이 너르다.","닿는 느낌 같은 것이 가볍고 부드럽다.","물건 따위에 정이 들다."]},{"id":70,"category":"고유어","term":"가납사니","definition":"쓸데없는 말을 지껄이기 좋아하는 수다스러운 사람.","example":"가납사니 같은 도시 사람들은 제멋대로 그럴싸한 소문을 퍼뜨리며….","exampleSource":"표준국어대사전 용례","otherMeanings":["말다툼을 잘하는 사람."]},{"id":71,"category":"고유어","term":"가드락가드락","definition":"조금 거만스럽게 잘난 체하며 버릇없이 자꾸 구는 모양.","example":"그 사람은 자기 집이 부자라고 하도 가드락가드락 친구를 대하여 모두가 그를 꺼린다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":72,"category":"고유어","term":"가살","definition":"말씨나 행동이 가량맞고 야살스러움. 또는 그런 짓.","example":"가살을 떨다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":73,"category":"고유어","term":"객쩍다","definition":"행동이나 말, 생각이 쓸데없고 싱겁다.","example":"객쩍은 공상.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":74,"category":"고유어","term":"안차다","definition":"겁이 없고 야무지다.","example":"그 애는 어른이 뭐라 해도 워낙 안차서 기도 안 죽는다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":75,"category":"고유어","term":"토실토실","definition":"보기 좋을 정도로 살이 통통하게 찐 모양.","example":"사 온 돼지가 토실토실 살이 오르면서….","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":76,"category":"고유어","term":"훈훈하다","definition":"날씨나 온도가 견디기 좋을 만큼 덥다.","example":"훈훈한 공기.","exampleSource":"표준국어대사전 용례","otherMeanings":["[薰薰, 하다] 마음을 부드럽게 녹여 주는 따스함이 있다.","[薰薰, 하다] 냄새가 서려 있다.","[醺醺, 하다] 술 취한 기운이 얼근하다."]},{"id":77,"category":"고유어","term":"거북하다","definition":"몸이 찌뿌드드하고 괴로워 움직임이 자연스럽지 못하거나 자유롭지 못하다.","example":"나는 속이 거북해서 점심을 걸렀다.","exampleSource":"표준국어대사전 용례","otherMeanings":["마음이 어색하고 겸연쩍어 편하지 않다."]},{"id":78,"category":"고유어","term":"구나방","definition":"말이나 행동이 모질고 거칠고 사나운 사람을 이르는 말.","example":"그는 말씨가 거친 구나방으로 소문이 났다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":79,"category":"고유어","term":"깔짝깔짝","definition":"자꾸 작은 물건이나 일을 가지고 만지작거리기만 하고 좀처럼 진전을 이루지 못하는 모양.","example":"밥을 깔짝깔짝 먹다.","exampleSource":"표준국어대사전 용례","otherMeanings":["매우 얇고 빳빳한 물체의 바닥이 앞뒤로 되풀이하여 가볍게 자꾸 뒤집히는 소리.","자꾸 갉아서 뜯거나 계속 진집을 내는 모양."]},{"id":80,"category":"고유어","term":"말랑말랑하다","definition":"사람의 몸이나 기질이 야무지지 못하고 맺힌 데가 없어 약하다.","example":"아들이 아니라 한 말랑말랑한 젊은이로 뵈는 눈총을 하고, 거의 강제로 술을 먹이는데 무척이나 재미있어했다.","exampleSource":"표준국어대사전 용례","otherMeanings":["매우 또는 여기저기가 야들야들하게 보드랍고 무르다."]},{"id":81,"category":"고유어","term":"몽니","definition":"받고자 하는 대우를 받지 못할 때 내는 심술.","example":"몽니를 부리다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":82,"category":"고유어","term":"무녀리","definition":"말이나 행동이 좀 모자란 듯이 보이는 사람을 비유적으로 이르는 말.","example":"영두만 한 무녀리가 없는 줄 알았는데 의곤이에 대면 영두는 오히려 씨억씨억하고 실팍한 터수였다.","exampleSource":"표준국어대사전 용례","otherMeanings":["한 태에 낳은 여러 마리 새끼 가운데 가장 먼저 나온 새끼."]},{"id":83,"category":"고유어","term":"무쪽같다","definition":"하는 행동이 변변치 못함을 이르는 말.","example":"할머니는 살뜰하게 살림을 꾸리시는 분인데, 무쪽같은 나는 어떻게 살림을 해야 할지 몰라 공연히 허둥대기만 한다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[null] 사람의 생김새가 몹시 못난 것을 두고 속되게 이르는 말. 흔히 여자의 경우를 두고 이른다."]},{"id":84,"category":"고유어","term":"발만스럽다","definition":"두려워하거나 삼가는 태도가 없이 꽤 버릇없다.","example":"요즘에는 어머니에게도 마구 바락바락 들이덤비는 게 그 행실이 꽤 발만스럽습니다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":85,"category":"고유어","term":"본데없다","definition":"보고 배운 것이 없다. 또는 행동이 예의범절에 어긋나는 데가 있다.","example":"어디서 배운 버릇이냐. 본데없는 놈 같으니라고.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":86,"category":"고유어","term":"볼썽사납다","definition":"어떤 사람이나 사물의 모습이 보기에 역겹다.","example":"그의 얼굴은 며칠 씻지 않은 사람처럼 볼썽사나웠다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":87,"category":"고유어","term":"사박스럽다","definition":"성질이 보기에 독살스럽고 야멸친 데가 있다.","example":"아내는 남편을 사박스럽게 몰아붙였다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":88,"category":"고유어","term":"새살스럽다","definition":"성질이 차분하지 못하고 가벼워 말이나 행동이 실없고 부산한 데가 있다.","example":"새살스러운 행동.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":89,"category":"고유어","term":"생게망게하다","definition":"하는 행동이나 말이 갑작스럽고 터무니없다.","example":"최가는 서럽게 울기 시작했다. 건성으로 울고 있던 상제는 서리병아리 같은 상놈 하나가 산신 제물에 메뚜기 뛰어들 듯하더니 읍곡(泣哭)을 하자, 생게망게해서 맥을 놓고 바라보았다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":90,"category":"고유어","term":"솔다","definition":"시끄러운 소리나 귀찮은 말을 자꾸 들어서 귀가 아프다.","example":"그 말은 귀가 솔도록 들었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["물기가 있던 것이나 상처 따위가 말라서 굳어지다.","흐르는 물이 세차게 굽이쳐 용솟음치다.","땅에 습기가 많아서 푸성귀 따위가 물러서 썩다.","공간이 좁다.","긁으면 아프고 그냥 두자니 가렵다."]},{"id":91,"category":"고유어","term":"알찐대다","definition":"남의 비위를 맞추려고 가까이 붙어서 계속 아첨하다.","example":"재환이는 태남이와 동갑내기였다. 그러나 유난히 잔망해 태남이 어깨 밑에서 알찐댔고 성품이 소심해서 태남이가 시키는 일이라면 입의 혀처럼 순종했다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":92,"category":"고유어","term":"야멸차다","definition":"자기만 생각하고 남의 사정을 돌볼 마음이 거의 없다.","example":"채련이만 하더라도 그렇게 야멸차게 하는 법이 어디 있나요. 우리는 마당에 내버려 두고….","exampleSource":"표준국어대사전 용례","otherMeanings":["태도가 차고 야무지다."]},{"id":93,"category":"고유어","term":"얍삽하다","definition":"(속되게) 사람이 얕은꾀를 쓰면서 자신의 이익만을 챙기려는 태도가 있다.","example":"얍삽하게 빠져나오다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":94,"category":"고유어","term":"어깃장","definition":"짐짓 어기대는 행동.","example":"사람이란 늙으면 대개의 경우 어깃장도 놓고 이기적으로 된다고들 한다.","exampleSource":"표준국어대사전 용례","otherMeanings":["널문을 짤 때 널쪽을 맞추어서 띳장을 대고 못을 박은 뒤, 그 문짝이 일그러지지 아니하게 대각선으로 붙인 띳장."]},{"id":95,"category":"고유어","term":"옴짝달싹","definition":"몸을 아주 조금 움직이는 모양.","example":"옴짝달싹 못 하게 묶다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":96,"category":"고유어","term":"우렁잇속","definition":"품은 생각을 모두 털어놓지 아니하는 의뭉스러운 속마음을 비유적으로 이르는 말.","example":"그 녀석의 속마음은 우렁잇속 같아서 뭐가 뭔지 알 수가 없다.","exampleSource":"표준국어대사전 용례","otherMeanings":["내용이 복잡하여 헤아리기 어려운 일을 비유적으로 이르는 말."]},{"id":97,"category":"고유어","term":"의뭉하다","definition":"겉으로는 어리석은 것처럼 보이면서 속으로는 엉큼하다.","example":"의뭉한 속셈을 드러내다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":98,"category":"고유어","term":"이물스럽다","definition":"성질이 음험하여 속을 헤아리기에 어려움이 있다.","example":"이물스러운 노파.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":99,"category":"고유어","term":"입방아","definition":"어떤 사실을 화제로 삼아 이러쿵저러쿵 쓸데없이 입을 놀리는 일.","example":"입방아에 오르내리다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":100,"category":"고유어","term":"자글자글","definition":"적은 양의 액체나 기름 따위가 걸쭉하게 잦아들면서 자꾸 끓는 소리. 또는 그 모양.","example":"찌개가 자글자글 끓고 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":["걱정스럽거나 조바심이 나거나 못마땅하여 마음을 졸이는 모양.","어린아이가 아파서 열이 자꾸 나며 몸이 달아오르는 모양.","햇볕이 지질 듯이 내리쪼이는 모양.","물체가 쪼그라들어 잔주름이 많은 모양."]},{"id":101,"category":"고유어","term":"콩팔칠팔하다","definition":"갈피를 잡을 수 없도록 마구 지껄이다.","example":"그는 흥분해서 콩팔칠팔하며 말을 늘어놓았다.","exampleSource":"제공 자료 예문","otherMeanings":["하찮은 일을 가지고 시비조로 캐묻고 따지다."]},{"id":102,"category":"고유어","term":"트레바리","definition":"이유 없이 남의 말에 반대하기를 좋아함. 또는 그런 성격을 지닌 사람.","example":"그는 무슨 말이든 반대부터 하는 트레바리였다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":103,"category":"고유어","term":"허투루","definition":"아무렇게나 되는대로.","example":"허투루 말하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":104,"category":"고유어","term":"헤살","definition":"일을 짓궂게 훼방함. 또는 그런 짓.","example":"헤살을 놓다.","exampleSource":"표준국어대사전 용례","otherMeanings":["물 따위를 젓거나 하여 흩뜨림. 또는 그런 짓."]},{"id":105,"category":"고유어","term":"황망히","definition":"마음이 몹시 급하여 당황하고 허둥지둥하는 면이 있게.","example":"황망히 걸음을 재촉하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":106,"category":"고유어","term":"후리다","definition":"남의 것을 갑자기 빼앗거나 슬쩍 가지다.","example":"그 지주는 남의 재물을 후려 먹었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["휘몰아 채거나 쫓다.","휘둘러서 깎거나 베다.","휘둘러서 때리거나 치다.","매력으로 남을 유혹하여 정신을 매우 흐리게 하다.","그럴듯한 말로 속여 넘기다.","→ 훌치다01."]},{"id":107,"category":"고유어","term":"후줄근하다","definition":"옷이나 종이 따위가 약간 젖거나 풀기가 빠져 아주 보기 흉하게 축 늘어져 있다.","example":"옷이 비에 젖어 후줄근하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["몹시 지치고 고단하여 몸이 축 늘어질 정도로 아주 힘이 없다."]},{"id":108,"category":"고유어","term":"옥실옥실","definition":"아기자기한 재미 따위가 많은 모양.","example":"작은 소품들이 옥실옥실 놓인 방에는 아기자기한 재미가 있었다.","exampleSource":"교정 예문","otherMeanings":["‘옥시글옥시글’의 준말."]},{"id":109,"category":"고유어","term":"을러대다","definition":"위협적인 언동으로 을러서 남을 억누르다.","example":"그 여자가 너무 앙칼지고 영악해서 공갈을 치거나 을러대도 아무 소용이 없었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":110,"category":"고유어","term":"조잘조잘","definition":"조금 낮은 목소리로 빠르게 말을 계속하는 모양.","example":"이 아이는 엄마에게 수업 시간에 있었던 일을 조잘조잘 이야기했다.","exampleSource":"제공 자료 예문","otherMeanings":["참새 따위의 작은 새가 잇따라 지저귀는 모양.","작은 끄나풀 같은 것이 어지럽게 달린 모양."]},{"id":111,"category":"고유어","term":"고깝다","definition":"섭섭하고 야속하여 마음이 언짢다.","example":"나를 모르는 체하는 것이 고까운 생각이 들었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":112,"category":"고유어","term":"곧다","definition":"마음이나 뜻이 흔들림 없이 바르다.","example":"대쪽같이 곧은 절개.","exampleSource":"표준국어대사전 용례","otherMeanings":["굽거나 비뚤어지지 아니하고 똑바르다."]},{"id":113,"category":"고유어","term":"도탑다","definition":"서로의 관계에 사랑이나 인정이 많고 깊다.","example":"우정이 도탑다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":114,"category":"고유어","term":"못내","definition":"자꾸 마음에 두거나 잊지 못하는 모양.","example":"못내 그리워하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["이루 다 말할 수 없이."]},{"id":115,"category":"고유어","term":"삽삽하다","definition":"태도나 마음 씀씀이가 마음에 들게 부드럽고 사근사근하다.","example":"청년의 삽삽한 태도에 마음이 누그러졌다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[颯颯, 하다] 바람이 몸으로 느끼기에 쌀쌀하다.","[澁澁, 하다] 매끄럽지 아니하고 껄껄하다.","[澁澁, 하다] 말이나 글이 분명하지 못하여 이해하기 어렵다.","[澁澁, 하다] 맛이 매우 떫다."]},{"id":116,"category":"고유어","term":"똘기","definition":"채 익지 않은 과일.","example":"배가 고픈 아이는 산에 있는 똘기까지 따 먹었다.","exampleSource":"교정 예문","otherMeanings":[]},{"id":117,"category":"고유어","term":"딸각딸각","definition":"‘딸가닥딸가닥’의 준말.","example":"부엌에서 설거지를 하는지 딸각딸각 소리가 난다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":118,"category":"고유어","term":"서름하다","definition":"남과 가깝지 못하고 사이가 조금 서먹하다.","example":"그 여학생과는 서름한 사이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["사물 따위에 익숙하지 못하고 서툴다."]},{"id":119,"category":"고유어","term":"애처롭다","definition":"가엾고 불쌍하여 마음이 슬프다.","example":"애처롭게 울다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":120,"category":"고유어","term":"저미다","definition":"마음을 몹시 아프게 하다.","example":"애간장을 저미다.","exampleSource":"표준국어대사전 용례","otherMeanings":["여러 개의 작은 조각으로 얇게 베어 내다.","칼로 도려내듯이 쓰리고 아프게 하다."]},{"id":121,"category":"고유어","term":"짠하다","definition":"안타깝게 뉘우쳐져 마음이 조금 언짢고 아프다.","example":"마음이 짠하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":122,"category":"고유어","term":"송아리","definition":"꽃이나 열매 따위가 잘게 모여 달려 있는 덩어리.","example":"포도 송아리.","exampleSource":"표준국어대사전 용례","otherMeanings":["꽃이나 열매 따위가 잘게 모여 달려 있는 덩어리를 세는 단위."]},{"id":123,"category":"고유어","term":"아람","definition":"밤이나 상수리 따위가 충분히 익어 저절로 떨어질 정도가 된 상태. 또는 그런 열매.","example":"흔들지도 않는 밤나무 가지에서 남은 밤송이가 저 혼자 아람이 벌어져 떨어져 내렸다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":124,"category":"고유어","term":"이울다","definition":"꽃이나 잎이 시들다.","example":"꽃이 이울다.","exampleSource":"표준국어대사전 용례","otherMeanings":["점점 쇠약하여지다.","해나 달의 빛이 약해지거나 스러지다."]},{"id":125,"category":"고유어","term":"마구리하다","definition":"기다란 물건 끝을 막다.","example":"주석으로 지팡이를 마구리하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":126,"category":"고유어","term":"스러지다","definition":"형체나 현상 따위가 차차 희미해지면서 없어지다.","example":"죽음은 한 조각 구름이 스러지는 것이라고 여기고 있더라.","exampleSource":"표준국어대사전 용례","otherMeanings":["불기운이 약해져서 꺼지다."]},{"id":127,"category":"고유어","term":"맵짜다","definition":"음식의 맛이 맵고 짜다.","example":"새댁이 만든 음식은 모두 맵짰다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[null] 바람 따위가 매섭게 사납다.","[null] 성미가 사납고 독하다.","[null] 성질 따위가 야무지고 옹골차다."]},{"id":128,"category":"고유어","term":"삼삼하다","definition":"음식 맛이 조금 싱거운 듯하면서 맛이 있다.","example":"국물이 삼삼하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["잊히지 않고 눈앞에 보이는 듯 또렷하다.","사물이나 사람의 생김새나 됨됨이가 마음이 끌리게 그럴듯하다.","[森森, 하다] 나무가 빽빽이 우거져 무성하다."]},{"id":129,"category":"고유어","term":"아귀아귀","definition":"음식을 욕심껏 입 안에 넣고 마구 씹어 먹는 모양.","example":"그는 밥을 아귀아귀 먹어 대며 내심 화를 삭이고 있었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":130,"category":"고유어","term":"안치다","definition":"밥, 떡, 찌개 따위를 만들기 위하여 그 재료를 솥이나 냄비 따위에 넣고 불 위에 올리다.","example":"시루에 떡을 안치다.","exampleSource":"표준국어대사전 용례","otherMeanings":["어려운 일이 앞에 밀리다.","앞으로 와 닥치다."]},{"id":131,"category":"고유어","term":"잦히다","definition":"밥물이 끓으면 불의 세기를 잠깐 줄였다가 다시 조금 세게 해서 물이 잦아지게 하다.","example":"밥물을 잦히다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[null] 뒤로 기울이다. ‘잦다02’의 사동사.","[null] 물건의 안쪽이나 아래쪽이 겉으로 드러나게 하다."]},{"id":132,"category":"고유어","term":"차지다","definition":"반죽이나 밥, 떡 따위가 끈기가 많다.","example":"차진 흙.","exampleSource":"표준국어대사전 용례","otherMeanings":["[null] 성질이 야무지고 까다로우며 빈틈이 없다."]},{"id":133,"category":"고유어","term":"곰비임비","definition":"물건이 거듭 쌓이거나 일이 계속 일어남을 나타내는 말.","example":"경사스러운 일이 곰비임비 일어난다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":134,"category":"고유어","term":"마름질","definition":"옷감이나 재목 따위를 치수에 맞도록 재거나 자르는 일.","example":"옷감을 펼쳐 놓고 마름질을 시작하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":135,"category":"고유어","term":"매조지다","definition":"일의 끝을 단단히 단속하여 마무리하다.","example":"지붕 이을 이엉도 엮으며 저희 딴엔 끼닛값을 하느라고 시늉껏 했습니다만 처소의 동무님들과는 일 매조지는 솜씨가 비견될 바 아니었지요.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":136,"category":"고유어","term":"모꼬지","definition":"놀이나 잔치 또는 그 밖의 일로 여러 사람이 모이는 일.","example":"혼인날에도 다른 제자보다 오히려 더 일찍이 와서 모든 일을 총찰하였고 모꼬지 자리에서도 가장 기쁜 듯이 술을 마시고 춤을 추고 즐기었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":137,"category":"고유어","term":"무릎맞춤","definition":"두 사람의 말이 서로 어긋날 때, 제삼자를 앞에 두고 전에 한 말을 되풀이하여 옳고 그름을 따짐.","example":"이 일은 무릎맞춤을 해 보아야 진상이 밝혀지겠다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":138,"category":"고유어","term":"허발","definition":"몹시 굶주려 있거나 궁하여 체면 없이 함부로 먹거나 덤빔.","example":"배고픈 김에 허발을 하고 음식을 걷어 먹었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[虛發] 총이나 활을 쏘아서 맞히지 못함.","[虛發] 목적을 이루지 못하는 공연한 짓이나 걸음을 함."]},{"id":139,"category":"고유어","term":"영금","definition":"따끔하게 당하는 곤욕.","example":"영금을 보다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[靈, 금] → 영검02.","[靈禽] 영묘한 힘이 있어 상서로움을 가져온다고 전하여지는 새. 흔히 ‘봉황’을 이른다."]},{"id":140,"category":"고유어","term":"종요롭다","definition":"없어서는 안 될 정도로 매우 긴요하다.","example":"이번 기술 제휴는 우리 회사를 키우는 데 종요로운 일이므로 모두가 성심으로 이 일에 임해 주기 바랍니다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":141,"category":"고유어","term":"댓바람","definition":"일이나 때를 당하여 서슴지 않고 당장.","example":"소식을 듣자마자 댓바람으로 달려나갔다.","exampleSource":"표준국어대사전 용례","otherMeanings":["일이나 때를 당하여 단 한 번.","아주 이른 시간."]},{"id":142,"category":"고유어","term":"긋다","definition":"비가 잠시 그치다.","example":"비가 긋는 것도 잠깐, 곧이어 빗줄기가 다시 쏟아지기 시작했다.","exampleSource":"표준국어대사전 용례","otherMeanings":["어떤 일정한 부분을 강조하거나 나타내기 위하여 금이나 줄을 그리다.","성냥이나 끝이 뾰족한 물건을 평면에 댄 채로 어느 방향으로 약간 힘을 주어 움직이다.","물건값이나 밥값, 술값 따위를 바로 내지 않고 외상으로 처리하다.","일의 경계나 한계 따위를 분명하게 짓다.","시험 채점에서 빗금을 표시하여 답이 틀림을 나타내다.","손이나 손가락으로 허공에 어떤 것을 그리는 동작을 하다.","명단에서 이름을 빼거나 문장이나 글의 일부분을 삭제하다.","활 따위를 쏘다.","비를 잠시 피하여 그치기를 기다리다."]},{"id":143,"category":"고유어","term":"그저","definition":"변함없이 이제까지.","example":"비가 그저 내리고 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":["다른 일은 하지 않고 그냥.","별로 신기할 것 없이.","어쨌든지 무조건.","특별한 목적이나 이유 없이.","아닌 게 아니라 과연. 남을 책망하거나 비난하는 뜻으로 쓴다."]},{"id":144,"category":"고유어","term":"해거름","definition":"해가 서쪽으로 넘어가는 일. 또는 그런 때.","example":"해거름에 가겠다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":145,"category":"고유어","term":"해거리","definition":"한 해를 거름. 또는 그런 간격.","example":"이 대회는 해거리로 열린다.","exampleSource":"표준국어대사전 용례","otherMeanings":["한 해를 걸러서 열매가 많이 열림. 또는 그런 현상. 한 해에 열매가 많이 열리면 나무가 약해져서 그다음 해에는 열매가 거의 열리지 않는다."]},{"id":146,"category":"고유어","term":"후미지다","definition":"물가나 산길이 휘어서 굽어 들어간 곳이 매우 깊다.","example":"후미진 골짜기.","exampleSource":"표준국어대사전 용례","otherMeanings":["[null] 아주 구석지고 으슥하다."]},{"id":147,"category":"고유어","term":"빗밑","definition":"비가 그치어 날이 개는 속도.","example":"빗밑이 가볍다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":148,"category":"고유어","term":"스산하다","definition":"몹시 어수선하고 쓸쓸하다.","example":"가랑비가 뿌리고 산바람도 불어와 스산하였다.","exampleSource":"표준국어대사전 용례","otherMeanings":["날씨가 흐리고 으스스하다.","마음이 가라앉지 아니하고 뒤숭숭하다."]},{"id":149,"category":"고유어","term":"여우비","definition":"볕이 나 있는 날 잠깐 오다가 그치는 비.","example":"여우비가 온 끝이라 개울가의 풀들이나 물빛이 더욱 뚜렷하였다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":150,"category":"고유어","term":"미처","definition":"아직 거기까지 미치도록.","example":"그가 오기 전에 미처 일을 끝내지 못했다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":151,"category":"고유어","term":"얼추","definition":"어떤 기준에 거의 가깝게.","example":"도착할 시간이 얼추 다 되었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["어지간한 정도로 대충."]},{"id":152,"category":"고유어","term":"이루","definition":"여간하여서는 도저히.","example":"이루 다 헤아릴 수 없다.","exampleSource":"표준국어대사전 용례","otherMeanings":["있는 대로 다.","[二壘] 야구에서, 일루와 삼루 사이에 있는 둘째 베이스.","[二壘] 야구에서, 이루를 지키는 선수.","[離婁] 중국 고대의 전설상의 인물. 백 보 떨어진 곳의 털끝을 볼 수 있을 만큼 시력이 뛰어났다고 한다.","[離淚] 이별할 때 슬퍼서 흘리는 눈물.","[離壘] 야구에서, 주자가 베이스에서 떨어지는 일."]},{"id":153,"category":"고유어","term":"가닥가닥","definition":"여러 군데서 갈려 나온 낱낱의 줄.","example":"베개 밑으로 흘러내리고 있는 그 섬세한 머리칼의 가닥가닥은 멜로디를 닮았고 합쳐져선 소리 없는 심포니를 이루고 있는 것이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["여러 가닥으로 갈라진 모양.","물기나 풀기가 있는 물체의 거죽이 거의 말라서 빳빳한 상태."]},{"id":154,"category":"고유어","term":"갈팡질팡","definition":"갈피를 잡지 못하고 이리저리 헤매는 모양.","example":"사병(士兵)들이 요란한 총성에 놀라 갈팡질팡 어둠 속을 뛰고 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":155,"category":"고유어","term":"갉작갉작","definition":"날카롭고 뾰족한 끝으로 자꾸 바닥이나 거죽을 문지르는 모양.","example":"눈가를 새끼손가락으로 갉작갉작 긁는다.","exampleSource":"표준국어대사전 용례","otherMeanings":["되는대로 자꾸 글이나 그림 따위를 쓰거나 그리는 모양."]},{"id":156,"category":"고유어","term":"짜장","definition":"과연 정말로.","example":"그는 짜장 사실인 것처럼 이야기를 한다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":157,"category":"고유어","term":"차라리","definition":"여러 가지 사실을 말할 때에, 저리하는 것보다 이리하는 것이 나음을 이르는 말. 대비되는 두 가지 사실이 모두 마땅치 않을 때 상대적으로 나음을 나타낸다.","example":"차라리 자결할망정 항복하지는 않겠다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":158,"category":"고유어","term":"차마","definition":"부끄럽거나 안타까워서 감히.","example":"차마 거절할 수 없다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":159,"category":"고유어","term":"터울","definition":"한 어머니로부터 먼저 태어난 아이와 그다음에 태어난 아이와의 나이 차이. 또는 먼저 아이를 낳은 때로부터 다음 아이를 낳은 때까지의 사이.","example":"터울이 지다.","exampleSource":"표준국어대사전 용례","otherMeanings":["‘터울거리다’의 어근."]},{"id":160,"category":"고유어","term":"감실감실","definition":"사람이나 물체, 빛 따위가 먼 곳에서 자꾸 아렴풋이 움직이는 모양.","example":"줄 끊긴 방패연은 바람에 날려 저 멀리 감실감실 사라져 갔다.","exampleSource":"표준국어대사전 용례","otherMeanings":["군데군데 약간 가무스름한 모양."]},{"id":161,"category":"고유어","term":"고분고분","definition":"말이나 행동이 공손하고 부드러운 모양.","example":"그 아이는 시키는 대로 고분고분 말을 잘 듣는다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":162,"category":"고유어","term":"미적미적","definition":"무거운 것을 조금씩 앞으로 자꾸 내미는 모양.","example":"농부가 달구지를 미적미적 밀고 간다.","exampleSource":"표준국어대사전 용례","otherMeanings":["해야 할 일이나 날짜 따위를 미루어 자꾸 시간을 끄는 모양.","자꾸 꾸물대거나 망설이는 모양."]},{"id":163,"category":"고유어","term":"부슬부슬","definition":"눈이나 비가 조용히 성기게 내리는 모양.","example":"봄비가 부슬부슬 내리다.","exampleSource":"표준국어대사전 용례","otherMeanings":["덩이진 가루 따위가 물기가 적어 잘 엉기지 못하고 부스러지기 쉬운 모양."]},{"id":164,"category":"고유어","term":"성큼성큼","definition":"다리를 잇따라 높이 들어 크게 떼어 놓는 모양.","example":"대령이 한 손을 가볍게 흔들더니 성큼성큼 대문으로 다가간다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":165,"category":"고유어","term":"아롱다롱","definition":"여러 가지 빛깔의 작은 점이나 줄 따위가 고르지 아니하고 촘촘하게 무늬를 이룬 모양.","example":"살구, 복숭아, 매화, 진달래, 개나리, 장미, 모란, 모두 아롱다롱 울긋불긋 곱고 다채로워….","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":166,"category":"고유어","term":"어슷비슷","definition":"큰 차이가 없이 서로 비슷비슷한 모양.","example":"그들은 형제도 아닌데 얼굴이 어슷비슷 닮았다.","exampleSource":"표준국어대사전 용례","otherMeanings":["이리저리 쏠리어 가지런하지 아니한 모양."]},{"id":167,"category":"고유어","term":"어슷어슷","definition":"여럿이 다 한쪽으로 조금 비뚤어진 모양.","example":"어슷어슷 누빈 옷.","exampleSource":"표준국어대사전 용례","otherMeanings":["힘없이 천천히 거니는 모양."]},{"id":168,"category":"고유어","term":"얼키설키","definition":"가는 것이 이리저리 뒤섞이어 얽힌 모양. ‘얼기설기「1」’보다 거센 느낌을 준다.","example":"얼키설키 얽힌 밧줄.","exampleSource":"표준국어대사전 용례","otherMeanings":["엉성하고 조잡한 모양. ‘얼기설기「2」’보다 거센 느낌을 준다.","관계나 일, 감정 따위가 복잡하게 얽힌 모양. ‘얼기설기「3」’보다 거센 느낌을 준다."]},{"id":169,"category":"고유어","term":"이따금","definition":"얼마쯤씩 있다가 가끔.","example":"이따금 영태가 내게 물었던 말들이 얼핏얼핏 되살아나곤 했다.","exampleSource":"교정 예문","otherMeanings":[]},{"id":170,"category":"고유어","term":"주저리주저리","definition":"너저분한 물건이 어지럽게 많이 매달려 있는 모양.","example":"주저리주저리 달리다.","exampleSource":"표준국어대사전 용례","otherMeanings":["너저분하게 이것저것 끊임없이 이야기하는 모양."]},{"id":171,"category":"고유어","term":"가늠","definition":"목표나 기준에 맞고 안 맞음을 헤아려 봄. 또는 헤아려 보는 목표나 기준.","example":"매사가 다 그렇듯이 떡 반죽도 가늠을 알맞게 해야 송편을 빚기가 좋다.","exampleSource":"표준국어대사전 용례","otherMeanings":["사물을 어림잡아 헤아림."]},{"id":172,"category":"고유어","term":"가리다","definition":"자기 일을 알아서 스스로 처리하다.","example":"그는 자기 앞도 못 가리는 처지라 결혼은 꿈도 못 꾼다.","exampleSource":"표준국어대사전 용례","otherMeanings":["보이거나 통하지 못하도록 막히다.","보이거나 통하지 못하도록 막다.","여럿 가운데서 하나를 구별하여 고르다.","낯선 사람을 대하기 싫어하다.","잘잘못이나 좋은 것과 나쁜 것 따위를 따져서 분간하다.","똥오줌을 눌 곳에 누다.","치러야 할 셈을 따져서 갚아 주다.","음식을 골라서 먹다.","머리를 대강 빗다.","곡식이나 장작 따위의 단을 차곡차곡 쌓아 올려 더미를 짓다."]},{"id":173,"category":"고유어","term":"가리사니","definition":"사물을 분간하여 판단할 수 있는 실마리.","example":"가리사니가 서다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[null] 사물을 판단할 만한 지각(知覺)."]},{"id":174,"category":"고유어","term":"갈마들다","definition":"서로 번갈아들다.","example":"낮과 밤이 갈마들다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":175,"category":"고유어","term":"갈피","definition":"일이나 사물의 갈래가 구별되는 어름.","example":"갈피를 못 잡다.","exampleSource":"표준국어대사전 용례","otherMeanings":["겹치거나 포갠 물건의 하나하나의 사이. 또는 그 틈.","[葛皮] 칡덩굴을 벗긴 껍질."]},{"id":176,"category":"고유어","term":"한들한들","definition":"가볍게 자꾸 이리저리 흔들리거나 흔들리게 하는 모양.","example":"간간이 부는 가는 바람에도 나무 끝은 한들한들 흔들린다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":177,"category":"고유어","term":"허둥지둥","definition":"정신을 차릴 수 없을 만큼 갈팡질팡하며 다급하게 서두르는 모양.","example":"허둥지둥 달아나다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":178,"category":"고유어","term":"휘뚜루마뚜루","definition":"이것저것 가리지 아니하고 닥치는 대로 마구 해치우는 모양.","example":"무계획적으로 휘뚜루마뚜루 돌아다니고 싶다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":179,"category":"고유어","term":"감돌다","definition":"어떤 기체나 기운이 가득 차서 떠돌다.","example":"계곡에 전운(戰雲)이 감돌다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[null] 어떤 둘레를 여러 번 빙빙 돌다.","[null] 생각 따위가 눈앞이나 마음속에서 사라지지 않고 자꾸 아른거리다.","[null] 길이나 물굽이 따위가 모퉁이를 따라 돌다."]},{"id":180,"category":"고유어","term":"감투","definition":"벼슬이나 직위를 속되게 이르는 말.","example":"감투가 떨어지다.","exampleSource":"표준국어대사전 용례","otherMeanings":["예전에, 머리에 쓰던 의관(衣冠)의 하나. 말총, 가죽, 헝겊 따위로 탕건과 비슷하나 턱이 없이 밋밋하게 만들었다.","‘탕건’을 속되게 이르는 말.","승려나 늙은이들이 추위를 막기 위하여 쓰는 모자의 하나. 담(毯)으로 둥글게 만들되 양옆으로 접어 올렸다가 펴서 내리면 뺨까지 가리게 된 것으로, 중국에서 전래하였다.","난간이나 대문의 기둥, 도리 따위의 꼭대기에 갓 모양으로 만들어 씌운 것.","[敢鬪] 과감히 싸움."]},{"id":181,"category":"고유어","term":"개평","definition":"노름이나 내기 따위에서 남이 가지게 된 몫에서 조금 얻어 가지는 공것.","example":"개평을 얻다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[開平] 제곱근을 계산하여 그 답을 구하는 것.","[槪評] 개략적으로 대충대충 하는 비평."]},{"id":182,"category":"고유어","term":"견주다","definition":"둘 이상의 사물을 질(質)이나 양(量) 따위에서 어떠한 차이가 있는지 알기 위하여 서로 대어 보다.","example":"나는 그와 실력을 견주기에는 부족함이 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":183,"category":"고유어","term":"고명딸","definition":"아들 많은 집의 외딸.","example":"그 집 막내는 고명딸로 태어나 오빠들 틈에서 귀염을 독차지하며 자랐다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":184,"category":"고유어","term":"꼭뒤","definition":"뒤통수의 한가운데.","example":"여인들은 머리를…꼭뒤에서 서너 번 틀어 쪽을 찌고 비녀를 꽂고, 늙으나 젊으나 꽃을 꽂았다.","exampleSource":"표준국어대사전 용례","otherMeanings":["활의 도고지가 붙은 뒤."]},{"id":185,"category":"고유어","term":"단출하다","definition":"식구나 구성원이 많지 않아서 홀가분하다.","example":"살림이 단출하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["일이나 차림차림이 간편하다."]},{"id":186,"category":"고유어","term":"버름하다","definition":"물건의 틈이 꼭 맞지 않고 조금 벌어져 있다.","example":"버름한 문틀.","exampleSource":"표준국어대사전 용례","otherMeanings":["마음이 서로 맞지 않아 사이가 뜨다."]},{"id":187,"category":"고유어","term":"빌미","definition":"재앙이나 탈 따위가 생기는 원인.","example":"빌미가 되다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":188,"category":"고유어","term":"사그라들다","definition":"삭아서 없어져 가다.","example":"장충은 제 노여움이 사그라들기를 기다리는지 몇 번이나 숨을 모았다가 다시 목소리를 평온하게 하여 길산을 다그쳤다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":189,"category":"고유어","term":"사리다","definition":"국수, 새끼, 실 따위를 동그랗게 포개어 감다.","example":"새끼를 사리다.","exampleSource":"표준국어대사전 용례","otherMeanings":["뱀 따위가 몸을 똬리처럼 동그랗게 감다.","짐승이 겁을 먹고 꼬리를 다리 사이에 구부려 끼다.","박아서 나온 못을 꼬부려 붙이다.","어떤 일에 적극적으로 나서지 않고 살살 피하며 몸을 아끼다.","정신을 바짝 가다듬다."]},{"id":190,"category":"고유어","term":"사위다","definition":"불이 사그라져서 재가 되다.","example":"숯불이 사위다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":191,"category":"고유어","term":"숫제","definition":"처음부터 차라리. 또는 아예 전적으로.","example":"하다가 말 것이라면 숫제 안 하는 것이 낫다.","exampleSource":"표준국어대사전 용례","otherMeanings":["순박하고 진실하게."]},{"id":192,"category":"고유어","term":"실마리","definition":"일이나 사건을 풀어 나갈 수 있는 첫머리.","example":"해결의 실마리가 보이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["감겨 있거나 헝클어진 실의 첫머리."]},{"id":193,"category":"고유어","term":"아련하다","definition":"똑똑히 분간하기 힘들게 아렴풋하다.","example":"그때 그 시절의 추억이 아련하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":194,"category":"고유어","term":"여의다","definition":"부모나 사랑하는 사람이 죽어서 이별하다.","example":"그는 일찍이 부모를 여의고 고아로 자랐다.","exampleSource":"표준국어대사전 용례","otherMeanings":["딸을 시집보내다.","멀리 떠나보내다."]},{"id":195,"category":"고유어","term":"우리다","definition":"어떤 물건을 액체에 담가 맛이나 빛깔 따위의 성질이 액체 속으로 빠져나오게 하다.","example":"어머니는 멸치를 우려 국물을 만드셨다.","exampleSource":"표준국어대사전 용례","otherMeanings":["더운 볕이 들다.","달빛이나 햇빛 따위가 희미하게 비치다.","꾀거나 위협하거나 하여 물품 따위를 취하다.","[null] → 후리다."]},{"id":196,"category":"고유어","term":"우수리","definition":"물건값을 제하고 거슬러 받는 잔돈.","example":"우수리는 받지 않을 테니 물건이나 좋은 것으로 주세요.","exampleSource":"표준국어대사전 용례","otherMeanings":["일정한 수나 수량에 차고 남는 수나 수량."]},{"id":197,"category":"고유어","term":"이드거니","definition":"충분한 분량으로 만족스러운 모양.","example":"바쁜 일정 때문에 부족했던 저녁 식사를 모처럼 이드거니 먹었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":198,"category":"고유어","term":"추리다","definition":"섞여 있는 것에서 여럿을 뽑아내거나 골라내다.","example":"버려진 것 중에서 쓸 만한 것을 추렸다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":199,"category":"고유어","term":"털다","definition":"자기가 가지고 있는 것을 남김없이 내다.","example":"사재를 털다.","exampleSource":"표준국어대사전 용례","otherMeanings":["달려 있는 것, 붙어 있는 것 따위가 떨어지게 흔들거나 치거나 하다.","남이 가진 재물을 몽땅 빼앗거나 그것이 보관된 장소를 모조리 뒤지어 훔치다.","일, 감정, 병 따위를 완전히 극복하거나 말끔히 정리하다."]},{"id":200,"category":"고유어","term":"허섭스레기","definition":"좋은 것이 빠지고 난 뒤에 남은 허름한 물건.","example":"이삿짐을 싸고 남은 허섭스레기.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":201,"category":"고유어","term":"홀몸","definition":"배우자나 형제가 없는 사람.","example":"사고로 아내를 잃고 홀몸이 되었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":202,"category":"고유어","term":"화수분","definition":"재물이 계속 나오는 보물단지. 그 안에 온갖 물건을 담아 두면 끝없이 새끼를 쳐 그 내용물이 줄어들지 않는다는 설화상의 단지를 이른다.","example":"은 덩이는 한번 돈으로 바꾸면 그만이지만 땅은 해마다 돈을 낳을 테니까. 그야말로 화수분이지.","exampleSource":"표준국어대사전 용례","otherMeanings":["전영택이 지은 단편 소설. 화수분 일가의 가난과 고통, 그리고 그로 인한 비극을 통하여 당시 우리 민족의 고통스러운 상황과 고통 속에서도 사라질 수 없는 따뜻한 인간애를 보여 주는 소설이다."]},{"id":203,"category":"고유어","term":"회목","definition":"손목이나 발목의 잘록한 부분.","example":"회목을 잡다.","exampleSource":"표준국어대사전 용례","otherMeanings":["강이나 길 따위에서 꺾이어 방향이 바뀌는 곳.","[檜木] 측백나뭇과의 상록 교목. 높이는 30~40미터이며, 암수한그루로 4월에 단성화가 피고 열매는 갈색의 구과(毬果)로 10월에 익는다. 목재는 질이 좋아 용도가 다양하다. 일본 특산종으로 우리나라 남부 지방에서 인공 조림으로 재배한다."]},{"id":204,"category":"고유어","term":"가녘","definition":"둘레나 끝에 해당되는 부분.","example":"겨울 안개가 바다 가녘에까지 자욱하게 끼어 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":205,"category":"고유어","term":"득달같이","definition":"잠시도 늦추지 아니하게.","example":"득달같이 달려가다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":206,"category":"고유어","term":"싹수","definition":"어떤 일이나 사람이 앞으로 잘될 것 같은 낌새나 징조.","example":"싹수가 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":207,"category":"고유어","term":"지레","definition":"어떤 일이 일어나기 전 또는 어떤 기회나 때가 무르익기 전에 미리.","example":"지레 겁을 먹다.","exampleSource":"표준국어대사전 용례","otherMeanings":["‘지렛대「1」’의 준말."]},{"id":208,"category":"고유어","term":"지지재재하다","definition":"이러니저러니 하고 자꾸 지껄이다.","example":"더 이상 지지재재할 것도 없이 두 놈이 제 딴엔 악에 받친 고함을 내지르며 몽둥이를 휘두르고 달려들었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":209,"category":"고유어","term":"짬짜미","definition":"남모르게 자기들끼리만 짜고 하는 약속이나 수작.","example":"아내의 밤늦게 돌아오는 그 일에 분명 노파의 짬짜미가 있으리라.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":210,"category":"고유어","term":"나비잠","definition":"갓난아이가 두 팔을 머리 위로 벌리고 자는 잠.","example":"팔을 어깨 위로 쳐들고 나비잠을 자던 갓난아기가 얼굴을 심하게 구기며 울기 시작했다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[나비, 簪] 날개를 편 나비 모양으로 만든 비녀. 새색시가 예장(禮裝)할 때에 머리에 덧꽂는다."]},{"id":211,"category":"고유어","term":"새우잠","definition":"새우처럼 등을 구부리고 자는 잠. 주로 모로 누워 불편하게 자는 잠을 의미한다.","example":"방바닥이 차서 웅크리고 새우잠을 잤다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":212,"category":"고유어","term":"말미","definition":"일정한 직업이나 일 따위에 매인 사람이 다른 일로 말미암아 얻는 겨를.","example":"말미가 나다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[末尾] 어떤 사물의 맨 끄트머리."]},{"id":213,"category":"고유어","term":"상글상글","definition":"눈과 입을 귀엽게 움직이며 소리 없이 정답게 자꾸 웃는 모양.","example":"손님들의 시중을 드는 것은 자그맣고 바지런한 주인아주머니였는데 철의 기억에는 언제나 상글상글 웃고 있었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":214,"category":"고유어","term":"섬뜩하다","definition":"갑자기 소름이 끼치도록 무섭고 끔찍하다.","example":"등골이 섬뜩하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":215,"category":"고유어","term":"멀거니","definition":"정신없이 물끄러미 보고 있는 모양.","example":"혼자 멀거니 앉아 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":216,"category":"고유어","term":"손사래","definition":"어떤 말이나 사실을 부인하거나 남에게 조용히 하라고 할 때 손을 펴서 휘젓는 일.","example":"손사래를 치다 거절이나 부인을 하며 손을 펴서 마구 휘젓다 .","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":217,"category":"고유어","term":"어련히","definition":"따로 걱정하지 아니하여도 잘될 것이 명백하거나 뚜렷하게. 대상을 긍정적으로 칭찬하는 뜻으로 쓰나, 때로 반어적으로 쓰여 비아냥거리는 뜻을 나타내기도 한다.","example":"아들놈 그만큼 키웠으면 이제 밥벌이야 어련히 알아서 안 할까.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":218,"category":"고유어","term":"곰살궂다","definition":"태도나 성질이 부드럽고 친절하다.","example":"곰살궂게 굴다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[null] 꼼꼼하고 자세하다."]},{"id":219,"category":"고유어","term":"수더분하다","definition":"성질이 까다롭지 아니하여 순하고 무던하다.","example":"수더분해 보이다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":220,"category":"고유어","term":"까라지다","definition":"기운이 빠져 축 늘어지다.","example":"날이 흐려서인지 몸이 까라진다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":221,"category":"고유어","term":"꼼바르다","definition":"마음이 좁고 지나치게 인색하다.","example":"꼼바르다 마음이 좁고 지나치게 인색하다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":222,"category":"고유어","term":"나부대다","definition":"얌전히 있지 못하고 철없이 촐랑거리다.","example":"그들은 무거운 짐들을 지고 종일 나부댄 탓인지 몹시 피곤했다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":223,"category":"고유어","term":"느물스럽다","definition":"말이나 행동이 능글맞은 데가 있다.","example":"느물스럽게 말하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":224,"category":"고유어","term":"떼꾼하다","definition":"눈이 쑥 들어가고 생기가 없다.","example":"떼꾼한 눈.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":225,"category":"고유어","term":"부산하다","definition":"급하게 서두르거나 시끄럽게 떠들어 어수선하다.","example":"교실 안은 많은 아이들로 매우 부산하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":226,"category":"고유어","term":"부추기다","definition":"감정이나 상황 따위가 더 심해지도록 영향을 미치다.","example":"경쟁심을 부추기다.","exampleSource":"표준국어대사전 용례","otherMeanings":["남을 이리저리 들쑤셔서 어떤 일을 하게 만들다."]},{"id":227,"category":"고유어","term":"얼뜨다","definition":"다부지지 못하여 어수룩하고 얼빠진 데가 있다.","example":"얼뜬 사람.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":228,"category":"고유어","term":"우세스럽다","definition":"남에게 놀림과 비웃음을 받을 듯하다.","example":"그런 말씀 마시오. 벌어먹고 사는 일이 우세스러울 것 조금도 없습니다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":229,"category":"고유어","term":"추저분하다","definition":"더럽고 지저분하다.","example":"모자를 쓸 때 들여다본 거울 속에 머리털이 텁수룩한 게 몹시도 추저분한 얼굴을 발견한 나는, 우선 이발소로 발길을 향하였다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":230,"category":"고유어","term":"치근덕거리다","definition":"성가실 정도로 끈덕지게 자꾸 귀찮게 굴다. ‘지근덕거리다’보다 거센 느낌을 준다.","example":"싫다는데도 자꾸만 치근덕거리는 그가 마치 한 마리 징그러운 벌레처럼 느껴졌다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":231,"category":"고유어","term":"두런두런","definition":"여럿이 나지막한 목소리로 서로 조용히 이야기하는 소리. 또는 그 모양.","example":"인부들은 이곳저곳에 모닥불을 중심으로 모여 앉아 두런두런 얘기를 주고받았다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":232,"category":"고유어","term":"볼멘소리","definition":"서운하거나 성이 나서 퉁명스럽게 하는 말투.","example":"인배의 입에서는 저도 모르게 볼멘소리가 흘러나왔다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":233,"category":"고유어","term":"맞갖다","definition":"마음이나 입맛에 꼭 맞다.","example":"마음에 맞갖지 않은 일자리라서 거절하였다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":234,"category":"고유어","term":"푸지다","definition":"매우 많아서 넉넉하다.","example":"푸지게 먹다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":235,"category":"고유어","term":"한소끔","definition":"한 번 끓어오르는 모양.","example":"밥이 한소끔 끓다.","exampleSource":"표준국어대사전 용례","otherMeanings":["일정한 정도로 한 차례 진행되는 모양."]},{"id":236,"category":"고유어","term":"비설거지","definition":"비가 오려고 하거나 올 때, 비에 맞으면 안 되는 물건을 치우거나 덮는 일.","example":"무시래기와 고구마 넝쿨을 툇마루에 올려놓는 것 외에는 달리 비설거지를 할 만한 게 없었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":237,"category":"고유어","term":"노상","definition":"언제나 변함없이 한 모양으로 줄곧.","example":"그는 노상 웃고 다닌다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[老相] 늙은 재상.","[勞傷] 갖은 고초로 마음에 상처를 입음.","[路上] 길의 바닥 표면.","[路上] 길거리나 길의 위.","[路床] 표층과 노반(路盤)을 통하여 확대된 면적에 분포하는 하중을 안전하게 지지하는 아랫부분.","[魯桑] 뽕나뭇과의 낙엽 교목. 높이는 5~7미터이며, 잎은 각 마디에서 한 개씩 어긋나고 심장 모양이다. 가지는 다른 뽕나무보다 굵고 각 마디에서 꺾어지면서 반대쪽으로 구부러진다. 5월에 수상(穗狀) 화서로 꽃이 피고 열매는 6~7월에 검게 익는다. 관상용으로도 재배하며 잎은 누에의 먹이로 쓴다.","[露霜] 이슬과 서리를 아울러 이르는 말."]},{"id":238,"category":"고유어","term":"자못","definition":"생각보다 매우.","example":"여러분에 대한 기대가 자못 큽니다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":239,"category":"고유어","term":"좀체","definition":"여간하여서는.","example":"일자리가 좀체 구해지지 않는가 봐요.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":240,"category":"고유어","term":"알싸하다","definition":"매운맛이나 독한 냄새 따위로 코 속이나 혀끝이 알알하다.","example":"고추가 매워 혀끝이 알싸하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":241,"category":"고유어","term":"함함하다","definition":"털이 보드랍고 반지르르하다.","example":"털이 함함한 강아지.","exampleSource":"표준국어대사전 용례","otherMeanings":["소담하고 탐스럽다.","[顑頷, 하다] 몹시 굶주려 부황이 나서 누르퉁퉁하다."]},{"id":242,"category":"고유어","term":"호젓하다","definition":"매우 홀가분하여 쓸쓸하고 외롭다.","example":"호젓한 시간.","exampleSource":"표준국어대사전 용례","otherMeanings":["후미져서 무서움을 느낄 만큼 고요하다."]},{"id":243,"category":"한자어","term":"간발","definition":"아주 잠시 또는 아주 적음을 이르는 말.","example":"벌써 그의 가슴으로 간발의 틈을 노린 칼끝이 닿고 있었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[簡拔] 여러 사람 가운데 골라 뽑음."]},{"id":244,"category":"한자어","term":"개재","definition":"어떤 것들 사이에 끼여 있음.","example":"사적 감정의 개재가 이 일의 변수이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[開齋] 단식재와 금육재 기간이 지남."]},{"id":245,"category":"한자어","term":"개정","definition":"주로 문서의 내용 따위를 고쳐 바르게 함.","example":"헌법 개정.","exampleSource":"표준국어대사전 용례","otherMeanings":["[介淨] ‘개정하다01’의 어근.","[改定] 이미 정하였던 것을 고쳐 다시 정함.","[改訂] 글자나 글의 틀린 곳을 고쳐 바로잡음.","[開廷] 법정을 열어 재판을 시작하는 일. 재판은 법정에서 하는 것이 원칙이지만 필요할 때 법원장의 권한으로 법원 외의 장소에서 행할 수 있다.","[開定] 선정(禪定)의 상태에서 나옴.","[開政] 정무를 보기 시작함.","[開政] 벼슬아치들의 인사에 관한 정사를 시작함."]},{"id":246,"category":"한자어","term":"결부","definition":"일정한 사물이나 현상을 서로 연관시킴.","example":"그 두 문제는 매우 밀접히 결부되어 있다.","exampleSource":"제공 자료 예문","otherMeanings":["[結負] ‘결복01「2」’의 원말.","[結簿] 조선 시대에, 논밭의 결(結)에 따라 토지세를 거두어들일 때 쓰던 장부."]},{"id":247,"category":"한자어","term":"결재","definition":"결정할 권한이 있는 상관이 부하가 제출한 안건을 검토하여 허가하거나 승인함.","example":"결재 서류.","exampleSource":"표준국어대사전 용례","otherMeanings":["[潔齋] 주색을 금하고 언행을 조심하여 몸과 마음을 깨끗이 함."]},{"id":248,"category":"한자어","term":"계제","definition":"어떤 일을 할 수 있게 된 형편이나 기회.","example":"변명할 계제가 없었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[計除] 셈을 따져서 제할 것을 제함.","[階除] 걸어서 층 사이를 오르내릴 수 있도록 턱이 지게 만들어 놓은 설비.","[階梯] 사다리라는 뜻으로, 일이 되어 가는 순서나 절차를 비유적으로 이르는 말.","[階梯] 기계 체조에 사용하는, 옆으로 비스듬히 세운 사다리."]},{"id":249,"category":"한자어","term":"곤혹","definition":"곤란한 일을 당하여 어찌할 바를 모름.","example":"예기치 못한 질문에 곤혹을 느끼다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":250,"category":"한자어","term":"공표","definition":"여러 사람에게 널리 드러내어 알림.","example":"학회는 결정적 증거가 나오기 전까지 새 학설의 공표를 미루기로 결정하였다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[空表] 기계의 구조가 단순한, 구식 회중시계의 하나.","[空票] 값을 치르지 않고 거저 얻은 입장권이나 차표.","[空票] 추첨 따위에서 아무런 배당이 없는 표.","[空標] 동그랗게 그려서 옳거나 맞음을 나타내는 ‘○’의 이름."]},{"id":251,"category":"한자어","term":"관건","definition":"어떤 사물이나 문제 해결의 가장 중요한 부분.","example":"문제 해결의 관건을 쥐다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[綸巾] 비단으로 만든 두건.","[關鍵] 문빗장과 자물쇠를 아울러 이르는 말."]},{"id":252,"category":"한자어","term":"면목","definition":"남을 대할 만한 체면.","example":"면목을 세우다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[面目] 얼굴의 생김새.","[面目] 사람이나 사물의 겉모습."]},{"id":253,"category":"한자어","term":"모략","definition":"사실을 왜곡하거나 속임수를 써 남을 해롭게 함. 또는 그런 일.","example":"모략에 빠지다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[謀略] 계책이나 책략."]},{"id":254,"category":"한자어","term":"백미","definition":"흰 눈썹이라는 뜻으로, 여럿 가운데에서 가장 뛰어난 사람이나 훌륭한 물건을 비유적으로 이르는 말. 중국 촉한(蜀漢) 때 마씨(馬氏) 다섯 형제가 모두 재주가 있었는데 그중에서도 눈썹 속에 흰 털이 난 마량(馬良)이 가장 뛰어났다는 데서 유래한다.","example":"백미로 꼽다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[白米] 희게 쓿은 멥쌀.","[白薇] 박주가릿과의 여러해살이풀. 높이는 50~80cm이고 곧게 서며 가지를 치지 않는데 전체에 털이 많다. 잎은 마주나고 끝이 뾰족한 긴 타원형 또는 달걀 모양이다. 초여름에 자주색 꽃이 산형(繖形) 화서로 피고 열매는 골돌과(蓇葖果)이다. 잎과 뿌리는 약재로 쓴다. 산과 들에 저절로 나는데 한국, 일본 등지에 분포한다.","[白薇] 백미꽃의 뿌리를 한방에서 이르는 말. 성질이 차서 열을 내리고 피를 시원하게 하여 골증열이나 산후 발열에 쓴다.","[百味] 온갖 맛있는 음식물.","[百媚] 사람의 마음을 홀리는 온갖 아름다운 태도."]},{"id":255,"category":"한자어","term":"보전","definition":"온전하게 보호하여 유지함.","example":"생태계 보전.","exampleSource":"표준국어대사전 용례","otherMeanings":["[甫田] 큰 밭.","[甫田] ≪시경≫의 편명(篇名).","[補塡] 부족한 부분을 보태어 채움.","[補箋] 어떤 서류에 간단한 의견을 적어서 덧붙이는 쪽지.","[補箋] 유가 증권이나 증서에 배서(背書)와 보증이 많아 여백이 없는 경우에 덧붙이는 종이.","[寶典] 귀중한 법전(法典).","[寶典] 귀중한 책.","[寶殿] 부처를 모셔 두는 건물."]},{"id":256,"category":"한자어","term":"비견","definition":"앞서거나 뒤서지 않고 어깨를 나란히 한다는 뜻으로, 낫고 못할 것이 없이 정도가 서로 비슷하게 함을 이르는 말.","example":"그는 톨스토이에 비견할 만한 소설가이다.","exampleSource":"교정 예문","otherMeanings":["[鄙見] 자신의 의견을 겸손하게 이르는 말."]},{"id":257,"category":"한자어","term":"산실","definition":"어떤 일을 꾸미거나 이루어 내는 곳. 또는 그런 바탕.","example":"우리 연구부를 기술 개발의 산실로 키우겠다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[産室] 해산하는 방.","[散失] 흩어져 잃어버림."]},{"id":258,"category":"한자어","term":"서광","definition":"좋은 일이 일어날 조짐.","example":"암울한 역사는 가고 이제 서광의 시대가 열릴 것이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[西光] 서방 정토의 부처의 빛. 항상 광명이 비친다.","[胥匡] 틀린 점을 서로 고쳐 줌.","[書狂] 어떤 부문의 학문을 연구하기 위해서가 아니라 단순히 취미로 책을 사들이는 버릇이 있는 사람.","[瑞光] 상서로운 빛.","[曙光] 새벽에 동이 틀 무렵의 빛.","[曙光] 기대하는 일에 대하여 나타난 희망의 징조를 비유적으로 이르는 말.","[曙光] 1919년에 창간된 종합 월간지. 오천석ㆍ오상순ㆍ이병도ㆍ장덕수 등이 집필한 것으로, 당시 일어났던 신문예 운동에 기여하였다."]},{"id":259,"category":"한자어","term":"슬하","definition":"무릎의 아래라는 뜻으로, 어버이나 조부모의 보살핌 아래. 주로 부모의 보호를 받는 테두리 안을 이른다.","example":"슬하에 자녀는 몇이나 두었소?","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":260,"category":"한자어","term":"아성","definition":"아주 중요한 근거지를 비유적으로 이르는 말.","example":"아성이 무너지다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[牙城] 아기(牙旗)를 세운 성이라는 뜻으로, 주장(主將)이 거처하는 성을 이르던 말.","[牙聲] 훈민정음에서 ‘ㄱ’, ‘ㄲ’, ‘ㆁ’, ‘ㅋ’을 이르는 말.","[亞聖] 유학에서 공자 다음가는 성인(聖人)이라고 하여 ‘맹자01’를 이르는 말.","[兒聲] 어린아이의 소리.","[兒聲] 유치한 말을 비유적으로 이르는 말."]},{"id":261,"category":"한자어","term":"염치","definition":"체면을 차릴 줄 알며 부끄러움을 아는 마음.","example":"예의와 염치에 어긋나다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":262,"category":"한자어","term":"유례","definition":"이전부터 있었던 사례.","example":"역사상 유례가 없는 이변.","exampleSource":"표준국어대사전 용례","otherMeanings":["[流例] 널리 전하여 오는 예.","[謬例] 잘못된 예.","[類例] 같거나 비슷한 예."]},{"id":263,"category":"한자어","term":"자청","definition":"어떤 일에 나서기를 스스로 청함.","example":"그는 그 일을 맡겠다고 자청을 하고 나섰다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[刺靑] 바늘로 찔러서 먹물 따위를 들인 글씨나 그림, 무늬. 또는 그렇게 한 물체.","[刺靑] 얼굴이나 팔뚝의 살을 따고 홈을 내어 먹물로 죄명을 찍어 넣던 벌."]},{"id":264,"category":"한자어","term":"장족","definition":"사물의 발전이나 진행이 매우 빠름.","example":"장족의 발전.","exampleSource":"표준국어대사전 용례","otherMeanings":["[杖足] 몽둥이로 발을 치던 형벌.","[長足] 기다랗게 생긴 다리.","[獐足] 과녁에 박힌 화살을 뽑는 도구. 노루발처럼 끝이 갈라지게 쇠붙이로 만들었다."]},{"id":265,"category":"한자어","term":"진수","definition":"사물이나 현상의 가장 중요하고 본질적인 부분.","example":"사상의 진수.","exampleSource":"표준국어대사전 용례","otherMeanings":["[辰宿] 모든 별자리의 별들.","[珍秀] ‘진수하다01’의 어근.","[珍羞] 진귀하고 맛이 좋은 음식.","[珍獸] 세상에 드문 진기한 짐승.","[眞水] 다른 것이 섞이지 아니한 순수한 물.","[眞修] 천태종에서, 초지(初地) 이상의 보살이 행하는 관법(觀法) 수행. 수행하려는 별다른 생각 없이 스스로 이치를 깨달아 행하는 수행이다.","[眞數] 로그 '<img style=\"vertical-align: middle;\" src='http://stdmgt.korean.go.kr:8899/dictionary/compilation/popup/formula.do?latex=log_%7B0%7D+x'>'에서 양수 <I>x</I>를 이르는 말.","[陳壽] 중국 서진(西晉)의 역사가(233~297). 자는 승조(承祚). 삼국 시대에 촉나라를 섬기었으나, 후에 진(晉)나라에 봉사하였다. 중국 정사(正史)의 하나인 ≪삼국지≫를 편찬하였다.","[軫宿] 이십팔수의 스물여덟째 별자리.","[進水] 새로 만든 배를 조선대에서 처음으로 물에 띄움.","[進修] 덕과 학문을 닦음.","[進修] 이전보다 나아지고 좋아짐.","[塵數] 먼지의 수라는 뜻으로, 많은 수를 이르는 말.","[盡數] 수량의 전부.","[螓首] 저녁매미의 이마라는 뜻으로, 아름다운 용모를 이르는 말.","[鎭守] 군대를 주둔하여 군사적으로 중요한 곳을 지킴.","[鎭戍] 변경(邊境)을 지킴."]},{"id":266,"category":"한자어","term":"가관","definition":"경치 따위가 꽤 볼만함.","example":"내장산의 단풍은 참으로 가관이지.","exampleSource":"표준국어대사전 용례","otherMeanings":["[加冠] 성년식인 관례를 치르며 갓을 처음 쓰는 일.","[可觀] 꼴이 볼만하다는 뜻으로, 남의 언행이나 어떤 상태를 비웃는 뜻으로 이르는 말.","[假官] 조선 시대에, 관제 운용에서 정원 외에 추가로 임용하거나, 중요 관직에 결원이 생겼을 경우 타관이 겸임하던 임시 관직.","[假官] 조선 시대에, 승정원에 속한 정칠품 벼슬. 주서(注書)가 사고를 당할 때에 그 일을 대신 맡아보게 하기 위하여 정원(定員) 이외로 두었다.","[假觀] 삼관(三觀)의 하나. 우주의 모든 존재는 공(空)한 것으로서 실제로 있는 것이 아니므로, 모양을 분명히 갖춘 것도 실체가 없는 임시적인 존재라는 것이다.","[笳管] 속이 빈 대에 구멍을 뚫고 불어서 소리를 내는 악기를 통틀어 이르는 말.","[歌管] 노래와 악기를 아울러 이르는 말."]},{"id":267,"category":"한자어","term":"각서","definition":"약속을 지키겠다는 내용을 적은 문서.","example":"각서를 받다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[角黍] 웃기떡의 하나. 찹쌀가루에 대추를 이겨 섞고 꿀에 반죽하여 깨소나 팥소를 넣어 송편처럼 만든 다음, 기름에 지진다.","[覺書] 조약에 덧붙여 해석하거나 보충할 것을 정하고, 예외 조건을 붙이거나 자기 나라의 의견, 희망 따위를 진술하는 외교 문서. 조약보다는 강제성이 약하여 비교적 가벼운 의미로 사용된다."]},{"id":268,"category":"한자어","term":"각축","definition":"서로 이기려고 다투며 덤벼듦.","example":"외세의 각축.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":269,"category":"한자어","term":"간과하다","definition":"큰 관심 없이 대강 보아 넘기다.","example":"나는 그가 따라 주는 술을 마시면서도 그 사실을 결코 간과하지 않았다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":270,"category":"한자어","term":"회자","definition":"회와 구운 고기라는 뜻으로, 칭찬을 받으며 사람의 입에 자주 오르내림을 이르는 말.","example":"그 노래는 오늘날까지 많은 사람 사이에 널리 회자되고 있다.","exampleSource":"교정 예문","otherMeanings":["[回刺] 승문원에 새로 들어온 사람이 허름한 차림을 하고 밤에 선배들을 찾아다니며 동료로 인정받던 일.","[會子] 중국 당나라 말기부터 금융업자들이 일정한 지역에서 통용하던 약속 어음. 송나라 때에는 정부에서 관자(官子)로서 발행하였다.","[劊子] 군영(軍營)에서 사형을 집행하던 사람."]},{"id":271,"category":"한자어","term":"감퇴","definition":"기운이나 세력 따위가 줄어 쇠퇴함.","example":"식욕 감퇴.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":272,"category":"한자어","term":"강변","definition":"이치에 닿지 아니한 것을 끝까지 굽히지 않고 주장하거나 변명함.","example":"광신의 열정과 독선의 강변으로만 무장된 서로 다른 이념의 만남은 이 땅을 소란스러운 심리적 폭력의 경쟁 터로 만들었다가 마침내는 유혈의 대결로 끝장을 보고 말았다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[江邊] 강의 가장자리에 잇닿아 있는 땅. 또는 그 부근.","[剛辯] ‘강변하다01’의 어근."]},{"id":273,"category":"한자어","term":"개관","definition":"전체를 대강 살펴봄. 또는 그런 것.","example":"국문학사의 개관.","exampleSource":"표준국어대사전 용례","otherMeanings":["[改棺] 무덤을 옮길 때 관을 새로 마련함.","[開棺] 시체가 들어 있는 관의 뚜껑을 엶.","[開管] 양쪽 끝이 뚫리고 속이 빈 관. 한쪽 끝에 진동하는 음차(音叉)를 가까이 대거나 공기를 불어 넣으면 내부의 공기 기둥의 진동으로 소리가 난다.","[開館] 도서관, 영화관, 박물관, 회관 따위의 기관이 설비를 차려 놓고 처음으로 문을 엶. 또는 그렇게 함.","[開館] 도서관, 영화관, 박물관, 회관 따위가 그날의 일을 시작하기 위하여 문을 엶. 또는 그렇게 함.","[開關] 관문(關門), 성문(城門), 세관(稅關) 따위를 엶.","[蓋棺] 시체를 관에 넣고 뚜껑을 덮음.","[漑灌] 농사를 짓는 데에 필요한 물을 논밭에 댐.","[槪觀] 윤곽, 명암, 색채, 구도 따위의 대체의 모양."]},{"id":274,"category":"한자어","term":"객기","definition":"객쩍게 부리는 혈기(血氣)나 용기.","example":"객기가 나다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":275,"category":"한자어","term":"거치","definition":"공채(公債), 사채(社債) 따위의 상환 또는 지급을 일정 기간 하지 않는 일.","example":"3년 거치 5년 상환 조건으로 돈을 융자하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[据置] 그대로 둠.","[鋸齒] 톱 따위의 가장자리에 있는 뾰족뾰족한 이.","[鋸齒] 식물의 잎이나 꽃잎 가장자리에 있는, 톱니처럼 깔쭉깔쭉하게 베어져 들어간 자국.","[擧痔] 항문 주위에 군살이 생겨서 아픈 치질."]},{"id":276,"category":"한자어","term":"건재","definition":"힘이나 능력이 줄어들지 않고 여전히 그대로 있음.","example":"건재를 과시하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[建材] ‘건축 용재’를 줄여 이르는 말.","[乾才] 맡은 일을 감당하며 처리하는 재주.","[乾材] 조제하지 않은 그대로의 약재."]},{"id":277,"category":"한자어","term":"검수","definition":"물건의 규격, 수량, 품질 따위를 검사한 후 물건을 받음.","example":"검수 기간.","exampleSource":"표준국어대사전 용례","otherMeanings":["[劍樹] 가지, 잎, 꽃, 과실이 모두 칼로 되어 있다는 지옥의 나무.","[劍樹] 불경, 불효, 무자비한 죄를 지은 사람이 떨어지는 지옥. 시뻘겋게 단 뜨거운 쇠 알의 열매가 달리고 잎이 칼로 된 나무 숲속에서 온몸이 찔리는 고통을 받는다.","[黔首] 검은 두건을 쓴 머리라는 뜻으로, 일반 백성을 비유적으로 이르는 말. 고대 중국에서 평민들이 머리에 검은 두건을 쓴 데서 비롯된 말이다.","[檢水] 수질이 좋은지 나쁜지를 검사하는 일.","[檢修] 점검하여 수리함.","[檢數] 물건의 개수를 헤아려 검사하는 일."]},{"id":278,"category":"한자어","term":"경륜","definition":"일정한 포부를 가지고 일을 조직적으로 계획함. 또는 그 계획이나 포부.","example":"경륜이 있는 사람.","exampleSource":"표준국어대사전 용례","otherMeanings":["[徑輪] 지름과 둘레를 아울러 이르는 말.","[徑輪] 토지의 지름과 둘레. 또는 토지의 면적.","[經綸] 세상을 다스림. 또는 그런 능력.","[競輪] 일정한 거리를 자전거를 타고 달려 빠르기를 겨루는 경기.","[競輪] 가장 빨리 달릴 것이라고 예상하는 자전거에 돈을 걸어 내기를 하는 오락."]},{"id":279,"category":"한자어","term":"경색","definition":"소통되지 못하고 막힘.","example":"정국 경색을 풀다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[哽塞] 지나치게 소리를 내어 울어 목이 막힘.","[梗塞] 혈액 속에 떠다니는 혈전(血栓) 따위의 물질이 혈관을 막는 일. 이로 인하여 혈액 순환이 잘되지 않아 영양 공급이 중단되며 그 부위의 세포 조직이 죽게 된다.","[景色] 산이나 들, 강, 바다 따위의 자연이나 지역의 모습.","[景色] 정경이나 광경."]},{"id":280,"category":"한자어","term":"경시","definition":"대수롭지 않게 보거나 업신여김.","example":"인명(人命) 경시 현상.","exampleSource":"표준국어대사전 용례","otherMeanings":["[更始] 고쳐 다시 시작함.","[庚時] 이십사시(二十四時)의 열여덟째 시. 오후 네 시 반부터 다섯 시 반까지이다.","[京試] 조선 시대에, 3년마다 서울에서 치러 생원과 진사를 뽑던 소과(小科)의 첫 시험.","[勁矢] 강한 화살.","[卿寺] 조선 시대에, 구경(九卿)이 있던 중앙 관아.","[經始] 집을 짓기 시작함.","[經始] 경영에 착수함.","[警視] 대한 제국 때에, 경시청과 각 도(道)의 관찰부에 속한 경찰 고등관(高等官). 이전의 경무관(警務官)을 고친 것이다.","[警視] 일제 강점기에 둔, 지금의 총경(總警)에 해당하는 경찰관의 계급."]},{"id":281,"category":"한자어","term":"경주","definition":"힘이나 정신을 한곳에만 기울임.","example":"좋은 결과를 거둘 수 있도록 그 일에 최선의 노력이 경주되어야 한다.","exampleSource":"제공 자료 예문","otherMeanings":["[勁酒] 독한 술.","[傾注] 물 따위를 기울여 붓거나 쏟음.","[傾注] 강물이 쏜살같이 바다로 흘러 들어감.","[傾注] 비가 퍼붓듯 쏟아지는 것을 비유적으로 이르는 말.","[輕舟] 가볍고 빠른 작은 배.","[慶州] 경상북도의 동남부에 있는 시. 신라 천 년의 고도(古都)로 명승고적이 많아 관광 명소이다. 제삼차 산업과 농업이 주요 산업이며 특산물로 유기, 죽세공품 따위가 있다. 불국사, 석굴암, 분황사와 그 밖에도 많은 명승지가 있다. 1995년 행정 구역 개편 때 경주군을 통합하여 도농 복합 형태의 시를 이루었다. 면적은 1,324.08㎢.","[慶州] 중국 요나라 때의 주. 현재 네이멍구 자치구인 바린쭤치(巴林左旗)의 서북부에 있었다. 불탑인 백탑(白塔)과 영경릉의 벽화는, 현존하는 뛰어난 요나라 건축ㆍ회화 작품이다.","[瓊州] → 충저우.","[競舟] 정해진 거리에서 보트를 저어 스피드를 겨루는 경기. 혼자서 젓는 싱글 스컬에서 8명이 젓는 에이트까지 9종목이 있는데, 올림픽에서 남자는 2,000미터, 여자는 1,000미터 코스에서 실시한다.","[競走] 사람, 동물, 차량 따위가 일정한 거리를 달려 빠르기를 겨루는 일. 또는 그런 경기."]},{"id":282,"category":"한자어","term":"경질","definition":"어떤 직위에 있는 사람을 다른 사람으로 바꿈.","example":"임원 경질.","exampleSource":"표준국어대사전 용례","otherMeanings":["[勁疾] ‘경질하다02’의 어근.","[硬質] 단단하고 굳은 성질.","[經帙] 고려 시대에, 경권(經卷)을 말아 두는 데 쓰던 물건. 가느다란 참대 조각을 짜서 직사각형의 대자리처럼 만들고 그 한쪽에 삼각형의 비단을 붙여 줄을 단 것으로, 현재 전라남도 순천시 송광면 송광사에 있다."]},{"id":283,"category":"한자어","term":"계류","definition":"일정한 곳을 벗어나지 못하도록 배를 말뚝에 매는 일.","example":"선박 혼잡 등에 의한 장기간의 계류가 아닌 한, 비용은 그다지 큰 문제가 되지 않는다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[溪流, /, 谿流] 산골짜기에 흐르는 시냇물.","[稽留] 객지에 가서 머물러 있음.","[繫留] 일정한 곳을 벗어나지 못하도록 밧줄 같은 것으로 붙잡아 매어 놓음.","[繫留] 어떤 사건이 해결되지 않고 걸려 있음.","[繫留] 한 화음으로부터 다른 화음으로 옮길 때, 그 가운데 어느 한 성음 또는 몇 개의 성음이 다른 화음으로 늦게 들어가서 안어울림음을 이루는 일."]},{"id":284,"category":"한자어","term":"고견","definition":"뛰어난 의견이나 생각.","example":"그 사람의 정치적 판단은 당시의 고견이었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[高見] 남의 의견을 높여 이르는 말.","[顧見] 돌이켜 봄.","[顧見] 마음을 기울여 돌보아 줌."]},{"id":285,"category":"한자어","term":"고적","definition":"북과 피리를 아울러 이르는 말.","example":"고적을 울리다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[古跡, /, 古蹟] 옛 문화를 보여 주는 건물이나 터.","[考績] 고려ㆍ조선 시대에, 관리의 근무 성적을 평가하여 결정하던 일. 승진과 좌천, 포상과 처벌에 반영하였다.","[孤寂] 외롭고 쓸쓸함.","[故敵] 옛날의 적.","[高適] 고려 시대의 문신(?~?). 삼별초의 난이 평정되자 유총관(留摠官)에 임명되어 탐라 백성을 다스렸다.","[高適] 중국 당나라의 시인(707?~765). 자는 달부(達夫). 벼슬은 감찰어사ㆍ절도사를 지냈으며, 잠참과 더불어 변경(邊境)의 풍물을 읊었다.","[高積] 높이 쌓임."]},{"id":286,"category":"한자어","term":"고증","definition":"예전에 있던 사물들의 시대, 가치, 내용 따위를 옛 문헌이나 물건에 기초하여 증거를 세워 이론적으로 밝힘.","example":"왕궁이 철저한 문헌의 고증을 통해 복원되었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":287,"category":"한자어","term":"고착","definition":"어떤 상황이나 현상이 굳어져 변하지 않음.","example":"분단의 고착을 막고 통일을 앞당기려는 노력이 필요하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[固着] 물건 같은 것이 굳게 들러붙어 있음.","[固着] 특정한 대상이나 생각에 집착하여 벗어나지 못함. 또는 그런 상태. 이전의 발달 단계에서 적절했던 대상이나 생각이, 발달이 진행되어 다른 생각이나 행동이 요구되는데도 그 이전의 상태에 머무르는 일이다.","[固着] 정신 분석학에서, 성욕이 발달하지 못하여 어린애 때의 사랑의 대상에서 떠나지 못함. 또는 그런 상태."]},{"id":288,"category":"한자어","term":"고찰","definition":"어떤 것을 깊이 생각하고 연구함.","example":"한국 문학에 대한 새로운 고찰.","exampleSource":"표준국어대사전 용례","otherMeanings":["[古刹] 역사가 오래된 옛 절.","[高札] 입찰액 가운데서 가장 높은 가격.","[高札] 상대편의 편지를 높여 이르는 말.","[高札] 예전에, 널리 알리는 글을 써서 붙이던 널빤지.","[高察] 남의 고찰(考察)을 높여 이르는 말."]},{"id":289,"category":"한자어","term":"곡진하다","definition":"매우 정성스럽다.","example":"곡진한 사랑.","exampleSource":"표준국어대사전 용례","otherMeanings":["[曲盡, 하다] 매우 자세하고 간곡하다."]},{"id":290,"category":"한자어","term":"공방","definition":"서로 공격하고 방어함.","example":"공방을 벌이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[工房] 조선 시대에, 승정원에 속한 육방(六房) 가운데 공예ㆍ건축ㆍ토목 공사 따위에 관한 일을 맡아보던 부서.","[工房] 조선 시대에, 각 지방 관아에 속한 육방(六房) 가운데 공예ㆍ건축ㆍ토목ㆍ공사 따위에 관한 일을 맡아보던 부서.","[工房] 조선 시대에, 각 지방 관아의 공방(工房)에 속하여 공전(工典)에 관한 일을 맡아보던 구실아치.","[工房] 공예품 따위를 만드는 곳.","[公方] ‘공방하다01’의 어근.","[孔方] ‘엽전’을 달리 이르는 말. 엽전의 가운데 네모난 구멍이 있으므로 이렇게 이른다.","[空房] 사람이 들지 않거나 거처하지 않는 방.","[空房] 오랫동안 남편 없이 아내 혼자서 거처하는 방.","[貢房] 조선 후기에, 지방 백성을 대신하여 나라에 공물을 바치고 나중에 그 비용과 이자를 합하여 값을 받던 곳."]},{"id":291,"category":"한자어","term":"공상","definition":"현실적이지 못하거나 실현될 가망이 없는 것을 막연히 그리어 봄. 또는 그런 생각.","example":"공상에 빠지다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[工商] 공업과 상업을 아울러 이르는 말.","[工商] 물건을 만들거나 파는 일에 종사하는 사람.","[公相] 삼공(三公)과 재상(宰相)을 아울러 이르는 말.","[公相] 최고의 벼슬.","[公傷] 공무(公務)로 인하여 입은 상처.","[功狀] 구체적인 공적(功績).","[共相] 여러 가지 사물에 공통되는 모양.","[供上] 물건 따위를 상급 관청이나 궁중, 또는 임금에게 바치던 일.","[空床] 팔걸이와 등받이가 없는 의자.","[空相] 만물의 실체가 없는 모양.","[貢上] 나라에 특산물을 바치던 일."]},{"id":292,"category":"한자어","term":"공활하다","definition":"텅 비고 매우 넓다.","example":"공활한 가을 하늘.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":293,"category":"한자어","term":"교착","definition":"어떤 상태가 굳어 조금도 변동이나 진전이 없이 머묾.","example":"교착 국면.","exampleSource":"표준국어대사전 용례","otherMeanings":["[交着] 서로 붙음.","[交錯] 이리저리 엇갈려 뒤섞임.","[膠着] 아주 단단히 달라붙음."]},{"id":294,"category":"한자어","term":"구금","definition":"피고인 또는 피의자를 구치소나 교도소 따위에 가두어 신체의 자유를 구속하는 강제 처분. 형이 확정되지 않은 사람에 대하여 집행하며, 형이 확정되면 구금 일수를 계산하여 형을 집행한 것과 동일하게 취급한다.","example":"그는 지금 그리 명예스럽지도 못한 일로 구금이 되어 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[九禁] 아홉 겹의 금문(禁門)이라는 뜻으로, 대궐을 이르는 말.","[口金] 전구의 소켓에 있는, 금속으로 이루어진 부분.","[口琴] 아시아나 태평양의 여러 섬에서 사용하는 원시적인 소형 악기의 하나. 대나무 가운데를 가늘게 쪼개어 리드를 끼워 입에 물고 연주하는데, 쇠로 만든 것도 있다.","[口噤] 입을 꼭 다물고 벌리지 못하는 중풍 증상."]},{"id":295,"category":"한자어","term":"구분","definition":"일정한 기준에 따라 전체를 몇 개로 갈라 나눔.","example":"구분을 짓다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[口分] 사람마다 똑같이 나누어 줌.","[口分] 관아에서 식구의 수효에 따라 내어 주던 양식.","[丘墳] 송장이나 유골을 땅에 묻어 놓은 곳. 흙으로 둥글게 쌓아 올리기도 하고 돌로 평평하게 만들기도 하는데, 대개 묘석을 세워 누구의 것인지 표시한다.","[丘墳] 땅이 비탈지고 조금 높은 곳.","[狗糞] 개의 똥.","[俱焚] 한꺼번에 불에 탐."]},{"id":296,"category":"한자어","term":"구비","definition":"있어야 할 것을 빠짐없이 다 갖춤.","example":"구비 서류.","exampleSource":"표준국어대사전 용례","otherMeanings":["[口碑] 비석에 새긴 것처럼 오래도록 전해 내려온 말이라는 뜻으로, 예전부터 말로 전하여 내려온 것을 이르는 말. 주로 서민들 사이에서 전해 내려온 것을 이른다.","[廏肥] 외양간에서 쳐낸 두엄.","[糗糒] 먼 길을 가는 데 지니고 다니기 쉽게 만든 양식.","[糗糒] 흉년이 들어 곤궁한 사람들을 구호할 때에, 죽을 쑤어 주지 않고 대신 주던 곡식.","[糗糒] 중국에 가는 사신이 가지고 가던 양식.","[鼽鼻] 코가 막히거나 맑은 콧물이 자꾸 흐르는 콧병. 급성 코염에 속한다."]},{"id":297,"category":"한자어","term":"구제","definition":"자연적인 재해나 사회적인 피해를 당하여 어려운 처지에 있는 사람을 도와줌.","example":"구제 기관.","exampleSource":"표준국어대사전 용례","otherMeanings":["[舅弟] 외사촌 형제.","[舊制] 이전의 제도.","[舊製] 옛적에 만듦. 또는 그런 물건.","[舊題] 새로 붙인 제목 이전에 원래 쓰던 제목.","[驅除] 해충 따위를 몰아내어 없앰."]},{"id":298,"category":"한자어","term":"구조","definition":"부분이나 요소가 어떤 전체를 짜 이룸. 또는 그렇게 이루어진 얼개.","example":"가옥 구조.","exampleSource":"표준국어대사전 용례","otherMeanings":["[九條] 베 아홉 폭을 가로 꿰매어 만든 가사. 주로 외출할 때나 법회 때에 입는다.","[久阻] 소식이 오랫동안 막힘.","[口調] 말의 가락.","[狗蚤] 벼룩과의 곤충. 사람벼룩과 비슷한데 길이는 1.7~3.4mm이다. 벼룩보다 크나 뛰는 힘은 약하다. 주로 개의 몸에 붙어 기생한다.","[救助] 재난 따위를 당하여 어려운 처지에 빠진 사람을 구하여 줌.","[舅祖] 아버지의 외숙부.","[鉤爪] 갈고리 모양으로 생긴 새의 발톱.","[鉤爪] 끝이 뾰족하고 꼬부라진 물건. 흔히 쇠로 만들어 물건을 걸고 끌어당기는 데 쓴다.","[構造] 일정한 설계에 따라 여러 가지 재료를 얽어서 만든 물건. 건물, 다리, 축대, 터널 따위가 있다.","[構造] 탁상, 섬유상 따위와 같은 광물의 형태.","[構造] 집합과 거기에서 정하여진 연산이나 집합과 거기에서 정해진 관계 등 집합과 그것이 가지고 있는 집합론적 대상으로써 얽어진 것.","[構造] 구조주의에서, 어떤 일을 성립시키는 것 사이의 상호 기능적 연관."]},{"id":299,"category":"한자어","term":"국한되다","definition":"범위가 일정한 부분에 한정되다.","example":"오염 문제는 이제는 도시에만 국한된 것이 아니다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":300,"category":"한자어","term":"궤변","definition":"상대편을 이론으로 이기기 위하여 상대편의 사고(思考)를 혼란시키거나 감정을 격앙시켜 거짓을 참인 것처럼 꾸며 대는 논법.","example":"궤변을 늘어놓다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":301,"category":"한자어","term":"기거","definition":"일정한 곳에서 먹고 자고 하는 따위의 일상적인 생활을 함. 또는 그 생활.","example":"기거 양식.","exampleSource":"표준국어대사전 용례","otherMeanings":["[起去] 일어나서 떠남.","[起居] 앉아 있다가 손님을 영접하려고 일어섬.","[起居] 몸을 뜻대로 움직이며 생활함.","[寄居] 남에게 덧붙어서 사는 일.","[基據] 터전을 닦음. 또는 그 터전.","[箕踞] 두 다리를 뻗고 앉음."]},{"id":302,"category":"한자어","term":"기고하다","definition":"신문, 잡지 따위에 싣기 위하여 원고를 써서 보내다.","example":"그는 여러 유명한 과학 잡지에 논문을 기고한 경력이 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[奇古, 하다] 기이하고 예스럽다.","[氣高, 하다] 맑게 갠 하늘이 높고 푸르다.","[氣高, 하다] 못마땅한 것을 참지 못하고 성을 내거나 왈칵 행동하는 성미가 매우 강하다.","[起稿, 하다] 원고를 쓰기 시작하다."]},{"id":303,"category":"한자어","term":"기량","definition":"기술상의 재주.","example":"기량을 연마하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[氣量] 기체의 양.","[氣量] 기상과 도량을 아울러 이르는 말.","[器量] 사람의 재능과 도량을 아울러 이르는 말."]},{"id":304,"category":"한자어","term":"기부","definition":"자선 사업이나 공공사업을 돕기 위하여 돈이나 물건 따위를 대가 없이 내놓음.","example":"구두쇠가 장학금 기부를 약속하다니 믿을 수 없는 일이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[肌膚] 사람이나 동물의 몸을 싸고 있는 살이나 살가죽.","[妓夫] 기생이나 몸 파는 여자들의 영업을 돌보아 주면서 얻어먹고 지내는 사내.","[起仆] 일어섰다 넘어졌다 함.","[記付] 사무를 인계할 때에 중기(重記)에 기록함.","[記府] 예전에, 문서를 보관하던 곳.","[記簿] 물건의 출납이나 돈의 수지(收支) 계산을 적어 두는 책.","[寄付] 물건을 줌.","[寄付] 의지하거나 부탁함.","[基部] 기초가 되는 부분.","[欺負] 속이고 배반함.","[箕否] 기자(箕子)의 후손으로 알려진 사람. 조선후(朝鮮侯)라고 이르다가 뒤에 왕이라고 하였다고 전하여진다.","[畿府] 조선 시대에, 경기도 감영을 예스럽게 이르던 말.","[機婦] 베를 짜는 여자."]},{"id":305,"category":"한자어","term":"기술","definition":"대상이나 과정의 내용과 특징을 있는 그대로 열거하거나 기록하여 서술함. 또는 그런 기록.","example":"기술 내용.","exampleSource":"표준국어대사전 용례","otherMeanings":["[技術] 과학 이론을 실제로 적용하여 사물을 인간 생활에 유용하도록 가공하는 수단.","[技術] 사물을 잘 다룰 수 있는 방법이나 능력.","[奇術] 기묘한 솜씨나 재주.","[奇術] 교묘한 눈속임으로 재미있게 부리는 재주.","[旣述] 이미 앞서 기술함."]},{"id":306,"category":"한자어","term":"난관","definition":"일을 하여 나가면서 부딪치는 어려운 고비.","example":"난관에 봉착하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[卵管] 배란된 난자를 자궁 쪽으로 내려보내는 한 쌍의 관. 길이는 약 10cm, 지름은 0.7cm이며 안쪽으로 자궁벽을 뚫고 자궁안으로 열려져 있다.","[難關] 지나기가 어려운 곳."]},{"id":307,"category":"한자어","term":"납량","definition":"여름철에 더위를 피하여 서늘한 기운을 느낌.","example":"납량 특집극.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":308,"category":"한자어","term":"낭보","definition":"기쁜 기별이나 소식.","example":"세계 선수권 대회에서 우리나라 농구 팀이 우승했다는 낭보가 전해졌다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":309,"category":"한자어","term":"냉소","definition":"쌀쌀한 태도로 비웃음. 또는 그런 웃음.","example":"냉소를 머금다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":310,"category":"한자어","term":"논고","definition":"자기의 주장이나 믿는 바를 논술하여 알림.","example":"논고를 펼치다.","exampleSource":"표준국어대사전 용례","otherMeanings":["→ 논꼬.","[論告] 형사 재판에서, 증거 조사를 마치고 검사가 피고의 범죄 사실과, 그에 대한 법률 적용에 관한 의견을 진술하는 일.","[論考, /, 論攷] 여러 문헌을 고증하여 논술함. 흔히 책 이름이나 논문 제목에 쓴다."]},{"id":311,"category":"한자어","term":"누락","definition":"기입되어야 할 것이 기록에서 빠짐. 또는 그렇게 되게 함.","example":"명부에 누락이 생기다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":312,"category":"한자어","term":"누적","definition":"포개어 여러 번 쌓음. 또는 포개져 여러 번 쌓임.","example":"누적된 피로","exampleSource":"제공 자료 예문","otherMeanings":["[漏籍] 병적, 학적 따위의 기록에서 빠뜨림."]},{"id":313,"category":"한자어","term":"덕분","definition":"베풀어 준 은혜나 도움.","example":"선생님 덕분에 대학 생활을 무사히 마칠 수 있었습니다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":314,"category":"한자어","term":"도저하다","definition":"학식이나 생각, 기술 따위가 아주 깊다.","example":"학문이 도저하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[到底, 하다] 행동이나 몸가짐이 빗나가지 않고 곧아서 훌륭하다."]},{"id":315,"category":"한자어","term":"도태되다","definition":"여럿 중에서 불필요하거나 부적당한 것이 줄어 없어지다.","example":"우리는 치열한 경쟁 사회에서 도태되지 않도록 열심히 살아야 한다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[淘汰, 되다, /, 陶汰, 되다] 물건 따위가 물속에서 일어져 좋은 것만 골라지고 불필요한 것이 가려져서 버려지다."]},{"id":316,"category":"한자어","term":"독창","definition":"다른 것을 모방함이 없이 새로운 것을 처음으로 만들어 내거나 생각해 냄.","example":"오늘의 거문고는 신라 때 백결 선생이 처음부터 여섯 현으로 만든 독창의 악기라고 하니까.","exampleSource":"표준국어대사전 용례","otherMeanings":["[禿瘡] 머리에 생기는 피부병의 하나. 군데군데 둥글고 붉은 반점이 생기고 나중에는 머리털이 빠진다.","[毒瘡] 독기가 있는 악성 종기나 큰 부스럼.","[獨唱] 성악에서, 혼자서 노래를 부름. 또는 그 노래.","[獨窓] 문짝이 한쪽만 달린 창."]},{"id":317,"category":"한자어","term":"돌연","definition":"예기치 못한 사이에 급히.","example":"그때 나는 예상 못했던 일과 돌연 마주치게 되었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["반듯하게 만든 문틀이나 미닫이 울거미의 둘레.","[突燃] 강렬한 빛과 열을 내면서 급속히 타오름."]},{"id":318,"category":"한자어","term":"돌출","definition":"예기치 못하게 갑자기 쑥 나오거나 불거짐.","example":"돌출 발언.","exampleSource":"표준국어대사전 용례","otherMeanings":["[突出] 쑥 내밀거나 불거져 있음."]},{"id":319,"category":"한자어","term":"두서","definition":"일의 차례나 갈피.","example":"두서가 잡히다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[頭書] 책이나 논문 따위의 첫머리에 내용이나 목적 따위를 간략하게 적은 글.","[頭書] 본문(本文)에 앞서 모든 요소를 포함하여 쓴 부분.","[蠹書] 좀이 슨 책.","[蠹書] 책을 볕에 쬠."]},{"id":320,"category":"한자어","term":"두찬","definition":"전거나 출처가 확실하지 못한 저술.","example":"출처가 불분명한 두찬을 근거로 삼아서는 안 된다.","exampleSource":"제공 자료 예문","otherMeanings":["[杜撰] 틀린 곳이 많은 작품."]},{"id":321,"category":"한자어","term":"만끽하다","definition":"마음껏 먹고 마시다.","example":"별미를 만끽하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[滿喫, 하다] 욕망을 마음껏 충족하다."]},{"id":322,"category":"한자어","term":"만반","definition":"마련할 수 있는 모든 것.","example":"적국의 침입에 대비해 만반의 준비를 하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[滿盤] ‘만반하다’의 어근."]},{"id":323,"category":"한자어","term":"망라","definition":"물고기나 새를 잡는 그물이라는 뜻으로, 널리 받아들여 모두 포함함을 이르는 말.","example":"각계각층의 지도자들이 망라되다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":324,"category":"한자어","term":"몰각","definition":"아주 없애 버림.","example":"헤 옛날 생활의 흔적들이 모두 몰각되고 말았다.","exampleSource":"제공 자료 예문","otherMeanings":["[沒却] 무시해 버림.","[沒刻] 밤이 깊은 때.","[沒覺] 깨달아 인식하지 못함."]},{"id":325,"category":"한자어","term":"미수","definition":"목적한 바를 시도하였으나 이루지 못함.","example":"암살 기도가 미수로 그치다.","exampleSource":"표준국어대사전 용례","otherMeanings":["설탕물이나 꿀물에 미숫가루를 탄 여름철 음료.","[未收] 돈이나 물건 따위를 아직 다 거두어들이지 못함.","[未收] 부기에서, 영업 주목적 이외의 임시적 거래에서 발생하는 금전 채권. 토지 판매 대금의 미수 부분, 유가 증권의 외상 매출금 따위가 이에 해당한다.","[未遂] 범죄를 실행하려다가 그 목적을 달성하지 못한 일. 행위자의 의사에 의한 중지 미수, 외부의 방해에 의한 장애 미수, 불능 미수가 있다.","[米壽] 여든여덟 살을 달리 이르는 말.","[尾宿] 꼬리별이라는 뜻으로, ‘혜성01「1」’을 달리 이르는 말.","[尾宿] 이십팔수의 여섯째 별자리의 별들. 주성(主星)은 전갈자리의 뮤성(μ星)이다.","[眉叟] ‘이인로’의 자.","[眉叟] ‘허목’의 호.","[眉壽] 눈썹이 세도록 오래 삶. 축수(祝壽)할 때에 쓰는 말이다.","[美秀] ‘미수하다04’의 어근.","[美鬚] 아름다운 수염.","[微睡] 잠시 동안의 가벼운 잠."]},{"id":326,"category":"한자어","term":"박약","definition":"의지나 체력 따위가 굳세지 못하고 여림.","example":"그런 양면성과 이중 구조를 가진 자신의 의식이 싫었다. 그건 사상 무장의 나약이나 혁명 의지의 박약이나 실천 용기의 빈약으로 찍힐 요소였다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[薄弱] 불충분하거나 모자란 데가 있음.","[薄弱] 지능 따위가 정상적이지 못한 상태임.","[薄弱] 얇고도 약함.","[薄藥] 성질과 맛이 순하고 반응이 느린 약."]},{"id":327,"category":"한자어","term":"박장대소","definition":"손뼉을 치며 크게 웃음.","example":"사회자의 재치 있는 말에 방청석에서 박장대소가 터졌다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":328,"category":"한자어","term":"반려","definition":"주로 윗사람이나 상급 기관에 제출한 문서를 처리하지 않고 되돌려줌.","example":"사표 반려.","exampleSource":"표준국어대사전 용례","otherMeanings":["[反戾, /, 叛戾] 배반하여 돌아섬.","[反戾, /, 叛戾] 도리에 어긋남.","[伴侶] 짝이 되는 동무."]},{"id":329,"category":"한자어","term":"발발","definition":"전쟁이나 큰 사건 따위가 갑자기 일어남.","example":"6ㆍ25 전쟁 발발.","exampleSource":"표준국어대사전 용례","otherMeanings":["추위, 두려움, 흥분 따위로 몸이나 몸의 일부분을 가늘게 자꾸 떠는 모양.","무엇을 아주 아끼거나 중요하게 생각하여 노심초사하는 모양.","몸을 바닥 가까이 대고 작은 동작으로 기는 모양.","자신을 낮추어 비굴하게 행동하는 모양을 비유적으로 이르는 말.","바쁘게 여기저기 돌아다니는 모양.","종이나 헝겊 따위가 몹시 삭아서 쉽게 째지는 모양.","‘발발하다01’의 어근.","[勃勃] ‘발발하다02’의 어근."]},{"id":330,"category":"한자어","term":"발인","definition":"장례를 지내러 가기 위하여 상여 따위가 집에서 떠남. 또는 그런 절차.","example":"발인을 서두르다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[發軔] 수레가 떠나간다는 뜻으로, 어떤 일이 시작함을 비유적으로 이르는 말."]},{"id":331,"category":"한자어","term":"발현","definition":"속에 있거나 숨은 것이 밖으로 나타나거나 그렇게 나타나게 함. 또는 그런 결과.","example":"자의식의 발현.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":332,"category":"한자어","term":"배열","definition":"일정한 차례나 간격에 따라 벌여 놓음.","example":"배열 순서.","exampleSource":"표준국어대사전 용례","otherMeanings":["[背熱] 등에서 몹시 열이 나는 증상.","[配列, /, 排列] 동일한 성격의 데이터를 관리하기 쉽도록 하나로 묶는 일."]},{"id":333,"category":"한자어","term":"배임","definition":"주어진 임무를 저버림. 주로 공무원 또는 회사원이 자기의 이익을 위하여 임무를 수행하지 않고 국가나 회사에 재산상의 손해를 주는 경우를 이른다.","example":"배임 행위.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":334,"category":"한자어","term":"배치되다","definition":"서로 반대로 되어 어그러지거나 어긋나게 되다.","example":"법규에 배치되다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[配置, 되다] 사람이나 물자 따위가 일정한 자리에 알맞게 나뉘어 놓이다.","[排置, 되다] 일정한 차례나 간격에 따라 벌여져 놓이다."]},{"id":335,"category":"한자어","term":"배포","definition":"신문이나 책자 따위를 널리 나누어 줌.","example":"신문 배포.","exampleSource":"표준국어대사전 용례","otherMeanings":["[排布, /, 排鋪] 머리를 써서 일을 조리 있게 계획함. 또는 그런 속마음.","[排布, /, 排鋪] 일정한 차례나 간격에 따라 벌여 놓음.","[排布, /, 排鋪] 살림을 꾸리거나 차림.","[焙脯] 육포의 하나. 쇠고기나 돼지고기를 얇고 넓적하게 저며 간을 친 것을, 화롯불 따위에 배롱(焙籠) 같은 것을 씌운 뒤 그 위에다 놓고 말린다.","[褙布] 가죽신이나 함지박 따위를 질기고 단단하게 하려고 풀칠을 하여 여러 겹으로 붙인 헝겊이나 종이."]},{"id":336,"category":"한자어","term":"변질","definition":"성질이 달라지거나 물질의 질이 변함. 또는 그런 성질이나 물질.","example":"식료품의 변질을 막기 위해서는 냉동 보관이 필요하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":337,"category":"한자어","term":"봉정","definition":"문서나 문집 따위를 삼가 받들어 올림.","example":"화갑 기념 논문집 봉정.","exampleSource":"표준국어대사전 용례","otherMeanings":["[峯頂] 산봉우리의 맨 꼭대기.","[蓬征] 정처 없이 떠돌아다님."]},{"id":338,"category":"한자어","term":"부담","definition":"어떠한 의무나 책임을 짐.","example":"부담이 없다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[負擔] 옷이나 책 따위의 물건을 담아서 말에 실어 운반하는 작은 농짝.","[負擔] 법률 행위의 부관(附款)의 하나. 주된 의사 표시에 덧붙여서 그 상대편에게 이에 따르는 특별한 의무를 지우는 의사 표시이다.","[腐談] 케케묵은 말. 또는 쓸모없는 이야기."]},{"id":339,"category":"한자어","term":"부여","definition":"사람에게 권리ㆍ명예ㆍ임무 따위를 지니도록 해 주거나, 사물이나 일에 가치ㆍ의의 따위를 붙여 줌.","example":"임무 부여.","exampleSource":"표준국어대사전 용례","otherMeanings":["[夫餘, /, 扶餘] 기원전 1세기 무렵에 부여족이 북만주 일대에 세운 나라. 농경 생활을 주로 했고, 중국으로부터 철기 문화를 받아들이고 은력을 사용하는 등 진보된 제도와 조직을 갖추었으나, 3세기 말에 선비족의 침입으로 크게 쇠퇴한 후, 그 영토가 대부분 고구려에 편입되었다.","[扶餘] 통일 신라 경덕왕 때 ‘남부여’를 고친 이름.","[扶餘] 충청남도 부여군에 있는 읍. 백제의 성왕 때부터 의자왕 때까지 도읍지였다. 군청 소재지이다. 면적은 58.86㎢.","[賦與] 나누어 줌."]},{"id":340,"category":"한자어","term":"부연","definition":"이해하기 쉽도록 설명을 덧붙여 자세히 말함.","example":"부연 설명.","exampleSource":"표준국어대사전 용례","otherMeanings":["[附椽, /, 婦椽] 처마 서까래의 끝에 덧얹는 네모지고 짧은 서까래. 처마 끝을 위로 들어 올려 모양이 나게 한다.","[浮煙] 연기가 뜨거나 연기를 띄움. 또는 그 연기.","[浮煙] 안개가 뽀얗게 낌.","[富衍] ‘부연하다02’의 어근.","[敷衍, /, 敷演] 늘려서 널리 폄."]},{"id":341,"category":"한자어","term":"부재","definition":"그곳에 있지 아니함.","example":"치안 부재.","exampleSource":"표준국어대사전 용례","otherMeanings":["[不才] 재주가 모자라거나 없음.","[不才] 자신의 재주를 겸손하게 이르는 말.","[附載] 어떤 글이나 시 따위를 주가 되는 글에 첨가하여 실음.","[部材] 구조물의 뼈대를 이루는 데 중요한 요소가 되는 여러 가지 재료.","[覆載] 하늘이 만물을 덮고 땅이 만물을 받쳐 실었다는 뜻으로, 하늘과 땅을 이르는 말."]},{"id":342,"category":"한자어","term":"부족","definition":"필요한 양이나 기준에 미치지 못해 충분하지 아니함.","example":"시간 부족.","exampleSource":"표준국어대사전 용례","otherMeanings":["[夫族] 남편의 친족.","[附族] 혈연관계가 없거나 분명하지 아니하면서도 일가처럼 지내는 사람들.","[副族] 원소 주기율표에서, 원소의 성질을 여덟 족으로 나누었을 때 각 족(族)의 베타 부분에 속하는 아족(亞族). 제1족부터 제8족까지 같은 족에 속하는 원소들은 성질의 차이에 따라 A, B의 두 부분으로 나누어져 있다. 현재는 18족으로 나누어 생각하여 이러한 개념이 없어졌다.","[部族] 같은 조상ㆍ언어ㆍ종교 등을 가진, 원시 사회나 미개 사회의 구성 단위가 되는 지역적 생활 공동체.","[部族] 성(姓)과 본(本)이 같은 겨레붙이."]},{"id":343,"category":"한자어","term":"부흥","definition":"쇠퇴하였던 것이 다시 일어남. 또는 그렇게 되게 함.","example":"민족 부흥에 앞장서다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":344,"category":"한자어","term":"비치","definition":"마련하여 갖추어 둠.","example":"비치 도서.","exampleSource":"표준국어대사전 용례","otherMeanings":["[鼻痔] 콧구멍 속에 군살이 생겨 차츰 커지는 병. 군살의 크기에 따라 다르지만 대체로 코가 막히고 콧물이 많이 나오며 냄새를 잘 맡지 못하고 머리가 아프다."]},{"id":345,"category":"한자어","term":"비호","definition":"편들어서 감싸 주고 보호함.","example":"그와 같은 엄청난 사건은 권력의 비호를 받지 않고서는 일어날 수 없다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[飛虎] 나는 듯이 빠르게 달리는 범.","[悲號] 슬퍼하면서 울부짖음."]},{"id":346,"category":"한자어","term":"빈사","definition":"거의 죽게 됨. 또는 그런 상태.","example":"구조대는 빈사 상태의 등산객을 병원으로 옮겼다.","exampleSource":"교정 예문","otherMeanings":["[貧士] 살림이 구차한 선비.","[賓師] 예전에, 제후에게 빈객(賓客)의 대우를 받던 학자.","[賓辭] 명제에서, 주사(主辭)에 결합되어 그것을 규정하는 개념. 예를 들어, ‘개는 동물이다.’, ‘하늘은 높다.’에서 ‘동물’, ‘높다’가 이에 해당한다."]},{"id":347,"category":"한자어","term":"빙자하다","definition":"남의 힘을 빌려서 의지하다.","example":"최술은 장인을 빙자하여 어서 술이나 들고 푹 취해 버려야만 마음이 편해질 것 같았다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[憑藉, 하다] 말막음을 위하여 핑계로 내세우다."]},{"id":348,"category":"한자어","term":"사단","definition":"사건의 단서. 또는 일의 실마리.","example":"지섭으로서는 문화제의 성격과 관련하여 행사의 주제나 종류 따위를 윤곽 지어 놓는 일과 그 사단을 구하는 작업이 우선 중요했다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[四端] 사람의 본성에서 우러나오는 네 가지 마음. ≪맹자≫에서 유래한 것으로, 인(仁)에서 우러나오는 측은지심, 의(義)에서 우러나오는 수오지심, 예(禮)에서 우러나오는 사양지심, 지(智)에서 우러나오는 시비지심을 이른다.","[寺檀] 절과 시주하는 신도.","[私斷] 개인의 판단.","[事端] → 사달01.","[社團] 특정한 목적을 위하여 두 사람 이상이 결합하여 설립한 단체. 개인을 초월한 독립 단일체로서 법인의 자격을 부여받을 수 있다.","[社團] 법률에 의하여 법률적인 권리와 의무의 주체로 인정을 받은 법인.","[社壇] 임금이 백성을 위하여 토신(土神)인 사(社)와 곡신(穀神)인 직(稷)에게 제사 지내던 제단. 현재 사직 공원으로 남아 있는 서울 사직단은 조선 시대에 태조가 종묘와 함께 지은 것이다. 사적 제121호.","[社壇] 토신(土神)에 제사를 지내는 제단.","[師團] 군대 편성 단위의 하나. 군단(軍團)의 아래, 연대(聯隊) 또는 여단(旅團)의 위이다. 여러 병과(兵科)가 모여 있으며 이를 지휘하는 사령부가 있어 어느 정도 독립적인 작전을 수행할 수 있다.","[師檀] 사승(師僧)과 단도(檀徒)를 아울러 이르는 말.","[紗緞] 사(紗)와 비단을 아울러 이르는 말.","[斜斷] 비스듬히 자름.","[斜斷] 그물코의 마디 한 다리만을 끊어 삼각 그물감을 만드는 일.","[詞壇] 문인(文人)들의 사회.","[←Satan] 적대자라는 뜻으로, 하나님과 대립하여 존재하는 악(惡)을 인격화하여 이르는 말."]},{"id":349,"category":"한자어","term":"사사하다","definition":"스승으로 섬기다. 또는 스승으로 삼고 가르침을 받다.","example":"그는 전처만을 외경했을 뿐만 아니라 전처만을 사사했다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[些些, 하다] 하잘것없이 작거나 적다.","[使事, 하다] 어떤 일을 시키다.","[斜射, 하다] 햇빛이나 그림자 따위가 비스듬히 비치다.","[斜射, 하다] 대각선 쪽에 있는 목표를 향하여 비스듬히 사격을 하다.","[奢肆, 하다] 사치스럽고 방자하다.","[賜死, 하다] 죽일 죄인을 대우하여 임금이 독약을 내려 스스로 죽게 하다.","[謝辭, 하다] 고마운 뜻을 나타내는 말을 하다.","[謝辭, 하다] 사죄하는 말을 하다.","[謝辭, 하다] 예를 갖추어 사양하다. 또는 그런 뜻을 나타내는 말을 하다.","[辭謝, 하다] 사절(辭絕)하여 물리치다."]},{"id":350,"category":"한자어","term":"사장","definition":"사물 따위를 필요한 곳에 활용하지 않고 썩혀 둠.","example":"경기가 악화되면서 많은 연구가 사장되었다.","exampleSource":"제공 자료 예문","otherMeanings":["달구지 틀 사이에 대어 까는 널빤지. 짐 싣는 바닥이 된다.","[士長] 궁중에서, 내시를 감독하는 사람을 이르던 말.","[司長] 대한 제국 때에, 궁내부와 각 부(部)에 속한 각 사(司)의 으뜸 벼슬.","[四杖] 부(缶)를 치는 채. 대를 아홉 조각으로 쪼개어 만든다.","[四葬] 네 가지 장례 방식. 수장(水葬), 화장(火葬), 토장(土葬), 임장(林葬)을 이른다.","[四葬] 고대 중국의 네 가지 장례 방식. 수장(水葬), 화장(火葬), 토장(土葬), 조장(鳥葬)을 이른다.","[四障] 불도 수행의 네 가지 장애. 혹장(惑障), 악장(惡障), 보장(報障), 견장(見障)을 이른다.","[四障] 부처가 되지 못하는 사람의 원인이 되는 네 가지 장애. 인과응보를 믿지 않는 천제장(闡提障), 자기의 실체적 존재를 고집하는 외도장(外道障), 이 세상의 고통을 두려워하여 열반에 나아가기만을 원하는 성문장(聲聞障), 자기 혼자만의 깨달음에 안주하고 자비심이 없는 연각장(緣覺障)을 이른다.","[四藏] 불교의 네 가지 성전. 경장(經藏), 율장(律藏), 논장(論藏)에 주장(呪藏)이나 잡장(雜藏)을 넣은 네 가지를 이른다.","[寺長] 남사당놀이에서, 각 놀이 분야의 우두머리.","[寺長] 사당패에서, 각 종목의 으뜸가는 사람.","[寺長] 사당(寺黨)의 남편.","[沙場, /, 砂場] 강가나 바닷가에 있는 넓고 큰 모래벌판.","[私匠] 관부에 예속되지 않은 장인(匠人).","[私莊] 개인이 사사로이 소유한 별장.","[私莊] 많은 전답을 소작 준 곳에 지은 지주의 별택(別宅).","[私藏] 개인이 사사로이 간직함. 또는 그런 물건.","[事障] 열반을 해치는 번뇌.","[社長] 회사의 책임자. 회사 업무의 최고 집행자로서 회사 대표의 권한을 지닌다.","[社長] 조선 시대에, 사창(社倉)의 곡식을 나누어 주고 거두어들이는 일을 맡아보던 사람.","[社長] 조선 시대에, 지방 행정 구역의 하나인 사(社)의 우두머리.","[社章] 결사(結社)할 때 서로 약속하여 정한 기념장.","[社葬] 회사가 주재하여 지내는 장례.","[査丈] 혼인한 두 집안의 부모들 사이에서 그 집안의 위 항렬이 되는 상대편을 이르는 말.","[射場] 활을 쏘기 위한 일정한 설비를 갖추어 놓은 곳.","[師丈] 스승이 되는 어른.","[師匠] 학문이나 기예에 능하여 남의 스승이 될 만한 사람. 또는 학문이나 기예를 가르치는 사람.","[師長] 스승과 나이 많은 어른.","[紗帳] 얇고 가벼운 비단으로 만든 휘장.","[赦狀] 형벌을 용서한다는 편지.","[赦狀] 대사(大赦)나 특사(特赦)를 명하는 편지.","[詞狀] 소송을 제기하기 위하여 제일심 법원에 제출하는 서류. 이에는 법정 기재 사항인 당사자, 법정 대리인, 청구의 취지, 청구의 원인을 적어야 한다.","[詞章, /, 辭章] 시가와 문장을 아울러 이르는 말.","[詞章, /, 辭章] 문장을 꾸미는 말.","[詞場] 문인(文人)들의 사회.","[寫場] 사진을 찍는 시설을 갖추어 놓은 곳.","[寫場] 일정한 시설을 갖추고 사진 찍는 일을 영업으로 하는 집.","[謝狀] 사례하는 편지.","[謝狀] 사과하는 편지.","[謝章] 임금의 은혜에 감사하는 뜻을 표하여 올리던 글.","[辭狀] 직책에서 사임하겠다는 뜻을 적어 내는 문서."]},{"id":351,"category":"한자어","term":"사지","definition":"사람의 두 팔과 두 다리를 통틀어 이르는 말.","example":"사지를 뻗다.","exampleSource":"표준국어대사전 용례","otherMeanings":["배의 두 멍에 끝에 세우는 짧은 나무.","→ 서지05.","[司紙] 조선 시대에, 조지서(造紙署)에서 종이 만드는 일을 맡아보던 종육품 벼슬. 성종 때 없앴다.","[四至] 사유지나 경작지 따위의 동서남북의 경계.","[四知] 두 사람만의 비밀이라도 어느 때고 반드시 남이 알게 됨을 이르는 말. 중국 후한(後漢)의 양진(楊震)이 형주 자사(荊州刺史)로 부임했을 때, 왕밀(王密)이 밤중에 찾아와서 당신과 나밖에는 아무도 알 사람이 없다 하며 금(金) 열 근을 바쳤을 때, 하늘이 알고 땅이 알고 내가 알고 자네가 안다 하며 받지 않았다는 데서 유래한다. ≪후한서≫의 <양진전(楊震傳)>에 나오는 말이다.","[四肢] 척추동물의 몸에서 뻗어 나온 두 쌍의 다리 부분. 보통 전지(前肢)와 후지(後肢)로 나눈다.","[四指] 칠조 중 네 번째 가락. 평조와 계면조에서, 남려(南呂)를 으뜸음으로 한다.","[四智] 불과(佛果)에 이르러 모든 부처가 갖추는 네 가지 지혜. 대원경지, 평등성지, 묘관찰지, 성소작지이다.","[寺址] 절을 세울 터. 또는 절이 있었던 터.","[死地] 죽을 곳. 또는 죽어야 할 장소.","[死地] 죽을 지경의 매우 위험하고 위태한 곳.","[沙地, /, 砂地] 모래흙으로 이루어진 땅.","[沙紙, /, 砂紙] 금강사(金剛沙)나 유리 가루, 규석(硅石) 따위의 보드라운 가루를 발라 붙인 천이나 종이. 쇠붙이의 녹을 닦거나 물체의 거죽을 반들반들하게 문지르는 데에 쓴다.","[邪智] 간사한 지혜.","[私地] 개인이 소유한 땅.","[私智] 개인의 작은 지혜.","[私智] 공정하지 못한 개인의 사사로운 지혜.","[事知] ‘사지하다’의 어근.","[社誌] ‘사내보’와 ‘사외보’를 통틀어 이르는 말.","[舍知] 신라 때에 둔, 십칠 관등 가운데 열셋째 등급. 사두품 이상이 오를 수 있었다.","[舍知] 신라 때에, 집사성(執事省)ㆍ조부(調府)ㆍ경성주작전ㆍ창부(倉府)ㆍ예부(禮部) 따위의 관아에 속한 벼슬. 위계는 대사부터 사지까지이다.","[絲紙] 제사나 잔치 때에 누름적이나 산적을 꽂은 꼬챙이 끝에 감아 늘어뜨린 좁고 가늘게 오린 종이. 제사에는 흰 종이, 잔치에는 오색(五色) 종이를 쓴다.","[楂枝] 뗏목이 될 만한 큰 나뭇가지."]},{"id":352,"category":"한자어","term":"산화하다","definition":"어떤 대상이나 목적을 위하여 목숨을 바치다.","example":"동료를 구하기 위해 수류탄을 들고 산화하는 무명용사들.","exampleSource":"표준국어대사전 용례","otherMeanings":["[散花, 하다, /, 散華, 하다] 꽃을 뿌리며 부처를 공양하다.","[酸化, 하다] 어떤 원자, 분자, 이온 따위가 전자를 잃다.","[酸化, 하다] 물질 중에 있는 어떤 원자의 산화수가 증가하다.","[酸化, 하다] 어떤 물질이 산소와 결합하거나 수소를 잃다."]},{"id":353,"category":"한자어","term":"상기되다","definition":"흥분이나 부끄러움으로 얼굴이 붉어지다.","example":"그녀는 황급히 오느라고 얼굴이 빨갛게 상기되어 있었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[想起, 되다] 지난 일이 돌이켜져 생각나다."]},{"id":354,"category":"한자어","term":"상념","definition":"마음속에 품고 있는 여러 가지 생각.","example":"그는 의자에 앉아 한동안 상념에 잠겨 있었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":355,"category":"한자어","term":"상당","definition":"일정한 액수나 수치 따위에 해당함.","example":"상당 기간.","exampleSource":"표준국어대사전 용례","otherMeanings":["[上堂] 선종의 장로나 주지가 법당의 강단에 올라가 설법함. 또는 그런 일.","[上堂] 신라 때의 십칠 관등 가운데 11관위인 나마(奈麻)에서 6관위인 아찬까지의 관직.","[上堂] 하회 별신굿에서, 본놀이를 시작하기 전에 제주(祭主)와 무당, 광대들이 모여 음식을 차려 놓고 서낭대와 성줏대를 세워 신이 내리기를 비는 굿.","[上黨] ‘창즈’의 옛 이름."]},{"id":356,"category":"한자어","term":"상도","definition":"상업 활동에서 지켜야 할 도덕. 특히 상업자들 사이에서 지켜야 할 도의를 이른다.","example":"오히려 관에 뇌물을 쓰고 왜놈과 결탁하면서까지 상도를 어기고 돈벌기에만 급급한 잠상(潛商) 거상들에 대한 원한이 더 깊었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[上途] 여행길에 오름.","[上都] 고려 시대에, 사경 가운데에서 각각 신라와 고구려의 중심지였던 동경과 서경을 이르던 말.","[上都] 중국 원나라 때 도읍의 하나. 1256년에 쿠빌라이가 즉위한 곳으로, 원래 카이펑(開平)으로 명명하였다가 나중에 이 이름으로 고쳤다.","[相到] 서로에게 다다름.","[常度] 정상적인 법도.","[常道] 항상 변하지 않는 떳떳한 도리.","[常道] 항상 지켜야 할 도리.","[傷悼] 마음이 아프도록 몹시 슬퍼함.","[想到] 생각이 어떤 곳에 미침.","[霜刀] 서릿발같이 푸르고 날카롭게 서슬이 선 칼."]},{"id":357,"category":"한자어","term":"상수","definition":"남보다 뛰어난 수나 솜씨. 또는 그런 수나 솜씨를 가진 사람.","example":"바둑에서는 상수가 백을 잡고 두도록 되어 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[上水] 음료수나 사용수 따위로 쓰기 위하여 수도관을 통하여 보내는 맑은 물.","[上水] 먹는 물이나 공업, 방화(防火) 따위에 쓰는 물을 관을 통하여 보내 주는 설비.","[上壽] 나이가 보통 사람보다 썩 많음. 또는 그 나이.","[上壽] 100세의 나이. 또는 그 나이가 된 노인. 장수한 것을 상ㆍ중ㆍ하로 나누었을 때 가장 많은 나이를 이른다.","[上壽] 환갑잔치 따위에서, 주인공에게 장수를 비는 뜻으로 술잔을 올림.","[上數] 가장 좋은 꾀.","[向秀] 중국 진(晉)나라의 문인(230?~280). 죽림칠현의 한 사람으로, 곽상(郭象)과 함께 초기 도가서인 ≪장자(莊子)≫에 신도가 경향의 주석을 단 ≪장자주(莊子洼)≫를 썼다.","[相須] 한약 배합 방법의 하나. 성질이 비슷한 두 가지 이상의 약을 같이 써서 약의 효능을 서로 높이게 한다.","[常修] 삼수(三修)의 하나. 부처의 몸이 상주불멸임을 알고, 모든 것은 무상하다고 하는 데에 집착하는 성문(聲聞)의 잘못을 깨뜨리는 일을 이른다.","[常羞] 늘 먹음. 또는 그런 음식.","[常數] 자연으로 정하여진 운명.","[常數] 정하여진 수량.","[常數] 물질의 물리적ㆍ화학적 성질을 표시하는 수치. 일정한 상태에 있는 물질의 성질에 관하여 일정량을 보이는 수를 이른다. 원소의 원자량이나 물질의 비열(比熱)과 같이 각 물질에 고유한 상수와 만유인력 상수나 아보가드로 상수와 같이 물질의 종류에 관계없이 기본적인 법칙에 나타나는 보편적인 상수가 있다.","[常數] 변하지 아니하는 일정한 값을 가진 수나 양.","[常隨] 늘 일정한 임무를 띠고 따라다님.","[喪需] 초상 치르는 데에 드는 비용.","[喪需] 초상 치르는 데 드는 물건.","[賞首] 가장 뛰어나서 상을 받는 사람.","[霜鬚] 서리처럼 흰 수염."]},{"id":358,"category":"한자어","term":"상주하다","definition":"늘 일정하게 살다.","example":"그 섬에 상주하는 사람은 100명 정도밖에 안 된다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[上奏, 하다] 임금에게 말씀을 아뢰다.","[常駐, 하다] 군대 따위가 언제나 머무르다."]},{"id":359,"category":"한자어","term":"상치","definition":"일이나 뜻이 서로 어긋남.","example":"상대방과 의견이 상치되면 다소 여유를 갖고 대화에 임해야 한다.","exampleSource":"제공 자료 예문","otherMeanings":["→ 상추01.","[上, 치] 같은 부류의 사람이나 사물 가운데서 신분이나 품질이 가장 높은 사람이나 물건.","[上齒] 윗잇몸에 난 이.","[尙齒] 노인을 존경함.","[相値] 두 가지 일이 공교롭게 마주침.","[常置] 늘 설치하여 두거나 비치하여 둠."]},{"id":360,"category":"한자어","term":"상환","definition":"갚거나 돌려줌.","example":"원리금 상환.","exampleSource":"표준국어대사전 용례","otherMeanings":["[相換] 서로 맞바꿈.","[償還] 실질적으로 남이 부담하여야 할 출연(出捐)을 자기가 했을 경우에 그 사람에게 자기의 부담을 보상하게 하는 일."]},{"id":361,"category":"한자어","term":"생면하다","definition":"처음으로 대하다.","example":"그 아이를 생면하고 난 후 6년 동안에 들려오는 그 아이에 대한 소문은 온통 정떨어지는 것들뿐이었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[生面, 하다] 생색을 내다."]},{"id":362,"category":"한자어","term":"선수","definition":"남이 하기 전에 앞질러 하는 행동.","example":"선수를 빼앗기다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[先手] 먼저 손찌검을 함. 또는 그 손찌검.","[先手] 바둑이나 장기 따위에서, 먼저 놓거나 두는 일. 또는 상대편이 어떤 수를 쓰기 전에 먼저 중요한 자리에 두는 것.","[先守] 운동 경기에서, 먼저 수비하는 일.","[船首] 배의 앞부분.","[善手] 솜씨가 남보다 뛰어난 사람.","[選手] 운동 경기나 기술 따위에서, 기량이 뛰어나 많은 사람 가운데에서 대표로 뽑힌 사람. 또는 스포츠를 직업으로 하는 사람.","[選手] 어떤 일을 능숙하게 하거나 버릇으로 자주 하는 사람을 비유적으로 이르는 말.","[選授] 인재를 골라 벼슬자리를 줌."]},{"id":363,"category":"한자어","term":"소거하다","definition":"글자나 그림 따위를 지워 없애다.","example":"벽에 있는 낙서를 소거하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[消去, 하다] 둘 이상의 미지수를 가진 방정식에서 특정한 미지수를 없애다.","[消去, 하다] 조건 반사에 강화가 더 이상 주어지지 아니할 때 그 반응이 나타나지 아니하게 하다.","[消去, 하다] 데이터를 처리하는 기구 전체나 일부를 초기 상태로 되돌리다.","[掃去, 하다] 부정적인 것을 모조리 없애다."]},{"id":364,"category":"한자어","term":"소관","definition":"맡아 관리하는 바. 또는 그 범위.","example":"소관 사무.","exampleSource":"표준국어대사전 용례","otherMeanings":["[小官] 지위가 낮은 관리.","[小官] 관리가 자기를 낮추어 이르는 일인칭 대명사.","[小管] 작은 관(管).","[所關] 관계되는 바.","[所觀] 보이는 것.","[素官] 낮은 벼슬."]},{"id":365,"category":"한자어","term":"소정","definition":"정해진 바.","example":"소정 기간.","exampleSource":"표준국어대사전 용례","otherMeanings":["[小正] 문장의 첫머리 이외에 쓰는 알파벳의 인쇄 활자.","[小亭] 작은 정자.","[小政] ‘유월 도목’을 달리 이르는 말. 12월의 도목정사보다 규모가 작은 데서 유래한다.","[小釘] 작은 못.","[小艇] 작은 배.","[素定] 본래부터 작정함.","[素情] 본래부터의 감정.","[疏情] 따돌리고 멀리하는 마음."]},{"id":366,"category":"한자어","term":"소지","definition":"물건을 지니고 있는 일. 또는 그런 물건.","example":"이 공원에 경로 우대증 소지 노인은 무료입장이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[小志] 작은 뜻.","[小枝] 작은 나뭇가지.","[小知, /, 小智] 작은 지혜.","[小指] 다섯 손가락 가운데 다섯째 손가락. 가장 가늘다.","[小指] 다섯 발가락 가운데 다섯째 발가락. 가장 작고 가늘다.","[小誌] 조그마한 잡지.","[小誌] 자기가 관여하고 있는 잡지를 남에게 낮추어 이르는 말.","[沼地] 늪이 많은 땅.","[沼池] 늪과 못을 아울러 이르는 말.","[所志] 예전에, 청원이 있을 때에 관아에 내던 서면.","[所持] 민법에서, 사회 통념으로 보아 물건이 사실적으로 지배되어 있다고 보이는 객관적 상태를 이르는 말.","[所持] 형법에서, 목적물을 사실적인 지배하에 둔 상태를 이르는 말.","[素地] 본래의 바탕.","[素地] 문제가 되거나 부정적인 일 따위를 생기게 하는 원인. 또는 그렇게 될 가능성.","[素志] 평소에 늘 지니고 있는 생각.","[掃地] 땅을 쓺.","[掃地] 마당 쓰는 일을 맡은 사람.","[燒紙] 부정(不淨)을 없애고 신에게 소원을 빌기 위하여 흰 종이를 태워 공중으로 올리는 일. 또는 그런 종이."]},{"id":367,"category":"한자어","term":"소진하다","definition":"점점 줄어들어 다 없어지다. 또는 다 써서 없애다.","example":"자식들로 하여금 부단히 그 울타리에 머리를 처박고 뛰쳐나가기를 시도하게 하던 그 힘이 소진해 버렸다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[疏陳, 하다] 조리 있게 진술하다.","[訴陳, 하다] 소송의 뜻을 진술하다. 원고와 피고가 진술하는 일을 이른다.","[燒盡, 하다] 다 타서 없어지다."]},{"id":368,"category":"한자어","term":"소청","definition":"남에게 청하거나 바라는 일.","example":"부디 소녀의 소청을 들어주십시오.","exampleSource":"표준국어대사전 용례","otherMeanings":["[掃淸] 더럽거나 어지러운 것을 쓸고 닦아서 깨끗하게 함.","[掃淸] 휩쓸어 죄다 없애 버림.","[疏請] 임금에게 상소하여 청함.","[疏廳] 조선 시대에, 유생들이 모여서 건의ㆍ상소를 하던 집.","[訴請] 하소연하여 청함.","[訴請] 공무원법에서, 징계 처분이나 휴직ㆍ면직ㆍ직위 해제 따위의 불이익 처분을 받은 사람이 그 처분에 따르지 아니하고 취소나 변경 따위를 청구하는 일.","[訴請] 귀속 재산 처리에 관하여 이해관계인이 이의 신청을 하는 일.","[訴請] 예전에, 지방 자치법에서 지방 자치 단체의 조례(條例) 또는 그 장(長)의 명령이나 처분이 헌법 또는 법률을 위반하였을 때에, 주민 100인 이상이 서명을 하여 그의 취소 따위를 청구하던 일."]},{"id":369,"category":"한자어","term":"소환","definition":"법원이 피고인, 증인, 변호인, 대리인 따위의 소송 관계인에게 소환장을 발부하여, 공판 기일이나 그 밖의 일정한 일시에 법원 또는 법원이 지정한 장소에 나올 것을 명령하는 일.","example":"소환에 불응하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[小宦] 나이가 젊고 지위가 낮은 환관.","[召還] 국제법에서, 본국에서 외국에 파견한 외교 사절이나 영사를 불러들이는 일.","[召還] 헌법에서, 국가나 지방 자치 단체의 공직에 있는 사람을 임기가 끝나기 전에 국민의 투표로 파면하는 일. 또는 그런 제도."]},{"id":370,"category":"한자어","term":"송영","definition":"가는 사람을 보내고 오는 사람을 맞음.","example":"열차가 정거장에 들어올 때에 송영 나온 군중은 깃발을 두르며 만세를 부르고….","exampleSource":"표준국어대사전 용례","otherMeanings":["[送迎] 묵은해를 보내고 새해를 맞음.","[頌榮] 예배의 시작과 마지막에 들어가는 기도 형식의 송가.","[誦詠] 시가를 외워 읊조림."]},{"id":371,"category":"한자어","term":"송치","definition":"수사 기관에서 검찰청으로, 또는 한 검찰청에서 다른 검찰청으로 피의자와 서류를 넘겨 보내는 일.","example":"열흘이 되자 우리는 송치가 되어서 법원 파출소로 이첩되었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["암소 배 속에 든 새끼.","[送致] 서류나 물건 따위를 보내어 정해진 곳에 이르게 함."]},{"id":372,"category":"한자어","term":"수임","definition":"위임 계약에 의하여 상대편의 법률 행위나 사무 처리를 맡음.","example":"변호사 수임 계약서.","exampleSource":"표준국어대사전 용례","otherMeanings":["[水荏] 꿀풀과의 한해살이풀. 줄기는 높이가 60~90cm이고 모가 지며, 잎은 마주나고 넓은 달걀 모양이다. 여름에 흰색의 잔꽃이 줄기 끝에 총상(總狀) 화서로 피고 꽃이 진 뒤에 네 개의 잔씨가 들어 있는 수과(瘦果)를 맺는다. 잎은 독특한 냄새가 있어 반찬으로 쓰고, 씨는 기름을 짜서 식용하는데 고소한 냄새가 난다. 동남아시아가 원산지로 한국, 중국, 인도 등지에 분포한다.","[受任] 임무나 위임을 받음.","[授任] 임무나 위임을 줌.","[授任] 위임 계약에 의하여 위임 사무를 처리할 권리를 줌."]},{"id":373,"category":"한자어","term":"수작","definition":"남의 말이나 행동, 계획을 낮잡아 이르는 말.","example":"엉뚱한 수작.","exampleSource":"표준국어대사전 용례","otherMeanings":["[手作] 손으로 만듦. 또는 그런 일.","[秀作] 우수한 작품.","[授爵] 작위를 줌.","[授爵] 헌관이 헌작할 때 집사관이 그 오른편에서 술이 담긴 작(爵)을 건네주던 일.","[酬酌] 술잔을 서로 주고받음.","[酬酌] 서로 말을 주고받음. 또는 그 말."]},{"id":374,"category":"한자어","term":"수주","definition":"주문을 받음. 주로 물건을 생산하는 업자가 제품의 주문을 받는 것을 이르는 말이다.","example":"수주가 줄다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[手珠] 여러 개의 나무로 만든 구슬을 끈에 꿰어서 고리 모양으로 만든 물건. 주로 나이 든 사람들이 손에 들고 빙빙 돌려 손의 뻣뻣한 증상을 부드럽게 푸는 데 쓴다.","[水主] 신라 때에, 고관가전과 월지악전에 속한 벼슬.","[水柱] 솟구쳐 뻗치거나 내리쏟아지는 굵은 물줄기.","[水紬] 품질이 좋은 비단의 하나.","[守株] 한 가지 일에만 얽매여 발전을 모르는 어리석은 사람을 비유적으로 이르는 말. 중국 송나라의 한 농부가 우연히 나무 그루터기에 토끼가 부딪쳐 죽은 것을 잡은 후, 또 그와 같이 토끼를 잡을까 하여 일도 하지 않고 그루터기만 지키고 있었다는 데서 유래한다. ≪한비자≫의 <오두편(五蠹篇)>에 나오는 말이다.","[隋珠] 중국 수나라의 국보였던 구슬. 수후(隋侯)가 뱀을 살려 준 뒤 뱀으로부터 받은 보주(寶珠)로, 화씨지벽(和氏之璧)과 함께 천하의 귀중한 보배로 불린다.","[壽酒] 오래 살기를 기원하고 축하하는 술.","[數珠] 염불할 때에, 손으로 돌려 개수를 세거나 손목 또는 목에 거는 법구(法具).","[樹州] ‘변영로’의 호."]},{"id":375,"category":"한자어","term":"수지","definition":"수입과 지출을 아울러 이르는 말.","example":"수지 균형을 맞추다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[수, 紙] → 휴지02.","[手指] 손끝의 다섯 개로 갈라진 부분. 또는 그것 하나하나.","[手指] 궁중에서, ‘손01’을 이르던 말.","[守志] 지조를 지킴.","[收支] 거래 관계에서 얻는 이익.","[受支] 십이 연기의 하나. 외계와의 접촉에서 느끼는, 괴로움과 즐거움에 대한 느낌 작용을 이른다.","[受持] 경전이나 계율을 받아 항상 잊지 않고 머리에 새겨 가짐.","[殊智] 뛰어난 슬기.","[須知] 자신이 소속된 일에 대하여 모름지기 알아야 함.","[樹枝] 나무의 줄기에서 뻗어 나는 가지.","[樹脂] 소나무나 전나무 따위의 나무에서 분비하는 점도가 높은 액체. 또는 그것이 공기에 닿아 산화하여 굳어진 것.","[樹脂] 천연수지와 합성수지를 통틀어 이르는 말.","[獸脂] 짐승에서 짜낸 기름."]},{"id":376,"category":"한자어","term":"수탁","definition":"다른 사람의 의뢰나 부탁을 받음. 또는 그런 일.","example":"이 연구소는 중소기업의 수탁을 받아 연구 개발 사업을 수행한다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[手拓] 탁본을 뜸. 또는 그 탁본.","[受託] 남의 물건 따위를 맡음."]},{"id":377,"category":"한자어","term":"시금석","definition":"가치, 능력, 역량 따위를 알아볼 수 있는 기준이 되는 기회나 사물을 비유적으로 이르는 말.","example":"이번 총선은 민주주의의 발전 정도를 한 단계 높이거나 떨어뜨릴 수 있는 중요한 시금석이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[試金石] 귀금속의 순도를 판정하는 데 쓰는 검은색의 현무암이나 규질의 암석. 금이나 은 조각을 이 돌의 표면에 문질러 나타난 흔적의 빛깔과 표본의 금 빛깔을 비교하여 순도를 시험한다."]},{"id":378,"category":"한자어","term":"시여","definition":"남에게 물건을 거저 줌.","example":"그동안 남모르게 해 오던 불우 이웃에 대한 그의 시여 행위가 알려지면서 모범 시민 표창을 받게 되었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[詩餘] 중국 송나라 때 유행한 한시의 격식. 당나라 때 서역에서 들어온 것으로, 일정한 평측(平仄)으로 장단구를 만들고, 각 구에 알맞은 글자를 채워 넣어 짓는 시이다. 이백의 <억진아(憶秦娥)>, <보살만(菩薩蠻)>이 그 시초이다.","‘여24’의 높임말. 어미 ‘-시-’와 호격 조사 ‘여’가 결합한 말이다."]},{"id":379,"category":"한자어","term":"식언","definition":"한번 입 밖에 낸 말을 도로 입 속에 넣는다는 뜻으로, 약속한 말대로 지키지 아니함을 이르는 말.","example":"식언을 일삼다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[飾言] 말을 거짓으로 꾸밈. 또는 거짓으로 꾸며서 하는 말."]},{"id":380,"category":"한자어","term":"신병","definition":"보호나 구금의 대상이 되는 본인의 몸.","example":"신병 처리.","exampleSource":"표준국어대사전 용례","otherMeanings":["[身病] 몸에 생긴 병.","[神兵] 신이 보낸 군사라는 뜻으로, 신출귀몰하여 적이 도저히 맞싸울 수 없는 강한 군사를 비유적으로 이르는 말.","[神病] 장차 무당이나 박수가 될 사람이 걸리는 병. 이 병은 의약으로는 낫지 않으며 무당이 되어야만 낫는다고 한다.","[腎病] 오장(五臟)의 하나인 신(腎)에 생기는 병증. 머리가 어지럽고 귀울림이 있으며 정신이 맑지 못하고 다리와 무릎이 약하여지며 허리가 시큰거리고 유정(遺精)이 있는 따위가 주된 증상이다.","[新兵] 새로 입대한 병사.","[新病] 새로 생긴 병. 원래 있던 오래된 병에 상대하여 이르는 말이다."]},{"id":381,"category":"한자어","term":"신산하다","definition":"(비유적으로) 세상살이가 힘들고 고생스럽다.","example":"그는 문득 작년에 상처한 것을 생각하고 주부 없는 신산한 살림에 지쳐 조만간 장가를 가야 될 것을 생각하였다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[辛酸, 하다] 맛이 맵고 시다."]},{"id":382,"category":"한자어","term":"실각","definition":"발을 헛디딤.","example":"그는 계단에서 실각하여 부상을 입었다.","exampleSource":"제공 자료 예문","otherMeanings":["[실, 刻] 실처럼 가늘게 파서 새기는 일. 또는 그런 새김.","[失脚] 세력을 잃고 지위에서 물러남."]},{"id":383,"category":"한자어","term":"심금","definition":"마음속 깊이 품은 생각.","example":"그에게는 심금을 털어놓을 만한 친구가 없다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[心琴] 외부의 자극에 따라 미묘하게 움직이는 마음을 비유적으로 이르는 말."]},{"id":384,"category":"한자어","term":"아량","definition":"너그럽고 속이 깊은 마음씨.","example":"그는 넓은 아량으로 동료의 실수를 용서했다.","exampleSource":"교정 예문","otherMeanings":[]},{"id":385,"category":"한자어","term":"애도","definition":"사람의 죽음을 슬퍼함.","example":"애도 기간.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":386,"category":"한자어","term":"어안","definition":"물고기의 눈.","example":"어안이 벙벙하다 이때 '어안은 고유어로 어이없어 말을 못 하고 있 는 혀 안을 의미함.","exampleSource":"제공 자료 예문","otherMeanings":["어이없어 말을 못 하고 있는 혀 안.","[魚眼] 물이 끓어오를 때 생기는 물고기의 눈만 한 거품을 이르는 말."]},{"id":387,"category":"한자어","term":"언변","definition":"말을 잘하는 재주나 솜씨.","example":"유창한 언변.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":388,"category":"한자어","term":"영고","definition":"번성함과 쇠퇴함.","example":"그것은 한 가정의 우울에만 그칠 문제가 아닐 것이오, 국가의 영고에까지 관하는 문제가 될 것이 자명하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[迎鼓] 부여국에서 추수가 끝난 12월에 행하던 제천 의식. 모든 백성이 모여 하늘에 제사를 지내고 추수를 감사하며 날마다 춤과 노래와 술을 즐기었으며, 이 행사 중에는 처벌과 투옥을 금하고 죄수들을 놓아주기도 하였다.","[鈴鼓] ‘탬버린’이 처음 들어왔을 때 이르던 말.","[靈告] 신령의 계시.","[靈鼓] 아악에서 쓰는 북의 하나. 한쪽으로만 가죽을 대고 누런 칠을 한 북 여덟 개를 한 묶음으로 틀에 매달아 놓은 것으로, 지신(地神)에게 제사 지낼 때 헌가악(軒架樂)에 치며, 주악(奏樂)할 때 진고와 함께 친다."]},{"id":389,"category":"한자어","term":"오찬","definition":"손님을 초대하여 함께 먹는 점심 식사.","example":"오찬 간담회.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":390,"category":"한자어","term":"우골탑","definition":"가난한 농가에서 소를 팔아 마련한 학생의 등록금으로 세운 건물이라는 뜻으로, ‘대학01’을 속되게 이르는 말.","example":"한때 대학은 상아탑 대신에 우골탑으로 불렸다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":391,"category":"한자어","term":"우수","definition":"근심과 걱정을 아울러 이르는 말.","example":"우수가 서린 낯빛.","exampleSource":"표준국어대사전 용례","otherMeanings":["일정한 수효 외에 더 받는 물건.","물건값을 제하고 거슬러 받는 잔돈.","[牛首] 소의 목.","[牛宿] 이십팔수의 아홉째 수(宿). 이 수의 좌표 기준이 되는 수거성(宿距星)은 현대 천문학의 이름으로는 다비흐에 해당한다.","[牛髓] 소의 골.","[右手] 오른쪽에 있는 손.","[迂叟] 세상일에 어두운 늙은이.","[迂叟] 세상일을 잘 모르는 늙은이라는 뜻으로, 노인이 자기를 낮추어 이르는 일인칭 대명사.","[雨水] 비가 와서 고이거나 모인 물.","[雨水] 이십사절기의 하나. 입춘(立春)과 경칩(驚蟄) 사이에 들며, 양력 2월 18일경이 된다. 태양의 황경(黃經)이 330도인 때에 해당한다.","[偶數] 2로 나누어서 나머지가 0이 되는 수. 2, 4, 6, 8, 10 따위의 수를 이른다.","[憂囚] 시름에 잠겨 헤어나지 못함. 또는 그런 사람.","[優秀] 여럿 가운데 뛰어남.","[優殊] ‘우수하다03’의 어근.","[優數] ‘우수하다04’의 어근."]},{"id":392,"category":"한자어","term":"우활하다","definition":"사리에 어둡고 세상 물정을 잘 모르다.","example":"그의 생각은 현실과 동떨어져 우활했다.","exampleSource":"제공 자료 예문","otherMeanings":["[迂闊, 하다] 곧바르지 아니하고 에돌아서 실제와는 거리가 멀다.","[迂闊, 하다] 주의가 부족하다."]},{"id":393,"category":"한자어","term":"위생","definition":"건강에 유익하도록 조건을 갖추거나 대책을 세우는 일.","example":"위생 검사.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":394,"category":"한자어","term":"유기","definition":"내다 버림.","example":"관 내에 장치(藏置)한 물건을 손괴, 유기, 은닉, 또는 영득한 자는 7년 이하의 징역에 처한다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[幼期] 어린 시기.","[有期] 언제까지라고 정한 기한이 있음.","[有機] 생명을 가지며, 생활 기능이나 생활력을 갖추고 있음.","[有機] 생물체처럼 전체를 구성하고 있는 각 부분이 서로 밀접하게 관련을 가지고 있음.","[乳氣] 어린애 같은 모양. 또는 그런 기분.","[幽奇] ‘유기하다01’의 어근.","[柳器] 키버들의 가지나 대오리 따위로 엮어서 상자같이 만든 물건. 주로 옷을 넣어 두는 데 쓴다.","[留記] 고구려의 역사책. 고구려가 한자를 사용한 이후에 남긴 역사 기록으로, 영양왕 11년(600)에 이문진이 이를 요약하여 ≪신집(新集)≫ 다섯 권을 만들었다는 내용이 ≪삼국사기≫에 담겨 있을 뿐, 오늘날은 전하지 않는다.","[遊技] 당구ㆍ바둑 따위의, 오락으로 하는 운동이나 경기.","[遺記] 죽은 뒤에 남은 기록.","[遺棄] 어떤 사람이 종래의 보호를 거부하여, 그를 보호받지 못하는 상태에 두는 일.","[鍮器] 놋쇠로 만든 그릇."]},{"id":395,"category":"한자어","term":"유수","definition":"손꼽을 만큼 두드러지거나 훌륭함.","example":"국내 유수의 대기업.","exampleSource":"표준국어대사전 용례","otherMeanings":["[幼樹] 나서 한두 해쯤 자란 나무.","[有數] 정하여진 운수나 순서가 있음.","[乳首] → 젖꼭지.","[乳嗽] 갓난아이가 난 지 100일 안에 기침을 하는 병증. 숨이 차고 가래가 많으며 잠을 잘 자지 못한다.","[幽囚] 잡아 가둠.","[幽愁] 남모를 깊은 근심.","[幽邃] ‘유수하다03’의 어근.","[柳宿] 이십팔수의 스물넷째 별자리.","[流水] 흐르는 물.","[留守] 고려 시대에, 동경(東京)ㆍ서경(西京)ㆍ남경(南京)에 두어 그곳을 다스리게 하던 외관(外官) 벼슬.","[留守] 조선 시대에, 수도 이외의 요긴한 곳을 맡아 다스리던 정이품의 외관(外官) 벼슬. 개성ㆍ강화ㆍ광주ㆍ수원ㆍ춘천 등지에 두었다.","[留數] 주어진 점을 제외한 근방의 폐곡선에 따르는 1가 정칙 함수의 적분을 <I>2πi</I>로 나눈 값.","[遊手] 일정한 직업 없이 놀고 있음. 또는 그런 사람.","[劉秀] 중국 후한의 제1대 황제인 ‘광무제’의 본명."]},{"id":396,"category":"한자어","term":"유예","definition":"일을 결행하는 데 날짜나 시간을 미룸. 또는 그런 기간.","example":"이자의 유예.","exampleSource":"표준국어대사전 용례","otherMeanings":["[猶豫] 망설여 일을 결행하지 아니함.","[猶豫] 소송 행위를 하거나 소송 행위의 효력을 발생시키기 위하여 일정한 기간을 둠. 또는 그런 기간.","[遊藝] 육예(六藝)를 배움.","[遺裔] 선조나 어버이가 죽고 뒤에 남은 자손."]},{"id":397,"category":"한자어","term":"윤색","definition":"사실을 과장하거나 미화함을 비유적으로 이르는 말.","example":"번역극을 다루다 보면 우리 실정에 맞는 내용의 윤색도 필요하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[淪塞] 가라앉아 막힘.","[淪塞] 낙오되어 불행하게 됨.","[潤色] 윤이 나도록 매만져 곱게 함."]},{"id":398,"category":"한자어","term":"융성","definition":"기운차게 일어나거나 대단히 번성함.","example":"역사학의 융성.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":399,"category":"한자어","term":"응대","definition":"부름이나 물음 또는 요구 따위에 응하여 상대함.","example":"응대가 시큰둥하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[應待] 손님을 맞아들여 접대함."]},{"id":400,"category":"한자어","term":"인수","definition":"물건이나 권리를 건네받음.","example":"물품 인수.","exampleSource":"표준국어대사전 용례","otherMeanings":["[人首] 사람의 머리.","[人壽] 사람의 수명.","[人數] 사람의 수효.","[仁壽] 어진 덕이 있고 수명이 긺.","[仁獸] 성인이 이 세상에 나올 징조로 나타난다고 하는 상상 속의 짐승. 몸은 사슴 같고 꼬리는 소 같고, 발굽과 갈기는 말과 같으며 빛깔은 오색이라고 한다.","[引水] 물을 끌어다 댐.","[引受] 환어음의 지급인이 어음 금액을 지급할 의무를 진다는 내용을 어음에 적고 서명함.","[印綬] 병권(兵權)을 가진 무관이 발병부(發兵符) 주머니를 매어 차던, 길고 넓적한 녹비 끈.","[因數] 정수 또는 정식을 몇 개의 곱의 꼴로 하였을 때에, 그것의 각 구성 요소를 이르는 말.","[忍受] 치욕을 참고 받음."]},{"id":401,"category":"한자어","term":"인지하다","definition":"어떤 사실을 인정하여 알다.","example":"신호를 인지하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[仁智, 하다] 어질고 슬기롭다."]},{"id":402,"category":"한자어","term":"일별하다","definition":"한 번 흘낏 보다.","example":"우리는 그의 곁을 지날 때 땅바닥에 펼쳐 놓은 조그만 손수건 위에서 그의 전 소유물을 일별할 수 있었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[一別, 하다] 한 번 헤어지다."]},{"id":403,"category":"한자어","term":"임대","definition":"돈을 받고 자기의 물건을 남에게 빌려줌.","example":"임대 아파트.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":404,"category":"한자어","term":"임종","definition":"죽음을 맞이함.","example":"할머니는 편안하게 임종을 하셨다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[林鍾] 동양 음악에서, 십이율의 여덟째 음. 육려의 하나로 방위는 미(未), 절후는 음력 6월에 해당한다.","[臨終] 부모가 돌아가실 때 그 곁에 지키고 있음."]},{"id":405,"category":"한자어","term":"임차","definition":"돈을 내고 남의 물건을 빌려 씀.","example":"은행 돈을 빌려 사무실을 임차하였다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":406,"category":"한자어","term":"입선","definition":"출품한 작품이 심사에 합격하여 뽑힘.","example":"그러나 그보다도 더 반가운 것은 전람회 입선 작품이 신문에 발표된 것이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[入船] 배가 항구에 들어오거나 들어감.","[入線] 전차나 열차 따위가 역에서 승객을 태우기 위하여 지정된 선로(線路)에 들어옴.","[入禪] 좌선을 하거나 불경을 읽으러 선원에 들어가는 일.","[入禪] 선정(禪定)에 들어가는 일."]},{"id":407,"category":"한자어","term":"입찰","definition":"상품의 매매나 도급 계약을 체결할 때 여러 희망자들에게 각자의 낙찰 희망 가격을 서면으로 제출하게 하는 일.","example":"입찰 공고.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":408,"category":"한자어","term":"자작","definition":"자기 스스로 술을 따라 마심.","example":"자작으로 잔을 비우다.","exampleSource":"표준국어대사전 용례","otherMeanings":["‘자작거리다’의 어근.","‘자작하다01’의 어근.","자작나뭇과의 낙엽 활엽 교목. 높이는 20~30미터이며, 나무껍질은 흰색이며 종이처럼 벗겨진다. 잎은 어긋나고 삼각형의 달걀 모양이다. 4~5월에 단성화가 수상(穗狀) 화서로 피고 열매는 작은 견과(堅果)로 10월에 익는다. 나무껍질은 약용ㆍ유피용(鞣皮用)으로 쓰고 목재는 기구(器具)에 쓰며 산기슭의 풍치림의 조성에도 적당하다. 한국 북부와 일본, 중국, 시베리아 동부 등지에 분포한다.","[子爵] 다섯 등급으로 나눈 귀족의 작위(爵位) 가운데 넷째. 백작(伯爵)의 아래, 남작(男爵)의 위이다.","[子爵] 고려 공민왕 때에 둔, 오등작의 넷째 작위.","[自作] 자기 스스로 만들거나 지음. 또는 그렇게 만든 것.","[自作] 자기 땅에 자기가 직접 농사를 지음.","[赭斫] 산이 발갛게 드러나도록 나무를 남김없이 벰."]},{"id":409,"category":"한자어","term":"작고","definition":"고인이 되었다는 뜻으로, 사람의 죽음을 높여 이르는 말.","example":"원로 작가의 작고 소식에 문단이 슬픔에 잠겼다.","exampleSource":"제공 자료 예문","otherMeanings":["[作苦] 힘들여 수고하고 애씀."]},{"id":410,"category":"한자어","term":"작렬하다","definition":"포탄 따위가 터져서 쫙 퍼지다.","example":"작렬하는 포성.","exampleSource":"표준국어대사전 용례","otherMeanings":["[炸裂, 하다] (비유적으로) 박수 소리나 운동 경기에서의 공격 따위가 포탄이 터지듯 극렬하게 터져 나오다."]},{"id":411,"category":"한자어","term":"잡기","definition":"잡다한 놀이의 기술이나 재주.","example":"그는 잡기에 능하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["유도에서, 맞붙어 연습을 할 때 기술을 거는 쪽의 사람.","[雜伎] 중국 고대와 중세에 행하여진 각종 예능을 통틀어 이르는 말. 곡예, 기술(奇術), 가면, 무용, 인형 놀이 따위가 있다.","[雜妓] 각종 예능을 가진 기생.","[雜技] 잡스러운 여러 가지 노름.","[雜歧] 잡다한 기술을 다루던 벼슬. 또는 그 벼슬에 있던 벼슬아치. 천문관, 금루관, 화원, 산원, 율원, 의관, 역관 따위의 기술관을 이른다.","[雜記] 여러 가지 일을 질서 없이 기록함. 또는 그런 기록.","[雜記] 자질구레한 일을 기록함. 또는 그런 기록.","[雜器] 여러 가지 자질구레한 기명(器皿).","[雜器] 신령에게 공물을 바칠 때에 쓰는, 작은 나무 접시."]},{"id":412,"category":"한자어","term":"장계","definition":"왕명을 받고 지방에 나가 있는 신하가 자기 관하(管下)의 중요한 일을 왕에게 보고하던 일. 또는 그런 문서.","example":"책을 만들어서 장계와 함께 올리오니, 비옵건대, 중앙과 지방에 반포하여 영구히 성법(成法)으로 삼게 하소서.","exampleSource":"표준국어대사전 용례","otherMeanings":["[長計] 어떤 일이 오래 계속되도록 꾀하는 계책."]},{"id":413,"category":"한자어","term":"장고","definition":"오랫동안 깊이 생각함.","example":"바둑은 아직도 포석 단계였고, 그들은 장고에 장고를 거듭했다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[杖鼓, /, 長鼓] ‘장구01’의 원말.","[長股] 개구릿과의 하나. 몸의 길이는 5~9cm이며 대개 녹색을 띤 갈색에 어두운 갈색이나 검은 무늬가 있다. 머리는 세모지고 등 쪽에는 주름과 혹 같은 돌기가 많으며 배는 희거나 누런색이다. 한국, 몽골, 중국, 일본 등지에 분포한다.","[掌固] 고려 시대에, 동궁에 속하여 창고를 지키고 진설(陳設)을 맡아 하던 구실아치.","[掌故] 전부터 해 내려오던 전례(前例)가 관습으로 굳어진 것.","[掌故] 전례(典例)를 맡은 벼슬아치."]},{"id":414,"category":"한자어","term":"장악","definition":"손안에 잡아 쥔다는 뜻으로, 무엇을 마음대로 할 수 있게 됨을 이르는 말.","example":"정권 장악.","exampleSource":"표준국어대사전 용례","otherMeanings":["[帳幄] 한데에서 볕 또는 비바람을 피할 수 있도록 둘러치는 막."]},{"id":415,"category":"한자어","term":"주지","definition":"여러 사람이 두루 앎.","example":"주지의 사실.","exampleSource":"표준국어대사전 용례","otherMeanings":["별신굿에서, 나쁜 짐승이나 귀신을 물리치려고 씌우는 사자탈.","[主旨] 주장이 되는 요지나 근본이 되는 중요한 뜻.","[主旨] 하느님의 뜻.","[主枝] 원줄기에 붙어 있는 굵은 가지.","[主知] 감성이나 의지보다 이성, 지성, 합리성 따위를 중히 여기는 일.","[住地] 실질적인 생활의 근거가 되는 장소. 법인인 경우에는 주된 사무소나 본점을 이른다.","[住持] 세상에 머물러 교법(敎法)을 보존하고 유지함.","[住持] 절을 주관하는 승려.","[周池] 성(城) 둘레에 도랑처럼 파서 물이 괴게 한 곳.","[周紙] 가로로 길게 이어 돌돌 둥글게 만 종이. 편지나 그 밖의 글을 쓸 때 쓴다.","[注紙] 주서(注書)나 승지(承旨)가 임금 앞에서 임금의 명령을 받아 적는 데에 쓰던 종이.","[酒漬] 약을 술에 담가 서서히 스며들도록 하는 일."]},{"id":416,"category":"한자어","term":"준거","definition":"사물의 정도나 성격 따위를 알기 위한 근거나 기준.","example":"판단의 준거가 명확하지 않다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[峻拒] 엄정한 태도로 거절함.","[遵據] 전례나 명령 따위에 의거하여 따름.","[蹲踞] 주저앉음."]},{"id":417,"category":"한자어","term":"준공","definition":"공사를 다 마침.","example":"스포츠 센터를 착공 2년 만에 준공하였다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":418,"category":"한자어","term":"중용","definition":"중요한 자리에 임용함.","example":"요직에 중용되다.","exampleSource":"제공 자료 예문","otherMeanings":["[中庸] 지나치거나 모자라지 아니하고 한쪽으로 치우치지도 아니한, 떳떳하며 변함이 없는 상태나 정도.","[中庸] 재능이 보통임. 또는 그런 사람.","[中庸] 동양 철학의 기본 개념으로 사서의 하나인 ≪중용≫에서 말하는 도덕론. 지나치거나 모자람이 없이 도리에 맞는 것이 ‘중(中)’이며, 평상적이고 불변적인 것이 ‘용(庸)’이다.","[中庸] 아리스토텔레스의 덕론(德論)의 중심 개념. 이성으로 욕망을 통제하고, 지견(智見)에 의하여 과대와 과소가 아닌 올바른 중간을 정하는 것을 이른다.","[中庸] 유학 경전인 사서(四書)의 하나. 공자의 손자인 자사(子思)가 지은 것으로 중용의 덕과 인간의 본성인 성(性)에 대하여 설명하였다. 본디 ≪예기≫ 가운데 한 편이었으나, 유송(劉宋)의 대응(戴顒)이 빼내어 별책으로 하였고, 정자(程子)가 사서에 편입하였으며, 주자(朱子)가 장구(章句)를 만들어 성행하게 되었다. 1권."]},{"id":419,"category":"한자어","term":"증편","definition":"정기적인 교통편의 횟수를 늘림.","example":"증편 운행.","exampleSource":"표준국어대사전 용례","otherMeanings":["[蒸, 편, /, 烝, 편] 여름에 먹는 떡의 하나. 멥쌀가루를, 막걸리를 조금 탄 뜨거운 물로 묽게 반죽하여 더운 방에서 부풀려 밤, 대추, 잣 따위의 고명을 얹고 틀에 넣어 찐다."]},{"id":420,"category":"한자어","term":"진단","definition":"의사가 환자의 병 상태를 판단하는 일.","example":"의사의 진단을 받다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[眞檀] 자단, 백단 따위의 향나무를 통틀어 이르는 말.","[震旦] 해가 뜨는 곳이라는 뜻으로, ‘발해01’를 달리 이르는 말.","[震檀] ‘우리나라’를 예스럽게 이르는 말. ‘震’은 중국의 동쪽을 뜻하고, ‘檀’은 우리나라의 시조인 단군을 뜻하는 말이다."]},{"id":421,"category":"한자어","term":"진척","definition":"일이 목적한 방향대로 진행되어 감.","example":"진척 과정.","exampleSource":"표준국어대사전 용례","otherMeanings":["[津尺] 고려ㆍ조선 시대에, 나룻배의 사공 노릇을 하던 천민.","[進陟] 벼슬이 높아짐."]},{"id":422,"category":"한자어","term":"질곡","definition":"몹시 속박하여 자유를 가질 수 없는 고통의 상태를 비유적으로 이르는 말.","example":"질곡의 세월.","exampleSource":"표준국어대사전 용례","otherMeanings":["[桎梏] 옛 형구인 차꼬와 수갑을 아울러 이르는 말."]},{"id":423,"category":"한자어","term":"질책","definition":"꾸짖어 나무람.","example":"질책을 당하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[帙冊] 여러 권으로 한 벌을 이루는 책.","[質責] 꾸짖어 바로잡음."]},{"id":424,"category":"한자어","term":"차제","definition":"때마침 주어진 기회.","example":"미뤘던 문제는 차제에 꼭 짚고 넘어가자.","exampleSource":"표준국어대사전 용례","otherMeanings":["[차, 劑] 여러 가지 식물성 생약을 혼합하여 말려서 만든 약제. 끓는 물에 넣어 우려내거나 달여서 먹는다.","[次第] 순서 있게 구분하여 벌여 나가는 관계. 또는 그 구분에 따라 각각에게 돌아오는 기회.","[車制] 수레에 관한 제도라는 뜻으로, 운수(運輸)에 관련된 제도를 이르는 말.","[差除] 벼슬에 임명하던 일.","[差祭] 나라의 제사를 지내는 제관(祭官)으로 임명하던 일."]},{"id":425,"category":"한자어","term":"차출","definition":"어떤 일을 시키기 위하여 인원을 선발하여 냄.","example":"인원 차출.","exampleSource":"표준국어대사전 용례","otherMeanings":["[差出] 예전에, 관원으로 임명하기 위하여 인재를 뽑던 일."]},{"id":426,"category":"한자어","term":"착상","definition":"어떤 일이나 창작의 실마리가 되는 생각이나 구상 따위를 잡음. 또는 그 생각이나 구상.","example":"착상을 얻다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[着床] 포유류의 수정란이 자궁벽에 접착하여 모체의 영양을 흡수할 수 있는 상태가 됨. 또는 그런 현상."]},{"id":427,"category":"한자어","term":"착수","definition":"어떤 일에 손을 댐. 또는 어떤 일을 시작함.","example":"작업 착수.","exampleSource":"표준국어대사전 용례","otherMeanings":["[捉囚] 죄인을 잡아서 가둠.","[窄袖] 좁은 소매.","[着手] 형법에서, 범죄 실행의 개시를 이르는 말. 이것에 의하여 범죄의 법률적 구성 요건이 일부분 실현된다. 살인범이 사람을 죽이려고 칼을 드는 행위 따위를 이른다.","[着手] 바둑에서, 바둑돌을 바둑판에 번갈아 한 수씩 두는 일.","[着水] 수면에 닿음.","[着水] 수상 비행기 따위가 물 위에 내림."]},{"id":428,"category":"한자어","term":"착오","definition":"착각을 하여 잘못함. 또는 그런 잘못.","example":"착오가 생기다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[錯迕] 물건이나 생각 따위가 뒤섞임.","[錯誤] 부주의에서 생기는 추리의 오류.","[錯誤] 사람의 인식과 객관적 사실이 일치하지 않고 어긋나는 일."]},{"id":429,"category":"한자어","term":"착종","definition":"이것저것이 뒤섞여 엉클어짐.","example":"이사하느라고 그의 방에는 많은 책이 착종되어 있다.","exampleSource":"제공 자료 예문","otherMeanings":["[錯綜] 이것저것을 섞어 모음."]},{"id":430,"category":"한자어","term":"찬동","definition":"어떤 행동이나 견해 따위가 옳거나 좋다고 판단하여 그에 뜻을 같이함.","example":"찬동을 얻다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":431,"category":"한자어","term":"창달","definition":"거침없이 쑥쑥 뻗어 나감. 또는 그렇게 되게 함.","example":"민족 문화의 창달.","exampleSource":"표준국어대사전 용례","otherMeanings":["[暢達] 의견, 주장, 견해 따위를 거리낌이나 막힘이 없이 자유롭게 표현하고 전달함."]},{"id":432,"category":"한자어","term":"채근","definition":"어떤 일의 내용, 원인, 근원 따위를 캐어 알아냄.","example":"지금까지 채근을 해 본 바로 그는 이 사건과 무관하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[採根] 식물의 뿌리를 캐냄.","[採根] 어떻게 행동하기를 따지어 독촉함.","[採根] 남에게 받을 것을 달라고 독촉함.","[菜根] 먹을 수 있는 채소의 뿌리.","[菜根] 맛없고 거칠고 보잘것없는 음식을 비유적으로 이르는 말."]},{"id":433,"category":"한자어","term":"책동","definition":"좋지 아니한 일을 몰래 꾸미어 시행함.","example":"암투와 음모와 책동을 자행하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[策動] 남을 부추기어 일정한 방향으로 행동하게 함."]},{"id":434,"category":"한자어","term":"척결","definition":"나쁜 부분이나 요소들을 깨끗이 없애 버림.","example":"비리의 척결.","exampleSource":"표준국어대사전 용례","otherMeanings":["[剔抉] 살을 도려내고 뼈를 발라냄."]},{"id":435,"category":"한자어","term":"천착","definition":"어떤 원인이나 내용 따위를 따지고 파고들어 알려고 하거나 연구함.","example":"세밀한 관찰과 천착을 거듭하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[舛錯] ‘천착하다01’의 어근.","[穿鑿] 구멍을 뚫음.","[穿鑿] 억지로 이치에 닿지 아니한 말을 함."]},{"id":436,"category":"한자어","term":"철석","definition":"매우 굳고 단단한 것을 비유적으로 이르는 말.","example":"두 사람은 철석같은 약속을 맺었다.","exampleSource":"제공 자료 예문","otherMeanings":["[鐵石] 쇠와 돌을 아울러 이르는 말."]},{"id":437,"category":"한자어","term":"첨삭","definition":"시문(詩文)이나 답안 따위의 내용 일부를 보태거나 삭제하여 고침.","example":"첨삭 지도.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":438,"category":"한자어","term":"체계","definition":"일정한 원리에 따라서 낱낱의 부분이 짜임새 있게 조직되어 통일된 전체.","example":"명령 체계.","exampleSource":"표준국어대사전 용례","otherMeanings":["[逮繫] 붙잡아서 옥에 가둠.","[遞計] 예전에, 장에서 비싼 이자로 돈을 꾸어 주고 장날마다 본전의 일부와 이자를 받아들이던 일."]},{"id":439,"category":"한자어","term":"체류","definition":"객지에 가서 머물러 있음.","example":"체류 일정.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":440,"category":"한자어","term":"체불","definition":"마땅히 지급하여야 할 것을 지급하지 못하고 미룸.","example":"체불 노임.","exampleSource":"표준국어대사전 용례","otherMeanings":["[滯佛] 프랑스에 체류함."]},{"id":441,"category":"한자어","term":"초봉","definition":"처음으로 받는 봉급.","example":"요즈음 대기업의 대졸자 초봉이 얼마인지 알기나 해?","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":442,"category":"한자어","term":"촉탁되다","definition":"일이 부탁이 되어 맡겨지다.","example":"그는 자기에게 억지로 촉탁된 일도 기꺼이 하는 것을 보면 참 무던한 사람이야.","exampleSource":"표준국어대사전 용례","otherMeanings":["[囑託, 되다] 대등한 지위에 있는 관청 사이에서 필요한 사무가 다른 관청에 위임되다.","[囑託, 되다] 특정인에 의해 특정한 국가 사무가 수행되고, 이에 대하여 국가로부터 그 사람에게 반대급부가 제공되다. 국가와 개인 사이의 계약이다."]},{"id":443,"category":"한자어","term":"추대","definition":"윗사람으로 떠받듦.","example":"추대를 받다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[推貸] 돈을 돌려서 꾸어 주거나 꾸어 씀.","[錐臺] ‘원뿔대’의 전 용어."]},{"id":444,"category":"한자어","term":"추모","definition":"죽은 사람을 그리며 생각함.","example":"추모 행렬.","exampleSource":"표준국어대사전 용례","otherMeanings":["[秋麰] 가을에 씨를 뿌려 이듬해 초여름에 거두는 보리.","[酋矛] 자루가 짧은 창.","[追募] 추가로 모집함. 또는 그런 모집.","[醜貌] 보기 흉한 용모. 또는 못생긴 용모."]},{"id":445,"category":"한자어","term":"추인","definition":"지나간 사실을 소급하여 추후에 인정함.","example":"교도들이 저절로 이렇게 모여 버리자 하는 수 없이 집회를 추인을 한 셈이었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[追認] 일단 행하여진 불완전한 법률 행위를 뒤에 보충하여 완전하게 하는 일방적 의사 표시. 민법에서는 취소할 수 있는 행위의 추인, 무권 대리 행위의 추인, 무효 행위의 추인의 세 가지 경우에만 인정한다.","[推認] 미루어 인정함.","[篘人] 예전에, 무사들의 교습에 쓰기 위하여 꼴로 사람 모양을 만든 것. 이것을 대상으로 창이나 칼을 쓰는 연습을 하였다.","[麤人] 대승의 수행인에 비하여 거칠고 모자라는 사람이라는 뜻으로, 소승의 수행인을 이르는 말."]},{"id":446,"category":"한자어","term":"추징","definition":"형법상 몰수하여야 할 물건을 몰수할 수 없을 때에 몰수할 수 없는 부분에 해당하는 값의 금전을 징수하는 일.","example":"탈루 세금 추징.","exampleSource":"표준국어대사전 용례","otherMeanings":["[追徵] 부족한 것을 뒤에 추가하여 징수함."]},{"id":447,"category":"한자어","term":"추출","definition":"전체 속에서 어떤 물건, 생각, 요소 따위를 뽑아냄.","example":"이 글에서는 주된 생각이나 의견을 추출하기가 어렵다.","exampleSource":"제공 자료 예문","otherMeanings":["[抽出] 모집단(母集團)에서 표본을 뽑아내는 일.","[抽出] 고체 또는 액체의 혼합물에 용매(溶媒)를 가하여 혼합물 속의 어떤 물질을 용매에 녹여 뽑아내는 일."]},{"id":448,"category":"한자어","term":"추풍선","definition":"가을철의 부채라는 뜻으로, 철이 지나서 쓸모없이 된 물건을 비유적으로 이르는 말.","example":"유행이 지나자 그 물건은 추풍선 신세가 되었다.","exampleSource":"제공 자료 예문","otherMeanings":["[秋風扇] 이성의 사랑을 잃은 사람을 비유적으로 이르는 말."]},{"id":449,"category":"한자어","term":"축수","definition":"오래 살기를 빎.","example":"산신령께 어머님의 축수를 기원하나이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[祝手] 두 손바닥을 마주 대고 빎.","[逐水] 몸 안에 모여 있거나 차 있는 물을 빼내는 일. 또는 그런 방법.","[軸受] 회전 운동이나 직선 운동을 하는 굴대를 받치는 기구.","[縮首] 무섭고 두려워서 고개를 움츠림.","[縮綬] 장구 부속품의 하나. 가죽으로 깔때기처럼 만들어 장구의 좌우 마구리에 얼기설기 얽은 줄의 두 가닥을 끼워서 한쪽으로 밀면 줄이 팽팽해지고, 다른 한쪽으로 밀면 줄이 늘어지게 되어 장구의 소리를 조절한다."]},{"id":450,"category":"한자어","term":"축출","definition":"쫓아내거나 몰아냄.","example":"강제 축출.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":451,"category":"한자어","term":"출시","definition":"상품이 시중에 나옴. 또는 상품을 시중에 내보냄.","example":"우리 회사는 새 제품 출시를 앞두고 있다.","exampleSource":"교정 예문","otherMeanings":[]},{"id":452,"category":"한자어","term":"치성","definition":"있는 정성을 다함. 또는 그 정성.","example":"병자를 치성으로 간호하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[致誠] 신이나 부처에게 지성으로 빎. 또는 그런 일.","[稚省] 신라 때에, 예궁전과 어룡성에 둔 벼슬.","[雉城] 성 위에 낮게 쌓은 담. 여기에 몸을 숨기고 적을 감시하거나 공격하거나 한다.","[齒聲] 혀끝과 윗니 또는 윗잇몸이 닿아서 나는 소리. 현대 국어에서 ‘ㅅ’, ‘ㅆ’, ‘ㄴ’, ‘ㄹ’ 따위를 이른다.","[熾盛] 불길같이 성하게 일어남."]},{"id":453,"category":"한자어","term":"친소","definition":"친함과 친하지 아니함.","example":"그 결과 김 씨는 이 결원을, 자기와의 친소 관계를 따져 그의 독단으로 선발할 수 있는 권한이 주어졌다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":454,"category":"한자어","term":"칩거","definition":"나가서 활동하지 아니하고 집 안에만 틀어박혀 있음.","example":"칩거 생활을 하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":455,"category":"한자어","term":"쾌거","definition":"통쾌하고 장한 행위.","example":"쾌거를 이루다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":456,"category":"한자어","term":"탁견","definition":"두드러진 의견이나 견해.","example":"그는 환경 문제에 대해 탁견을 가지고 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":457,"category":"한자어","term":"통달하다","definition":"말이나 문서로써 기별하여 알리다.","example":"이 법령에 관한 경고를 각 지주에게 통달한 줄 아는데 당신은 아직 그 통고문을 못 보셨습니까?","exampleSource":"표준국어대사전 용례","otherMeanings":["[洞達, 하다] 사물의 이치나 지식, 기술 따위를 훤히 알거나 아주 능란하게 하다.","[通達, 하다] 사물의 이치나 지식, 기술 따위를 훤히 알거나 아주 능란하게 하다."]},{"id":458,"category":"한자어","term":"통변","definition":"말이 통하지 아니하는 사람 사이에서 뜻이 통하도록 말을 옮겨 줌. 또는 그런 일을 하는 사람.","example":"심유경은 왜말을 잘할 줄 알면서도 일부러 심가왕에게 통변을 시켜 따져 본다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":459,"category":"한자어","term":"특기","definition":"특별히 다루어 기록함. 또는 그런 기록.","example":"특기 사항.","exampleSource":"표준국어대사전 용례","otherMeanings":["[特技] 남이 가지지 못한 특별한 기술이나 기능."]},{"id":460,"category":"한자어","term":"팽배","definition":"어떤 기세나 사조 따위가 매우 거세게 일어남.","example":"기대 심리의 팽배.","exampleSource":"표준국어대사전 용례","otherMeanings":["[彭排] 조선 시대 호분위에 속한, 방패를 무기로 쓰던 병종(兵種). 달리기와 힘쓰기를 시험하여 뽑았으며 정원은 5,000명이었다.","[澎湃, /, 彭湃] 큰 물결이 맞부딪쳐 솟구침."]},{"id":461,"category":"한자어","term":"포복절도","definition":"배를 그러안고 넘어질 정도로 몹시 웃음.","example":"그의 유머에 모두가 포복절도하였다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":462,"category":"한자어","term":"폭등","definition":"물건의 값이나 주가 따위가 갑자기 큰 폭으로 오름.","example":"유가 폭등.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":463,"category":"한자어","term":"풍운","definition":"바람과 구름을 아울러 이르는 말.","example":"풍운의 조화를 부릴 줄 아는 신선의 경지에 이르다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[風雲] 용이 바람과 구름을 타고 하늘로 오르는 것처럼 영웅호걸들이 세상에 두각을 나타내는 좋은 기운.","[風雲] 사회적ㆍ정치적으로 세상이 크게 변하려는 기운을 비유적으로 이르는 말.","[風雲] 구름무늬의 하나.","[風韻] 풍류와 운치를 아울러 이르는 말.","[風韻] 바람이 부는 소리."]},{"id":464,"category":"한자어","term":"풍조","definition":"시대에 따라 변하는 세태.","example":"과소비 풍조.","exampleSource":"표준국어대사전 용례","otherMeanings":["[風鳥] 참새목 풍조과의 새를 통틀어 이르는 말. 부리와 꽁지가 길며, 수컷은 몸의 빛깔이 화려하고 여러 가지 동작으로 구애의 춤을 춘다. 40여 종이 뉴기니에 분포한다.","[風潮] 바람과 조수(潮水)를 아울러 이르는 말. 또는 바람에 따라 흐르는 조수.","[風調] 바람이 순조롭게 붊.","[風調] 시가 따위의 가락.","[風操] 높은 지조."]},{"id":465,"category":"한자어","term":"피력하다","definition":"생각하는 것을 털어놓고 말하다.","example":"자신의 견해를 피력하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":466,"category":"한자어","term":"피폐하다","definition":"지치고 쇠약하여지다.","example":"형의 피폐한 모습이 순간적으로 나를 두렵게 했다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[疲斃, 하다] 기운이 지쳐 죽다."]},{"id":467,"category":"한자어","term":"함양","definition":"능력이나 품성 따위를 길러 쌓거나 갖춤.","example":"인격 함양.","exampleSource":"표준국어대사전 용례","otherMeanings":["[咸陽] 경상남도 함양군 가운데에 있는 읍. 창호지가 유명하다. 군청 소재지이다. 면적은 69.35㎢.","[咸陽] → 셴양.","[涵養] 포화대에 물을 보급함. 또는 그런 여러 과정.","[檻羊] 우리 안에 갇힌 양이라는 뜻으로, 자유롭지 못한 처지에 있는 사람을 비유적으로 이르는 말."]},{"id":468,"category":"한자어","term":"항간","definition":"일반 사람들 사이.","example":"항간의 속설.","exampleSource":"표준국어대사전 용례","otherMeanings":["[항, 間] → 행간02.","[巷間] 시골 마을의 사회.","[巷間] 마을과 마을의 사이."]},{"id":469,"category":"한자어","term":"항진","definition":"기세나 기능 따위가 높아짐.","example":"환자는 심장 기능이 항진되어 정밀 검사를 받았다.","exampleSource":"제공 자료 예문","otherMeanings":["[亢進] 위세 좋게 뽐내고 나아감.","[亢進] 병세 따위가 심하여짐.","[降盡] 천도교에서, 세상의 모든 잡귀를 굴복하게 함. 또는 그런 일.","[航進] 비행기나 선박 따위가 앞으로 나아감.","[港津] 배가 안전하게 드나들도록 강가나 바닷가에 부두 따위를 설비한 곳. 보통 기능에 따라 상항ㆍ군항ㆍ어항ㆍ공업항, 위치에 따라 해항ㆍ연안항ㆍ호항, 법제상으로 개항ㆍ자유항ㆍ중계항 따위로 나눈다."]},{"id":470,"category":"한자어","term":"해촉","definition":"위촉했던 직책이나 자리에서 물러나게 함.","example":"규정을 어겼다는 이유로 해촉 통보를 받다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":471,"category":"한자어","term":"해후","definition":"오랫동안 헤어졌다가 뜻밖에 다시 만남.","example":"감격적인 해후.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":472,"category":"한자어","term":"행간","definition":"쓰거나 인쇄한 글의 줄과 줄 사이. 또는 행과 행 사이.","example":"행간이 넓다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[行姦] 간음을 행함.","[行間] 글에 직접적으로 나타나 있지 아니하나 그 글을 통하여 나타내려고 하는 숨은 뜻을 비유적으로 이르는 말."]},{"id":473,"category":"한자어","term":"환담","definition":"정답고 즐겁게 서로 이야기함. 또는 그런 이야기.","example":"환담을 나누다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[幻談] 괴상한 이야기."]},{"id":474,"category":"한자어","term":"환희","definition":"매우 기뻐함. 또는 큰 기쁨.","example":"환희의 함성.","exampleSource":"표준국어대사전 용례","otherMeanings":["[幻戲] 꿈 같은 장난.","[歡喜] 몸의 즐거움과 마음의 기쁨을 통틀어 이르는 말. 자기의 뜻에 알맞은 경계를 만났을 때의 기쁨, 죽어 극락왕생하는 것에 대한 기쁨, 불법(佛法)을 듣고 믿음을 얻어 느끼는 기쁨 따위를 이른다."]},{"id":475,"category":"한자어","term":"횡사","definition":"뜻밖의 재앙으로 죽음.","example":"비명에 횡사를 당하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[橫射] 총포를 좌우로 휘둘러 사격함.","[橫斜] 가로 비낌. 또는 모로 기울어짐.","[橫絲] 피륙이나 그물을 짤 때, 가로 방향으로 놓인 실.","[橫肆] ‘횡사하다04’의 어근.","[黌舍] 공부를 하거나 글을 배우는 집."]},{"id":476,"category":"한자어","term":"효험","definition":"일의 좋은 보람. 또는 어떤 작용의 결과.","example":"효험을 보다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":477,"category":"한자어","term":"흔연하다","definition":"기쁘거나 반가워 기분이 좋다.","example":"반가운 소식을 접하니 기쁘고 흔연하기 짝이 없습니다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":478,"category":"한자어","term":"흠모","definition":"기쁜 마음으로 공경하며 사모함.","example":"흠모의 대상.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":479,"category":"한자어","term":"개선","definition":"잘못된 것이나 부족한 것, 나쁜 것 따위를 고쳐 더 좋게 만듦.","example":"입시 제도 개선.","exampleSource":"표준국어대사전 용례","otherMeanings":["[改選] 의원이나 임원 등이 사퇴하거나 그 임기가 다 되었을 때 새로 선출함.","[疥癬] 옴진드기가 기생하여 일으키는 전염 피부병. 손가락이나 발가락의 사이, 겨드랑이 따위의 연한 살에서부터 짓무르기 시작하여 온몸으로 퍼진다. 몹시 가렵고 헐기도 한다.","[凱旋] 싸움에서 이기고 돌아옴.","[開船] 배가 떠남."]},{"id":480,"category":"한자어","term":"개발","definition":"산업이나 경제 따위를 발전하게 함.","example":"산업 개발.","exampleSource":"표준국어대사전 용례","otherMeanings":["[開發] 토지나 천연자원 따위를 유용하게 만듦.","[開發] 지식이나 재능 따위를 발달하게 함.","[開發] 새로운 물건을 만들거나 새로운 생각을 내어놓음."]},{"id":481,"category":"한자어","term":"계발","definition":"슬기나 재능, 사상 따위를 일깨워 줌.","example":"상상력 계발.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":482,"category":"한자어","term":"수정","definition":"바로잡아 고침.","example":"궤도의 수정.","exampleSource":"표준국어대사전 용례","otherMeanings":["[手錠] → 수갑01.","[水亭] 물가나 물 가운데에 지은 정자.","[水晶] 무색투명한 석영의 하나. 육방주상(六方柱狀)의 결정체이며, 주성분은 이산화 규소이다. 불순물의 혼합 정도에 따라 자색ㆍ흑색ㆍ황색ㆍ홍색 따위의 빛을 띠며, 도장ㆍ장식품ㆍ광학 기계 따위에 쓴다.","[水程] 배를 타고 물로 다니는 길.","[水精] 물의 정령(精靈). 또는 물속에 사는 요정.","[水精] ‘달05’을 달리 이르는 말.","[水精] ‘수정03’을 달리 이르는 말.","[守貞] 동정을 지키는 일.","[受精] 암수의 생식 세포가 하나로 합쳐져 접합자가 됨. 또는 그런 현상. 동물은 정자와 난자가 합쳐져 수정란을 이루고, 종자식물에서는 암술의 씨방 안의 난핵과 수술의 정핵이 결합하여 수정란을 만든다.","[修訂] 글이나 글자의 잘못된 점을 고침.","[修整] 고치어 정돈함.","[修整] 복제(複製)할 때에 복제를 선명하게 하기 위하여 원도(原圖)에 에어브러시를 써서 수정하는 일.","[修整] 사진술에서, 인화(印畫)를 선명하게 하거나 또는 수식할 목적으로 음화(陰畫)에 수정 바니시를 칠하여 연필로 화상(畫像)을 수정하는 일.","[授精] 정자를 난자에 결합시키는 일.","[綏定] 나라를 안정시킴.","[綏靖] 나라와 백성을 편안하게 함.","[輸情] 자기 나라의 내부 형편을 적국에 알려 줌.","[輸情] 죄인이 범죄 사실을 낱낱이 실토함."]},{"id":483,"category":"한자어","term":"경신","definition":"기록경기 따위에서, 종전의 기록을 깨뜨림.","example":"마라톤 세계 기록 경신.","exampleSource":"표준국어대사전 용례","otherMeanings":["[更新] 이미 있던 것을 고쳐 새롭게 함.","[更新] 어떤 분야의 종전 최고치나 최저치를 깨뜨림.","[庚申] 육십갑자의 쉰일곱째.","[京信] 서울에서 온 편지.","[京信] 서울 소식.","[敬信] 공경하며 믿음.","[敬神] 신을 공경함.","[敬愼] 공경하고 삼감.","[輕信] 깊이 생각하지 않고 쉽게 믿음."]},{"id":484,"category":"한자어","term":"독존","definition":"홀로 존재함.","example":"람과 같아서 독존하지 못하는 반쪽인 듯합니다.","exampleSource":"제공 자료 예문","otherMeanings":["[獨尊] 혼자만 높고 귀함."]},{"id":485,"category":"한자어","term":"사사하다","definition":"고마운 뜻을 나타내는 말을 하다.","example":"그는 도움을 준 이들에게 정중히 사사하였다.","exampleSource":"제공 자료 예문","otherMeanings":["[些些, 하다] 하잘것없이 작거나 적다.","[使事, 하다] 어떤 일을 시키다.","[師事, 하다] 스승으로 섬기다. 또는 스승으로 삼고 가르침을 받다.","[斜射, 하다] 햇빛이나 그림자 따위가 비스듬히 비치다.","[斜射, 하다] 대각선 쪽에 있는 목표를 향하여 비스듬히 사격을 하다.","[奢肆, 하다] 사치스럽고 방자하다.","[賜死, 하다] 죽일 죄인을 대우하여 임금이 독약을 내려 스스로 죽게 하다.","[謝辭, 하다] 사죄하는 말을 하다.","[謝辭, 하다] 예를 갖추어 사양하다. 또는 그런 뜻을 나타내는 말을 하다.","[辭謝, 하다] 사절(辭絕)하여 물리치다."]},{"id":486,"category":"한자어","term":"사여하다","definition":"나라나 관청에서 금품을 내려 주다.","example":"왕은 공을 세운 신하에게 토지를 사여하였다.","exampleSource":"제공 자료 예문","otherMeanings":["[私與, 하다] 개인적으로 주다. 또는 사사로이 몰래 주다."]},{"id":487,"category":"한자어","term":"지정","definition":"가리키어 확실하게 정함.","example":"지정 좌석에 앉으시오.","exampleSource":"표준국어대사전 용례","otherMeanings":["‘지정거리다’의 어근.","[支定] 풍년이나 흉년에 관계없이 해마다 일정한 금액으로 정하여진 소작료.","[地丁] 국화과의 여러해살이풀. 원줄기는 없고 이른 봄에 뿌리에서 깃 모양으로 깊이 갈라진 잎이 배게 난다. 높이 30cm 정도의 꽃줄기 끝에 누런 꽃이 4~5월에 두상(頭狀) 화서로 피는데 밤에는 오므라든다. 씨는 수과(瘦果)로 흰 갓털이 있어 바람에 날려 멀리 퍼진다. 잎은 식용하고 꽃 피기 전의 뿌리와 줄기는 한방에서 땀을 내게 하거나 강장(強壯)하는 약으로 쓴다. 한국, 중국 등지에 분포한다.","[地釘] 집터 따위의 바닥을 단단히 하려고 박는 통나무 토막이나 콘크리트 기둥.","[地精] 두릅나뭇과의 여러해살이풀. 높이는 60cm 정도이며, 잎은 줄기 끝에 서너 개씩 돌려나고 장상 복엽이다. 봄에 녹황색의 꽃이 피고 열매는 타원형으로 붉게 익는다. 뿌리는 희고 비대한 다육질인데 강장제로 귀중히 여겨진다. 깊은 산에 야생하거나 밭에서 기르는데 한국의 강원ㆍ경기ㆍ평남ㆍ평북ㆍ함남, 중국 등지에 분포한다.","[池亭] 못가에 있는 정자.","[至正] ‘지정하다01’의 어근.","[至正] 중국 원나라 순제 때의 연호(1341~1370).","[至情] 지극히 두터운 정분.","[至情] 진심에서 우러나오는 참된 정.","[至情] 아주 가까운 친척.","[至精] ‘지정하다02’의 어근.","[知情] 남의 사정을 앎.","[知情] 지성과 감정을 아울러 이르는 말.","[持正] 바른 도리를 취하고 지킴.","[指定] 관공서, 학교, 회사, 개인 등이 어떤 것에 특정한 자격을 줌."]},{"id":488,"category":"한자어","term":"실존","definition":"실제로 존재함. 또는 그런 존재.","example":"신의 실존에 대해 많은 논란이 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[實存] 사물의 본질이 아닌, 그 사물이 존재하는 그 자체. 스콜라 철학에서는 가능적 존재인 본질에 대하여 현실적 존재를 뜻한다.","[實存] 실존 철학에서, 개별자로서 자기의 존재를 자각적으로 물으면서 존재하는 인간의 주체적인 상태."]},{"id":489,"category":"한자어","term":"안광","definition":"사물을 보는 힘.","example":"안광이 날카롭다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[眼光] 눈의 정기.","[眼眶] 눈알의 언저리."]},{"id":490,"category":"한자어","term":"조신","definition":"몸가짐을 조심함.","example":"이제 너도 곧 지아비가 될 것이니 조신을 잘하여라.","exampleSource":"표준국어대사전 용례","otherMeanings":["[早晨] 이른 새벽.","[曺伸] 조선 성종 때의 문인(?~?). 자는 숙분(叔奮). 호는 적암(適庵). 문장과 어학에 능하여 사역원정(司譯院正)으로 발탁되었고, ≪이륜행실도≫를 편찬하였다. 저서에 ≪적암시집≫, ≪소문쇄록(謏聞瑣錄)≫ 따위가 있다.","[祖神] 신으로 모시는 조상.","[租神] 토속 신앙에서, 도조(賭租)를 맡은 귀신.","[朝臣] 조정에서 벼슬살이를 하고 있는 신하.","[潮信] 밀물과 썰물이 드나드는 시각.","[調信] ≪삼국유사≫ 조신몽 설화에 나오는 신라의 승려. 꿈속에서 아름다운 여인과 40여 년간을 함께 돌아다니며 살았는데, 헐벗고 굶주려 끝내 아이를 죽게 하는 따위의 비참한 지경을 당하고, 그 여인과 헤어질 때 꿈에서 깨어나 인생의 고락이 헛됨을 깨닫고 정토사(淨土寺)를 지었다고 전한다.","[竈神] 부엌을 맡는다는 신. 늘 부엌에 있으면서 모든 길흉을 판단한다고 한다."]},{"id":491,"category":"한자어","term":"지체","definition":"때를 늦추거나 질질 끎.","example":"잠시도 지체 말고 바로 집으로 돌아가시오.","exampleSource":"표준국어대사전 용례","otherMeanings":["어떤 집안이나 개인이 사회에서 차지하고 있는 신분이나 지위.","[地體] 지각으로 둘러싸인 지구의 몸체.","[肢體] 팔다리와 몸을 통틀어 이르는 말.","[遲滯] 의무 이행을 정당한 이유 없이 지연하는 일."]},{"id":492,"category":"한자어","term":"육안","definition":"오안의 하나. 사람의 육신에 갖추어진 눈이다. 단지 눈에 보이는 것만을 볼 수 있다.","example":"육안 혜 태양의 흑점은 육안으로는 볼 수 없다.","exampleSource":"제공 자료 예문","otherMeanings":["[肉眼] 안경이나 망원경, 현미경 따위를 이용하지 아니하고 직접 보는 눈.","[肉眼] 식견 없이 단순히 표면적인 현상만을 보는 것."]},{"id":493,"category":"한자어","term":"참석","definition":"모임이나 회의 따위의 자리에 참여함.","example":"참석 인원.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":494,"category":"한자어","term":"혼선","definition":"전신ㆍ전화ㆍ무선 통신 따위에서, 선이 서로 닿거나 전파가 뒤섞여 통신이 엉클어지는 일.","example":"전화에 갑자기 혼선이 생겨 통화를 중단했다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[婚扇] 혼례식 때에 신부의 얼굴을 가리는 데 쓰는 둥근 부채.","[混線] 말이나 일 따위를 서로 다르게 파악하여 혼란이 생김.","[混線] 줄이 갈피를 잡을 수 없게 뒤섞임. 또는 그 줄."]},{"id":495,"category":"한자어","term":"고수","definition":"차지한 물건이나 형세 따위를 굳게 지킴.","example":"강경 노선 고수.","exampleSource":"표준국어대사전 용례","otherMeanings":["산형과의 한해살이풀. 높이는 30~60cm이며, 잎은 어긋나고 잘게 갈라진 우상 복엽이다. 6~7월에 작고 흰 꽃이 복산형 화서로 가지 끝에 피고 열매는 둥글다. 잎과 줄기는 동부 유럽이 원산지로 절에서 많이 재배한다.","[叩首] 머리를 조아리어 존경의 뜻을 나타냄.","[孤愁] 홀로 시름에 잠김. 또는 그런 시름.","[枯樹] 말라서 죽어 버린 나무.","[苦受] 삼수(三受)의 하나. 외계와의 접촉으로 몸과 마음에 생기는 괴로운 느낌을 이른다.","[苦修] 고통을 참고 수행함.","[苦愁] 근심과 걱정으로 괴로워함.","[高手] 바둑이나 장기 따위에서 수가 높음. 또는 그런 사람.","[高手] 어떤 분야나 집단에서 기술이나 능력이 매우 뛰어난 사람.","[高愁] 깊고 큰 시름.","[高壽] 늙은이로서 썩 많은 나이. 또는 그런 나이가 된 사람.","[高壽] 백제 고이왕 때의 대신(?~?). 고이왕 27년(260)에 관제가 마련되자 그 이듬해 위사좌평(衛士佐平)에 임명되어 숙위 병사(宿衛兵事)를 관장하였다.","[鼓手] 북이나 장구 따위를 치는 사람.","[賈竪] 상인을 낮잡아 이르는 말.","[瞽瞍] 눈먼 노인.","[瞽瞍] 중국 순임금 아버지의 다른 이름. 어리석고 사리에 어두웠기 때문에 붙여진 이름이라 한다."]},{"id":496,"category":"한자어","term":"공사","definition":"토목이나 건축 따위의 일.","example":"사옥 신축 공사.","exampleSource":"표준국어대사전 용례","otherMeanings":["무당이 사람의 편에서 신에게 사정을 전하는 일.","[工事] 형사들의 은어로, ‘고문04’을 이르는 말.","[工師] 악기를 연주하거나 수공업에 종사하는 사람의 우두머리.","[公私] 공공의 일과 사사로운 일을 아울러 이르는 말.","[公私] 정부와 민간을 아울러 이르는 말.","[公私] 사회와 개인을 아울러 이르는 말.","[公事] 국가나 공공 단체의 일.","[公事] 조선 시대에, 소송을 속되게 이르던 말.","[公使] 국가를 대표하여 파견되는 외교 사절. 외교부 장관의 감독과 훈령을 받아 조약국에 상주하는 외교 사절로, 대사에 버금가는 계급이다.","[公社] 국가적 사업을 수행하기 위하여 설립된 공공 기업체의 하나. 정부가 전액 출자하는 공법인으로서, 정부의 감독을 받으며 공과금이 면제된다. 한국 수자원 공사, 한국 토지 주택 공사, 한국 관광 공사 따위가 있다.","[公舍] 관청에서 관리에게 빌려주어 살도록 지은 집.","[供司] 절에서 밥 짓는 일을 주로 하는 사람.","[供辭] 조선 시대에, 죄인이 범죄 사실을 진술하던 일. 또는 그 진술.","[空士] ‘공군 사관 학교’를 줄여 이르는 말.","[空事] 보람을 얻지 못하고 쓸데없이 한 노력.","[貢士] 고려 시대에, 향시에 급제하여 국자감시에 응시할 자격이 있는 사람에 대한 칭호. 상공(上貢), 향공(鄕貢), 빈공(賓貢)의 삼공(三貢)이 있었다.","[貢士] 고대 중국에서, 지방의 제후가 천자(天子)에게 유능한 인물을 천거하던 일. 또는 그렇게 천거된 사람.","[貢使] 공물(貢物)을 바치는 일을 맡아보던 사신(使臣)."]},{"id":497,"category":"한자어","term":"관용","definition":"정부 기관이나 국립 공공 기관에서 사용함.","example":"관용 설비.","exampleSource":"표준국어대사전 용례","otherMeanings":["[慣用] 습관적으로 늘 씀. 또는 그렇게 쓰는 것.","[慣用] 오랫동안 써서 굳어진 대로 늘 씀. 또는 그렇게 쓰는 것.","[寬容] 남의 잘못 따위를 너그럽게 받아들이거나 용서함. 또는 그런 용서."]},{"id":498,"category":"한자어","term":"기수","definition":"행사 때 대열의 앞에 서서 기를 드는 일을 맡은 사람.","example":"우리 선수단이 기수를 앞세우고 입장하였다.","exampleSource":"표준국어대사전 용례","otherMeanings":["궁중에서, ‘이불01’을 이르던 말.","[技手] ‘기원01’의 전 용어.","[汽水] 바닷물과 민물이 섞여 염분이 적은 물. 강어귀에 있는 바닷물을 이른다.","[忌數] 마음에 꺼려 싫어하는 숫자. 동양에서의 4나 서양에서의 13 따위를 이른다.","[其數] 그 수.","[奇數] 2로 나누어서 나머지 1이 남는 수. 1, 3, 5, 7, 9 따위의 수를 이른다.","[奇樹] 기이하게 생긴 나무.","[奇獸] 기이한 짐승.","[氣嗽] 기침이 나고 가래가 목구멍에 걸려서 침을 뱉거나 삼키기가 거북하고 가슴이 답답한 병. 특히 여자에게 많다.","[氣數] 저절로 오고 가고 한다는 길흉화복의 운수.","[耆叟] 나이가 들어 늙은 사람.","[起首] 어떤 사실의 시초.","[起溲] 술이 발효하기 시작함.","[起溲] 증편이나 강정 또는 빵 따위를 만들 때에 반죽에 술을 부어 부풀어 오르게 함.","[基數] 수를 나타내는 데 기초가 되는 수. 십진법에서는 0에서 9까지의 정수를 이른다.","[基數] 집합의 원소의 수. 집합 A와 집합 B가 일대일의 대응을 할 때, A와 B는 기수가 같다고 한다.","[淇水] → 치수이강.","[旣遂] 이미 일을 끝냄.","[旣遂] 어떠한 행위가 일정한 범죄의 구성 요건으로 완전히 성립하는 일.","[幾數] 어떤 일을 알아차릴 수 있는 눈치. 또는 일이 되어 가는 야릇한 분위기.","[期首] 기간이나 학기 따위의 처음.","[期數] 이자를 계산할 때, 빌린 돈의 기간을 나타내는 수.","[琪樹] 선경(仙境)에 있다는 옥같이 아름다운 나무.","[琪樹] 눈이 많이 쌓인 나무의 모양.","[琪樹] 아름다운 나무라는 뜻으로, 재주가 뛰어난 사람을 이르는 말.","[旗手] 기를 들고 신호하는 일을 맡은 사람.","[旗手] 사회 활동에서 앞장서서 이끄는 사람을 비유적으로 이르는 말.","[箕宿] 이십팔수의 일곱째 별자리의 별들. 주성(主星)은 궁수자리의 감마성(γ星)이다.","[機首] 비행기의 앞부분.","[機數] 비행기의 수.","[騎手] 경마에서 말을 타는 사람.","[羈愁, /, 羇愁] 객지에서 느끼는 쓸쓸함이나 시름."]},{"id":499,"category":"한자어","term":"동기","definition":"형제와 자매, 남매를 통틀어 이르는 말.","example":"동기끼리 사이좋게 지내다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[冬氣] 겨울철의 기후.","[冬期] 겨울의 시기.","[同期] 같은 시기. 또는 같은 기간.","[同期] 학교나 훈련소 따위에서의 같은 기(期).","[同期] 같은 시기에 같은 곳에서 교육이나 강습을 함께 받은 사람.","[同期] 둘 이상의 주기 현상(週期現象)이 그들 사이의 상호 작용이나 외부로부터의 신호 작용에 의하여, 같은 위상(位相) 또는 일정한 위상차(位相差)가 되는 일. 주파수가 일치하거나 정수비(整數比)의 관계로 된다.","[動氣] 배 속에 적취(積聚)가 있을 때 배꼽 부위에서 뛰는 맥.","[動機] 어떤 일이나 행동을 일으키게 하는 계기.","[動機] 음악 형식을 구성하는 가장 작은 단위. 둘 이상의 음이 모여서 된 것인데, 선율의 기본이 되며 또 일정한 의미를 가진 소절(小節)을 이룬다.","[童伎] 국악에서, 남자아이의 음악이나 춤.","[童妓] 아직 머리를 얹지 아니한 어린 기생.","[銅器] 구리로 만든 그릇."]},{"id":500,"category":"한자어","term":"동화","definition":"성질, 양식(樣式), 사상 따위가 다르던 것이 서로 같게 됨.","example":"자연과의 동화.","exampleSource":"표준국어대사전 용례","otherMeanings":["[同化] 밖으로부터 얻어 들인 지식 따위를 완전히 자기 것으로 만듦.","[同化] 외부에서 섭취한 에너지원을 자체의 고유한 성분으로 변화시키는 일.","[同化] 개인의 사고방식이나 행동이 사회 환경과 일치하는 일.","[同化] 어린이가 현실을 정신과 비슷한 것으로 만드는 일.","[同化] 예전부터 가지고 있던 생각에 따라 새로운 사실을 해석하는 일.","[同化] 감각이나 지각에서, 같은 성질의 것들이 서로 당기는 일.","[同化] 이전의 정황과 같은 유사한 정황에 대하여 같은 반응을 보이는 일.","[同化] 말소리가 서로 이어질 때, 어느 한쪽 또는 양쪽이 영향을 받아 비슷하거나 같은 소리로 바뀌는 소리의 변화를 이르는 말.","[同火] 서로 같은 불을 씀.","[同火] 한 솥의 밥을 먹으며 함께 생활함을 비유적으로 이르는 말.","[同和] 같이 화합함.","[動畫] 만화 영화에서, 한 장면 한 장면의 그림을 이르는 말.","[童畫] 아동이 그린 그림.","[童話] 어린이를 위하여 동심(童心)을 바탕으로 지은 이야기. 또는 그런 문예 작품. 대체로 공상적ㆍ서정적ㆍ교훈적인 내용으로 되어 있다.","[銅貨] 구리로 만든 돈. 실제로는 구리와 주석의 합금으로 되어 있다."]},{"id":501,"category":"한자어","term":"무지","definition":"무늬가 없이 전체가 한 가지 빛깔로 됨. 또는 그런 물건.","example":"무지를 자각하다.","exampleSource":"제공 자료 예문","otherMeanings":["곡식이 완전한 한 섬이 못 되는 것.","무더기로 쌓여 있는 더미.","보통보다 훨씬 정도에 지나치게.","[拇指] 다섯 손가락 가운데 첫째 손가락. 가장 짧고 굵다.","[無知] 아는 것이 없음.","[無知] 미련하고 우악스러움.","[無智] 지혜나 꾀가 없음."]},{"id":502,"category":"한자어","term":"분수령","definition":"어떤 사실이나 사태가 발전하는 전환점 또는 어떤 일이 한 단계에서 전혀 다른 단계로 넘어가는 전환점을 비유적으로 이르는 말.","example":"외국에서 지낸 5년이 그의 인생에 있어 중요한 분수령이 되었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[分水嶺] 분수계가 되는 산마루나 산맥."]},{"id":503,"category":"한자어","term":"사고","definition":"뜻밖에 일어난 불행한 일.","example":"자동차 사고.","exampleSource":"표준국어대사전 용례","otherMeanings":["[司庫] 신라 때에, 조부(調府)에 속한 벼슬. 경덕왕 때 이전의 사지(舍知)를 고친 것으로, 혜공왕 때 다시 사지로 고쳤다.","[史庫] 고려 말기부터 조선 후기까지 실록 따위 국가의 중요한 서적을 보관하던 서고. 강화의 정족산, 무주의 적상산, 봉화의 태백산, 평창의 오대산에 있었다.","[四考] 고려 시대에, 육품 이하 중앙 관직의 벼슬아치들에게 일 년에 네 번 공과(功過)를 심사하던 일. 성종 8년(989)부터 실시하였다.","[四苦] 인생의 네 가지 고통. 나는 것, 늙는 것, 병드는 것, 죽는 것을 이른다.","[四庫] 음양설에서 말하는 진(辰)ㆍ술(戌)ㆍ축(丑)ㆍ미(未)의 네 방향을 이르는 말.","[四庫] 중국 당나라 현종 때 장안과 뤄양(洛陽)의 두 곳에 서적을 경(經), 사(史), 자(子), 집(集)의 네 종류로 나누어 보관하던 서고. 또는 그 서적.","[四顧] 사방을 둘러봄.","[四顧] 동, 서, 남, 북 네 방위를 통틀어 이르는 말.","[死苦] 죽을 때의 고통.","[死苦] 죽을 정도의 심한 고통.","[死苦] 팔고의 하나. 죽음의 괴로움이나 죽음과 관련하여 느끼게 되는 여러 가지 괴로움을 이른다. 사고(四苦)의 하나이기도 하다.","[私考] 사사로운 생각.","[私庫] 사사로운 개인의 창고.","[私稿] 개인의 사사로운 원고.","[事故] 사람에게 해를 입혔거나 말썽을 일으킨 나쁜 짓.","[事故] 어떤 일이 일어난 까닭.","[社告] 회사에서 내는 광고.","[思考] 생각하고 궁리함.","[思考] 심상이나 지식을 사용하는 마음의 작용. 이에 의하여 문제를 해결한다. 직관적 사고, 분석적 사고, 집중적 사고, 확산적 사고 따위가 있다.","[思考] 개념, 구성, 판단, 추리 따위를 행하는 인간의 이성 작용.","[思顧] 두루 생각함.","[思顧] 돌이켜 생각함.","[査考] 자세히 생각하고 조사함.","[師姑] 선종에서, ‘비구니’를 이르는 말.","[斜高] 기둥체, 직원뿔, 직원뿔대의 꼭짓점에서 밑면의 한 점에 이르는 선분의 길이.","[斜高] 정사각뿔의 꼭짓점에서 밑면의 한 변의 중점에 이르는 선분의 길이.","[飼藳] 말이나 소 따위의 먹이로 쓰는 짚.","[謝告] 출판물 따위에서 어떤 사실에 대하여 감사의 뜻을 알림. 또는 그런 글.","[sago] 사고 야자나무의 수심(樹心)에서 나오는 쌀알 모양의 흰 전분. 식용 또는 바르는 풀의 원료로 쓴다."]},{"id":504,"category":"한자어","term":"사주","definition":"사람이 태어난 연월일시의 네 간지(干支). 또는 이에 근거하여 사람의 길흉화복을 알아보는 점.","example":"사주를 보다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[司舟] 신라 때, 선부(船府)에 속한 벼슬. 경덕왕 때 사지(舍知)를 고친 것으로, 혜공왕 때 다시 사지로 고쳤다.","[四周] 사방의 둘레.","[四柱] 혼인이 정해진 뒤 신랑 집에서 신부 집으로 신랑의 사주를 적어서 보내는 종이.","[四洲] 수미산을 중심으로 한 사방의 세계. 남쪽의 섬부주(贍部洲), 동쪽의 승신주(勝神洲), 서쪽의 우화주(牛貨洲), 북쪽의 구로주(俱盧洲)이다.","[史籒] 십체의 하나. 중국 주나라 선왕(宣王) 때에, 태사(太史)였던 주(籒)가 창작한 한자의 자체(字體). 소전(小篆)의 전신으로 대전(大篆)이라고도 한다.","[寺主] 절의 온갖 일을 맡아 이끌어 가는 사람.","[寺主] 당탑을 건조하고 관리하는 사무를 맡은 사람.","[寺主] 신라 때에, 국왕의 고문으로서 불교 정책의 총책임을 맡아보던 승직(僧職). 진흥왕 12년(551)에 고구려에서 온 혜량 법사(惠亮法師)를 처음으로 임명하였다.","[沙柱, /, 砂柱] 사막에서 모래가 회오리바람에 말려 올라가 기둥처럼 되는 현상.","[沙洲, /, 砂洲] 바닷가에 생기는 모래사장. 파도나 조류의 작용으로 강이나 해안의 수면 위에 둑 모양으로 이루어진다.","[私鑄] 돈 따위를 개인이 사사로이 주조함.","[事主] 하느님을 섬김.","[事酒] 일이 있을 때 마시는 술.","[事酒] 예전에 제사에 쓰던 술. 제사가 끝난 뒤에 하인이나 종들에게 주었다.","[使酒] 술을 마신 기운으로 기세를 부림.","[使嗾] 남을 부추겨 좋지 않은 일을 시킴.","[社主] 회사나 결사(結社)의 주인.","[師主] ‘승려01’를 높여 이르는 말.","[紗幮] 거칠게 짠 비단으로 만든 모기장.","[蛇酒] 소주 따위의 독한 술에 뱀을 넣어 우려낸 술.","[飼主] 가축 따위를 먹여 기르는 주인.","[駛走] 빨리 달림.","[賜酒] 임금이 공훈을 세운 신하에게 그 공로를 위로하기 위하여 술을 내리던 일. 또는 그 술."]},{"id":505,"category":"한자어","term":"양식","definition":"뛰어난 식견이나 건전한 판단.","example":"아무 데나 침을 뱉는 것은 양식 있는 행동이 아니다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[洋式] 서양의 양식이나 격식.","[洋食] 서양식 음식이나 식사.","[樣式] 일정한 모양이나 형식.","[樣式] 오랜 시간이 지나면서 자연히 정하여진 방식.","[樣式] 시대나 부류에 따라 각기 독특하게 지니는 문학, 예술 따위의 형식.","[養殖] 물고기나 해조, 버섯 따위를 인공적으로 길러서 번식하게 함.","[糧食] 생존을 위하여 필요한 사람의 먹을거리.","[糧食] 지식이나 물질, 사상 따위의 원천이 되는 것을 비유적으로 이르는 말."]},{"id":506,"category":"한자어","term":"서식","definition":"생물 따위가 일정한 곳에 자리를 잡고 삶.","example":"서식 환경.","exampleSource":"표준국어대사전 용례","otherMeanings":["[書式] 증서, 원서, 신고서 따위와 같은 서류를 꾸미는 일정한 방식."]},{"id":507,"category":"한자어","term":"이상","definition":"순서나 위치가 일정한 기준보다 앞이나 위.","example":"이상에서 살핀 바를 간단히 요약하면 다음과 같다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[二上] 예전에, 시문(詩文)을 평하는 등급 가운데 둘째 등급의 첫째.","[二相] 그 자체만이 가지는 자상(自相)과 다른 것에도 있는 공상(共相)을 통틀어 이르는 말.","[二相] 대지도론에서, 총상(總相)과 별상(別相)을 통틀어 이르는 말.","[二相] 대승기신론에서, 동상(同相)과 이상(異相)을 통틀어 이르는 말.","[二相] 조선 시대에, ‘우찬성’을 달리 이르던 말. 이상(貳相) 가운데 버금이라는 뜻이다.","[以上] 수량이나 정도가 일정한 기준보다 더 많거나 나음. 기준이 수량으로 제시될 경우에는, 그 수량이 범위에 포함되면서 그 위인 경우를 가리킨다.","[以上] 이미 그렇게 된 바에는.","[以上] 서류나 강연 등의 마지막에 써서 ‘끝’의 뜻을 나타내는 말.","[李箱] 시인ㆍ소설가(1910~1937). 본명은 김해경(金海卿). 초현실주의적이고 실험적인 시와 심리주의적 경향이 짙은 독백체의 소설을 써서 문단의 주목을 받았다. 작품에 시 <오감도>, 소설 <날개>, <종생기(終生記)>, 수필 <권태> 따위가 있다.","[泥狀] 진흙 덩어리와 같은 모양.","[泥像] 중국 고대에 부장품으로 쓰던, 진흙으로 빚어 만든 인형. 무인(武人), 무인(舞人), 여성 따위의 인상(人像)이나 토용(土俑)이 있다.","[理想] 생각할 수 있는 범위 안에서 가장 완전하다고 여겨지는 상태.","[理想] 생각할 수 있는 가장 완전한 상태. 절대적인 지성이나 감정의 최고 형태로 실현 가능한 상대적 이상과 도달 불가능한 절대적 이상으로 구별할 수 있다.","[異狀] 평소와는 다른 상태.","[異狀] 서로 다른 모양.","[異相] 보통과는 다른 인상이나 모양.","[異相] 사상의 하나. 사물이 생기면서부터 사라져 갈 때까지 변하여 가는 모양을 이른다.","[異相] 육상의 하나. 현상계가 지닌 서로 다른 모양이나 성질을 이른다.","[異常] 정상적인 상태와 다름.","[異常] 지금까지의 경험이나 지식과는 달리 별나거나 색다름.","[異常] 의심스럽거나 알 수 없는 데가 있음.","[異象] 이상한 모양.","[異象] 특수한 현상.","[貳相] 조선 시대에, ‘좌우찬성’을 달리 이르던 말. 삼정승 다음가는 벼슬이라는 뜻이다.","[履尙] 품행이 고상함.","[履霜] 서리를 밟는다는 것은 곧 물이 얼 겨울철이 닥칠 징조라는 뜻으로, 징조를 보고 장차 다가올 일에 대비하여야 함을 경계하는 말."]},{"id":508,"category":"한자어","term":"장기","definition":"가장 잘하는 재주.","example":"장기 자랑.","exampleSource":"표준국어대사전 용례","otherMeanings":["→ 쟁기01.","[仗器] 전쟁이나 싸움에 사용되는 기구를 통틀어 이르는 말.","[壯妓] 나이가 지긋한 장년의 기생.","[壯氣] 건장한 기운. 또는 왕성한 원기.","[杖期] 상주가 상복에 지팡이를 짚고 상례(喪禮)를 지내는 일 년 동안의 기간.","[杖朞] 상례(喪禮)에서, 상주가 상장(喪杖)을 짚고 생베로 지은 상복을 일 년 동안 입는 거상(居喪). 조부가 살아 있고 조모가 사망하였거나, 아버지가 사망한 뒤 재가한 어머니가 사망하였거나, 아버지에게서 쫓겨난 어머니가 사망하였거나, 아들이 있는 서모가 사망하였을 때에 이 복제를 따랐다.","[長崎] → 나가사키.","[長期] 긴 기간.","[長旗] 나부끼는 부분이 기다란 기.","[將棋, /, 將碁] 나무로 만든 32짝의 말을 붉은 글자와 푸른 글자의 두 종류로 나누어 판 위에 벌여 놓고 서로 번갈아 가며 공격과 수비를 교대로 하여 승부를 가리는 놀이. 또는 그런 놀이를 하는 데 쓰는 기구.","[將器] 장수가 될 만한 인재.","[帳記, /, 掌記] 물건이나 논밭 따위를 팔고 사는 데 관한 품명이나 값 따위를 적어 놓은 글.","[帳記, /, 掌記] 물품의 목록.","[場技] 주로 광대가 땅에서 뛰어넘으며 펼치는 묘기나 재주.","[葬期] 상(喪)을 당한 날로부터 장사를 치르는 날까지의 기간. 예전에는 법으로 엄격히 규정하였는데, 임금이나 왕비는 5개월, 사품 이상의 문무관은 3개월, 오품 이하 문무관과 서민은 1개월 이내로 하였다.","[葬器] 장례에 쓰는 여러 가지 기구.","[瘴氣] 축축하고 더운 땅에서 생기는 독한 기운.","[臟氣] 오장(五臟)의 기(氣). 또는 그것의 기능 및 활동.","[臟器] 내장의 여러 기관."]},{"id":509,"category":"한자어","term":"군무","definition":"여러 사람이 무리를 지어 춤을 춤. 또는 그 춤.","example":"군무를 추다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[軍務] 군사(軍事)에 관한 일.","[軍務] 군인으로서 군대에 복무하는 일.","[軍舞] ‘군사 무용’을 줄여 이르는 말."]},{"id":510,"category":"한자어","term":"독무","definition":"혼자서 추는 춤.","example":"독무(舞) 무용」 혼자서 추는 춤.","exampleSource":"제공 자료 예문","otherMeanings":["[毒霧] 독한 기운이 있는 안개."]},{"id":511,"category":"한자어","term":"가무","definition":"노래와 춤을 아울러 이르는 말.","example":"가무에 능한 기생.","exampleSource":"표준국어대사전 용례","otherMeanings":["[加貿] 관세의 수입을 늘리기 위하여 무역량을 늘리던 일. 해마다 오는 일본 사신에게 예물로 주던 인삼의 경비를 왜관에서 무역하는 사람에게 거둔 관세로 충당하던 때에, 인삼값이 모자랄 경우에 행하였다.","[家務] 살림을 꾸려 나가면서 하여야 하는 여러 가지 일. 빨래, 밥하기, 청소 따위를 이른다.","[家務] 자기 집이나 가까운 친척 집에 생기는 일이나 행사.","[笳舞] 신라 때에, 피리에 맞추어 춤을 추며 노래하던 무악(舞樂). 내물왕 때 향인(鄕人)들이 지어 즐겼다고 하는데, 가사와 악보는 전하지 않는다.","[歌舞] 노래하면서 춤을 춤."]},{"id":512,"category":"한자어","term":"농무","definition":"풍물놀이에 맞추어 추는 춤. 꽹과리, 북, 태평소, 징 따위의 소리에 맞추어 벙거지에 매단 털이나 띠를 빙빙 돌리며 흥겹게 춘다.","example":"농악대의 장단에 맞춰 흥겨운 농무가 펼쳐졌다.","exampleSource":"제공 자료 예문","otherMeanings":["[農務] 농사짓는 일. 또는 농사와 관계되는 일.","[農務] 농업에 관한 사무나 정무.","[濃霧] 자욱하게 낀 짙은 안개."]},{"id":513,"category":"한자어","term":"승무","definition":"장삼과 고깔을 걸치고 북채를 쥐고 추는 민속춤. 끝내 수행을 이루지 못한 고뇌를 법고를 두드려서 잊으려는 파계승의 심정을 나타낸다.","example":"승무를 추다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[乘務] 운행 중인 차, 기차, 배, 비행기 따위의 안에서 운행과 관련된 직무와 승객에 관한 사무를 맡아봄.","[陞廡] 학덕(學德)이 있는 사람을 문묘(文廟)에 올려 함께 제사 지내던 일.","[僧舞] 조지훈이 지은 시. 승무를 추고 있는 여승을 소재로 하여 삶의 번뇌를 극복하고자 하는 염원을 회화적으로 형상화한 작품이다."]},{"id":514,"category":"한자어","term":"일부","definition":"한 부분. 또는 전체를 여럿으로 나눈 얼마.","example":"일부 지역.","exampleSource":"표준국어대사전 용례","otherMeanings":["[一夫] 한 사람의 평범한 남자.","[一富] 첫째가는 큰 부자.","[日附] 서류 따위에 적는 그날그날의 일자.","[日賦] 물건값이나 빚 따위의 일정한 금액을 며칠에 나누어 날마다 내는 일. 또는 그런 돈."]},{"id":515,"category":"한자어","term":"수려하다","definition":"빼어나게 아름답다.","example":"산수가 수려하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":516,"category":"한자어","term":"화려하다","definition":"환하게 빛나며 곱고 아름답다.","example":"의상이 화려하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[華麗, 하다] 어떤 일이나 생활 따위가 보통 사람들이 누리기 어려울 만큼 대단하거나 사치스럽다."]},{"id":517,"category":"한자어","term":"호화","definition":"사치스럽고 화려함.","example":"호화 별장.","exampleSource":"표준국어대사전 용례","otherMeanings":["[號火] 신호를 하기 위하여 올리는 불. 봉화 따위가 있다.","[糊化] 녹말에 물을 넣어 가열할 때에 부피가 늘어나고 점성이 생겨서 풀처럼 끈적끈적하게 됨. 또는 그런 현상."]},{"id":518,"category":"한자어","term":"영화","definition":"몸이 귀하게 되어 이름이 세상에 빛남.","example":"부귀와 영화를 누리다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[映畫] 일정한 의미를 갖고 움직이는 대상을 촬영하여 영사기로 영사막에 재현하는 종합 예술.","[英貨] 영국의 화폐. 곧 파운드를 이른다.","[英華] 밖으로 드러나는 아름다운 색채.","[英華] 뛰어난 시나 문장을 비유적으로 이르는 말.","[英華] 영국과 중국을 아울러 이르는 말.","[穎花] 수상 화서로 핀 꽃.","[嬰禍] 화(禍)를 입은 일.","[靈化] 어떤 사물이 신령스럽게 됨. 또는 그렇게 되게 함."]},{"id":519,"category":"한자어","term":"번화하다","definition":"번성하고 화려하다.","example":"번화한 거리.","exampleSource":"표준국어대사전 용례","otherMeanings":["[繁華, 하다] 얼굴에 달기(達氣)가 있고 화려하다."]},{"id":520,"category":"한자어","term":"환갑","definition":"육십갑자의 ‘갑(甲)’으로 되돌아온다는 뜻으로, 예순한 살을 이르는 말.","example":"환갑을 맞이하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[環甲] 바탕이 되는 옷에 쇠고리를 빽빽하게 박아 붙인 갑옷."]},{"id":521,"category":"한자어","term":"외래어","definition":"외국에서 들어온 말로 국어처럼 쓰이는 단어. 버스, 컴퓨터, 피아노 따위가 있다.","example":"어느 시대이든 외국 문물이 들어오게 되면 외래어는 생기게 마련이다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":522,"category":"한자어","term":"관형사","definition":"체언 앞에 놓여서, 그 체언의 내용을 자세히 꾸며 주는 품사. 조사도 붙지 않고 어미 활용도 하지 않는데, ‘순 살코기’의 ‘순’과 같은 성상 관형사, ‘저 어린이’의 ‘저’와 같은 지시 관형사, ‘한 사람’의 ‘한’과 같은 수 관형사 따위가 있다.","example":"‘새’는 ‘새 옷’에서 명사를 꾸미는 관형사이다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":523,"category":"한자어","term":"유의어","definition":"뜻이 서로 비슷한 말.","example":"‘기쁘다’와 ‘즐겁다’는 서로 유의어 관계에 있다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":524,"category":"한자어","term":"반의어","definition":"그 뜻이 서로 정반대되는 관계에 있는 말. 한 쌍의 말 사이에 서로 공통되는 의미 요소가 있으면서 동시에 서로 다른 한 개의 의미 요소가 있어야 한다. ‘남자’와 ‘여자’, ‘총각’과 ‘처녀’, ‘위’와 ‘아래’, ‘작다’와 ‘크다’, ‘오다’와 ‘가다’ 따위이다.","example":"‘높다’와 ‘낮다’는 반의어이다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":525,"category":"한자어","term":"접전","definition":"경기나 전투에서 서로 맞붙어 싸움. 또는 그런 경기나 전투.","example":"순간 문치걸은 송기화와 헌병들 사이에 접전이 벌어진 것이라 판단하고 오르막길로 뛰어올라갔다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[接戰] 서로 힘이 비슷하여 승부가 쉽게 나지 아니하는 경기나 전투."]},{"id":526,"category":"한자어","term":"낙승","definition":"힘들이지 아니하고 쉽게 이김.","example":"낙승을 거두다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[落僧] 타락한 승려."]},{"id":527,"category":"한자어","term":"석패","definition":"경기나 경쟁에서 약간의 점수 차이로 아깝게 짐.","example":"우리 팀은 한 점 차이로 아쉽게 석패했다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":528,"category":"한자어","term":"신승","definition":"경기 따위에서 힘들게 겨우 이김.","example":"어제 열린 축구 경기에서는 우리 편이 3 대 2로 한 점 차의 신승을 거두었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[神僧] 정신이 신령에 통하여 모르는 것이 없이 잘 아는 승려.","[神僧] 꿈속 따위에 나타나는 신비스러운 승려.","[新升] 새로 제정되어 현재 쓰고 있는 되. 용량이 2리터이다."]},{"id":529,"category":"한자어","term":"우승","definition":"경기, 경주 따위에서 이겨 첫째를 차지함. 또는 첫째 등위.","example":"영광스러운 우승.","exampleSource":"표준국어대사전 용례","otherMeanings":["[牛蠅] 쇠파릿과의 곤충. 몸의 길이는 1.5cm 정도이며 누런 갈색이다. 온몸에 검은 털이 나 있고 위 몸통에 몇 개의 검은 줄무늬가 있다. 소나 말의 살갗을 파고들어 피를 빨아 먹고 살며, 온대 지방에 널리 분포한다.","[右丞] 고려 시대에, 상서도성에 속한 종삼품 벼슬.","[右丞] 조선 전기에, 삼사에 속한 종삼품 벼슬.","[郵丞] 조선 후기에, ‘역승’을 달리 이르던 말.","[愚僧] 어리석은 승려.","[愚僧] 어리석은 승려라는 뜻으로, 승려가 자기를 낮추어 이르는 일인칭 대명사."]},{"id":530,"category":"한자어","term":"건조","definition":"말라서 습기가 없음.","example":"건조(말라서 습기가 없음.","exampleSource":"제공 자료 예문","otherMeanings":["[建造] 건물이나 배 따위를 설계하여 만듦.","[乾造] 성명학(星命學)에서 이르는 남자의 운명.","[乾棗] 말린 대추.","[乾燥] 물기나 습기가 말라서 없어짐. 또는 물기나 습기를 말려서 없앰.","[乾燥] 분위기, 정신, 표현, 환경 따위가 여유나 윤기 없이 딱딱함."]},{"id":531,"category":"한자어","term":"가습기","definition":"수증기를 내어 실내의 습도를 조절하는 전기 기구.","example":"방이 건조해지지 않도록 가습기를 틀어 놓았다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":532,"category":"한자어","term":"환기","definition":"탁한 공기를 맑은 공기로 바꿈.","example":"실내 환기.","exampleSource":"표준국어대사전 용례","otherMeanings":["[喚起] 주의나 여론, 생각 따위를 불러일으킴."]},{"id":533,"category":"한자어","term":"오염","definition":"더럽게 물듦. 또는 더럽게 물들게 함.","example":"이 지역은 지하수 오염이 심각한 상태이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[汚染] 핵무기 따위의 방사성 물질이 목표물이나 대기 속에 머무르는 상태.","[汚染] 미생물이나 다세포 생물 조직 따위를 순수 배양할 때, 다른 미생물이 밖에서 유입되어 자라는 일."]},{"id":534,"category":"한자어","term":"부의금","definition":"부의로 보내는 돈.","example":"부의금을 내다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":535,"category":"한자어","term":"주례사","definition":"주례가 예식에서 행하는 의례적인 축사.","example":"신랑, 신부의 입장 후 주례사가 이어졌다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":536,"category":"한자어","term":"관혼상제","definition":"관례, 혼례, 상례, 제례를 아울러 이르는 말.","example":"관혼상제의 간소화.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":537,"category":"한자어","term":"풍습","definition":"풍속과 습관을 아울러 이르는 말.","example":"우리 민족 고유의 전통과 풍습.","exampleSource":"표준국어대사전 용례","otherMeanings":["[風濕] 풍사(風邪)와 습사(濕邪)가 겹친 것. 또는 이로 인하여 생긴 병증. 뼈마디가 쑤시고 켕기며 굽혔다 폈다 하기가 어렵다."]},{"id":538,"category":"한자어","term":"대체","definition":"다른 것으로 대신함.","example":"대체 방안.","exampleSource":"표준국어대사전 용례","otherMeanings":["[大體] 일이나 내용의 기본적인 큰 줄거리.","[大體] 다른 말은 그만두고 요점만 말하자면.","[對替] 어떤 금액을 한 계정에서 다른 계정으로 대체하는 일. 또는 그 계정."]},{"id":539,"category":"한자어","term":"상식","definition":"사람들이 보통 알고 있거나 알아야 하는 지식. 일반적 견문과 함께 이해력, 판단력, 사리 분별 따위가 포함된다.","example":"상식 밖의 행동.","exampleSource":"표준국어대사전 용례","otherMeanings":["[上食] 상가(喪家)에서 아침저녁으로 궤연 앞에 올리는 음식.","[尙食] 고려 시대에 둔 내명부의 벼슬.","[尙食] 조선 시대에, 내명부 가운데 식사에 관한 일을 맡아보던 종오품 벼슬.","[相識] 서로 얼굴이나 알 정도의 친분이 있음.","[常式] 일정한 법률이나 격식.","[常食] 늘 먹음. 또는 그런 음식."]},{"id":540,"category":"한자어","term":"이론","definition":"사물의 이치나 지식 따위를 해명하기 위하여 논리적으로 정연하게 일반화한 명제의 체계.","example":"경제 이론.","exampleSource":"표준국어대사전 용례","otherMeanings":["[理論] 실증성이 희박한, 순 관념적으로 조직된 논리.","[異論] 달리 논함. 또는 다른 이론(理論)이나 의견.","[irone] 붓꽃과 아이리스속 식물의 뿌리에서 얻는 무색 액체. 휘발성 기름 성분으로 향료에 쓴다. 화학식은 C<sub style='font-size:11px;'>14</sub>H<sub style='font-size:11px;'>22</sub>O."]},{"id":541,"category":"한자어","term":"과정","definition":"일정한 기간에 교육하거나 학습하여야 할 과목의 내용과 분량.","example":"오늘로 1학년 1학기 과정을 마치고 여름 방학에 들어간다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[科程] 학교에서 학생들이 공부하는 과목의 내용과 체계.","[過政] ‘과도 정부’를 줄여 이르는 말.","[過程] 일이 되어 가는 경로.","[課程] 해야 할 일의 정도.","[課程] 대학에서, 일정한 분야의 교수ㆍ연구를 위한 전문적인 절차."]},{"id":542,"category":"한자어","term":"수료","definition":"일정한 학과를 다 배워 끝냄.","example":"석사 과정 수료.","exampleSource":"표준국어대사전 용례","otherMeanings":["[水蓼] 마디풀과의 한해살이풀. 높이는 40~80cm이며 잎은 어긋나고 피침 모양이다. 6~9월에 꽃잎의 끝이 붉은색을 띠는 연녹색 꽃이 수상(穗狀) 화서로 피고 열매는 수과(瘦果)이다. 잎과 줄기는 짓이겨 물에 풀어서 고기를 잡는 데 쓴다. 잎은 매운맛이 나며 조미료로 쓰이기도 한다. 한국, 일본, 북미, 유럽 등지에 분포한다."]},{"id":543,"category":"한자어","term":"사상","definition":"어떠한 사물에 대하여 가지고 있는 구체적인 사고나 생각.","example":"사상의 자유.","exampleSource":"표준국어대사전 용례","otherMeanings":["[史上] 역사에 나타나 있는 바.","[四相] 사람이 겪는 네 가지 모습. 생, 노, 병, 사를 이른다.","[四相] 만물이 변하는 네 가지 모습. 생상(生相), 주상(住相), 이상(異相), 멸상(滅相)을 이른다.","[四相] 중생이 실재라고 믿는 네 가지 상. 아상(我相), 인상(人相), 중생상(衆生相), 수자상(壽者相)을 이른다.","[四象] 일월성신을 통틀어 이르는 말.","[四象] 음양(陰陽)의 네 가지 상징인 태양, 태음, 소양, 소음을 통틀어 이르는 말.","[四象] 땅속의 물, 불, 흙, 돌을 통틀어 이르는 말.","[死狀] 거의 죽게 된 상태.","[死狀] 죽어 버린 상태.","[死相] 거의 다 죽게 된 상. 또는 죽을 조짐이 나타난 상.","[死相] 죽은 사람의 얼굴.","[死傷] 죽거나 다침.","[私商] 개인이 하는 장사. 또는 그 장수.","[私傷] 공무(公務)가 아닌 사사로운 일로 입은 부상.","[私償] 사사롭게 진 빚을 갚음.","[事狀, /, 事相] 일이 되어 가는 형편이나 상황. 또는 벌어진 일의 상태.","[事相] 진리를 따라서 나타나는 현상계의 낱낱의 차별된 모양.","[事相] 밀교에서, 조단(造壇)ㆍ관정(灌頂)ㆍ인계(印契)ㆍ진언 따위의 밀교적 상징으로서 표현되는 구체적이고도 실제적인 의례와 행법.","[事象] 관찰할 수 있는 사물과 현상.","[事象] 어떤 실험이나 시행(試行)에서 일어날 수 있는 결과. 예를 들어 주사위를 던질 때 1이 나온다든가, 짝수가 나온다든가, 4 이상이 나온다든가 하는 따위이다.","[使相] 중국 당나라ㆍ송나라 때에, 재상의 호칭이 추가된 절도사나 절도사의 호칭이 추가된 은퇴한 재상을 이르던 말.","[泗上] 공자의 문하. 또는 그 학파. 공자가 화이수이강(淮水江)의 지류인 쑤수이강(泗水江) 변에서 제자를 가르쳤다는 데에서 유래한다.","[思想] 판단, 추리를 거쳐서 생긴 의식 내용.","[思想] 논리적 정합성을 가진 통일된 판단 체계.","[思想] 지역, 사회, 인생 따위에 관한 일정한 인식이나 견해.","[沙上, /, 砂上] 모래 위.","[捨象] 유의할 필요가 있는 현상의 특징 이외의 다른 성질을 버리는 일. 추상 작용에 필연적으로 수반되는 부정적 측면이다.","[蛇床] ‘사상자03「1」’의 성숙한 열매. 요통, 발기 불능(勃起不能), 낭습증 따위의 치료에 쓴다.","[絲狀] 실처럼 길고 가는 모양.","[寫象, /, 寫像] 지각 또는 사고에 의하여 과거의 대상이 의식에 다시 나타나는 상태.","[寫像] 물체에서 나온 빛이 거울에 반사 또는 굴절된 다음에 모여서 생기는 상(像).","[寫像] 광학계에서, 물체와 상과의 대응을 이르는 말.","[寫像] 어떤 집합의 임의의 원소가 다른 집합의 하나의 원소에 대응할 때, 그 두 집합 간의 대응 관계."]},{"id":544,"category":"한자어","term":"종교","definition":"신이나 초자연적인 절대자 또는 힘에 대한 믿음을 통하여 인간 생활의 고뇌를 해결하고 삶의 궁극적인 의미를 추구하는 문화 체계. 그 대상ㆍ교리ㆍ행사의 차이에 따라 여러 가지가 있는데, 애니미즘ㆍ토테미즘ㆍ물신 숭배 따위의 초기적 신앙 형태를 비롯하여 샤머니즘이나 다신교ㆍ불교ㆍ기독교ㆍ이슬람교 따위의 세계 종교에 이르기까지 비제도적인 것과 제도적인 것이 있다.","example":"종교를 믿다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":545,"category":"한자어","term":"인식","definition":"사물을 분별하고 판단하여 앎.","example":"인식이 높다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[認識] 자극을 받아들이고, 저장하고, 인출하는 일련의 정신 과정. 지각, 기억, 상상, 개념, 판단, 추리를 포함하여 무엇을 안다는 것을 나타내는 포괄적인 용어로 쓴다.","[認識] 일반적으로 사람이 사물에 대하여 가지는, 그것이 진(眞)이라고 하는 것을 요구할 수 있는 개념. 또는 그것을 얻는 과정."]},{"id":546,"category":"한자어","term":"패배","definition":"겨루어서 짐.","example":"찬란한 승리와 참담한 패배.","exampleSource":"표준국어대사전 용례","otherMeanings":["[敗北] 싸움에 져서 달아남."]},{"id":547,"category":"한자어","term":"불행","definition":"행복하지 아니함.","example":"불행을 느끼다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[不幸] 행복하지 아니한 일. 또는 그런 운수."]},{"id":548,"category":"한자어","term":"단장","definition":"몹시 슬퍼서 창자가 끊어지는 듯함.","example":"단장의 비애.","exampleSource":"표준국어대사전 용례","otherMeanings":["[丹粧] 얼굴, 머리, 옷차림 따위를 곱게 꾸밈.","[丹粧] 건물, 거리 따위를 손질하여 꾸밈.","[單葬] 주검을 하나만 묻은 무덤.","[短杖] 짧은 지팡이.","[短長] 길고 짧음.","[短章] 짧은 시가(詩歌)나 문장.","[短牆] 낮은 담.","[團長] ‘단’ 자가 붙은 단체의 우두머리.","[端莊] 단정(端整)하고 장엄함.","[端裝] 단정하게 차림.","[壇場] 단을 마련하여 놓은 곳.","[斷章] 한 체계로 묶지 아니하고 몇 줄씩의 산문체로 토막을 지어 적은 글.","[斷章] 가벼운 피아노 소곡. 베토벤의 ≪피아노 소곡집≫ 따위에서 볼 수 있다.","[簞匠] 조선 시대에, 죽순 껍질과 갈대로 돗자리를 만드는 일을 맡아 하던 사람."]},{"id":549,"category":"한자어","term":"궁핍","definition":"몹시 가난함.","example":"궁핍에 시달리다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":550,"category":"한자어","term":"난색","definition":"꺼리거나 어려워하는 기색.","example":"난색을 보이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[暖色, /, 煖色] 따뜻한 느낌을 주는 색. 노란색, 빨간색 계통의 색이다.","[難色] 비난하려는 낯빛."]},{"id":551,"category":"한자어","term":"분열","definition":"집단이나 단체, 사상 따위가 갈라져 나뉨.","example":"귀족 사회의 분열과 대립.","exampleSource":"표준국어대사전 용례","otherMeanings":["[分列] 각각 갈라져서 늘어섬. 또는 그렇게 함.","[分裂] 찢어져 나뉨.","[分裂] 원자핵이 방사능과 열을 방출하면서 다른 원자핵들로 쪼개지는 현상.","[分裂] 하나의 세포로 이루어진 개체가 둘 이상으로 나뉘어 불어나는 무성 생식. 주로 단세포 원생생물이나 박테리아에서 일어난다."]},{"id":552,"category":"한자어","term":"신봉","definition":"사상이나 학설, 교리 따위를 옳다고 믿고 받듦.","example":"계율의 신봉.","exampleSource":"표준국어대사전 용례","otherMeanings":["[信封] 편지 봉투.","[神鳳] 중국에서, 영묘한 징조로 여기는 봉황을 이르는 말.","[新峯] 함경북도 회령군과 부령군 사이에 있는 산봉우리. 높이는 1,145미터."]},{"id":553,"category":"한자어","term":"점멸","definition":"점점 멸망하여 감.","example":"찬란한 문화를 꽃피웠던 나라도 점멸의 길로 접어든 경우가 많다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[點滅] 등불이 켜졌다 꺼졌다 함. 또는 등불을 켰다 껐다 함.","[點滅] 어떤 생각이나 현상 따위가 생겨났다 사라졌다 함을 비유적으로 이르는 말."]},{"id":554,"category":"한자어","term":"불굴","definition":"온갖 어려움에도 굽히지 아니함.","example":"불굴의 신념.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":555,"category":"한자어","term":"책임","definition":"맡아서 해야 할 임무나 의무.","example":"연락 책임.","exampleSource":"표준국어대사전 용례","otherMeanings":["[責任] 어떤 일에 관련되어 그 결과에 대하여 지는 의무나 부담. 또는 그 결과로 받는 제재(制裁).","[責任] 위법한 행동을 한 사람에게 법률적 불이익이나 제재를 가하는 일. 민사 책임과 형사 책임이 있다."]},{"id":556,"category":"한자어","term":"질서","definition":"혼란 없이 순조롭게 이루어지게 하는 사물의 순서나 차례.","example":"질서 의식.","exampleSource":"표준국어대사전 용례","otherMeanings":["[姪壻] 조카딸의 남편을 이르는 말.","[疾徐] 빠름과 느림."]},{"id":557,"category":"한자어","term":"염원","definition":"마음에 간절히 생각하고 기원함. 또는 그런 것.","example":"우리 겨레의 염원.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":558,"category":"한자어","term":"지지","definition":"어떤 사람이나 단체 따위의 주의ㆍ정책ㆍ의견 따위에 찬동하여 이를 위하여 힘을 씀. 또는 그 원조.","example":"지지 세력.","exampleSource":"표준국어대사전 용례","otherMeanings":["어린아이의 말로, 더러운 것을 이르는 말.","수다스럽게 지껄이는 소리. 또는 그 모양.","‘지지하다02’의 어근.","[地, 지] → 지기03「2」.","[支持] 무거운 물건을 받치거나 버팀.","[支持] 주가 하락이 매입 세력에 의하여 어느 선에서 더 이상 계속되지 아니하는 일.","[止持] 몸과 말로 하는 나쁜 짓을 억제하여 죄업을 짓지 아니함.","[地支] 육십갑자의 아래 단위를 이루는 요소. 자(子), 축(丑), 인(寅), 묘(卯), 진(辰), 사(巳), 오(午), 미(未), 신(申), 유(酉), 술(戌), 해(亥)이다.","[地誌] 특정 지역의 자연 및 인문 현상을 백과사전식으로 나누어 기술한 책.","[地誌] 특정 지역의 지역적 성격을 종합적으로 구명하는 학문. 지리학의 한 분야이다.","[至知] 더없이 뛰어난 지혜. 또는 그런 지혜가 있는 사람.","[枝指] → 기지04.","[知止] 자신의 분수에 넘치지 아니하도록 그칠 줄을 앎.","[祇支] 승려가 가사 밑에 입는 옷. 왼쪽 어깨로부터 왼쪽 팔을 덮고, 한쪽 끝은 오른쪽 겨드랑이에 비스듬히 낀다.","[紙地] 종이의 품질.","[紙誌] 신문과 잡지 따위를 통틀어 이르는 말.","[智智] 지혜 가운데 지혜라는 뜻으로, 가장 뛰어난 부처의 지혜를 이르는 말.","[遲遲] ‘지지하다05’의 어근."]},{"id":559,"category":"한자어","term":"여론","definition":"사회 대중의 공통된 의견.","example":"여론 정치.","exampleSource":"표준국어대사전 용례","otherMeanings":["[餘論] 골자를 논의하고 난 뒤의 나머지 논의.","[輿論] 1922년에 미국의 평론가 리프먼(Lippmann, W.)이 쓴 여론 연구서. 여론을 실체화하고 현실적인 형성 과정 및 기능을 밝혔다."]},{"id":560,"category":"한자어","term":"방송","definition":"라디오나 텔레비전 따위를 통하여 널리 듣고 볼 수 있도록 음성이나 영상을 전파로 내보내는 일. 특정 지역을 대상으로 유선(有線)으로 행하는 것을 포함하기도 한다.","example":"교내 방송.","exampleSource":"표준국어대사전 용례","otherMeanings":["[放送] 죄인을 감옥에서 나가도록 풀어 주던 일."]},{"id":561,"category":"한자어","term":"유선","definition":"전선에 의한 통신 방식.","example":"서울과 대전을 유선으로 연결하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[乳腺] 유방(乳房) 속에 있는, 젖이 나오는 샘.","[油扇] 기름종이를 바른 부채.","[流線] 운동하고 있는 유체에서 각 점에 대한 접선의 방향이 유체가 흐르는 방향과 일치하도록 그은 가상적인 곡선. 유체의 흐름을 묘사하는 데 편리하게 이용한다.","[遊船] 뱃놀이를 할 때 타는 배.","[儒先] 옛 선비. 또는 선대(先代)의 유학자.","[諭善] 조선 시대에, 세손강서원에 속한 벼슬 이름. 영조 때 둔 것으로, 좌유선ㆍ우유선을 한 명씩 두었는데, 당하(堂下) 삼품에서 종이품 사이의 사람으로 임명하였다."]},{"id":562,"category":"한자어","term":"정권","definition":"정치상의 권력. 또는 정치를 담당하는 권력.","example":"정권 교체.","exampleSource":"표준국어대사전 용례","otherMeanings":["[正拳] 태권도에서, 주먹 쥔 손의 손등과 직각을 이루는 네 손가락의 마디 부분.","[正權] 정당한 권리.","[呈券] 과거의 답안을 시관(試官)에게 내던 일."]},{"id":563,"category":"한자어","term":"서두","definition":"일이나 말의 첫머리.","example":"서두를 떼다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[序頭] 어떤 차례나 순서의 맨 앞.","[書頭] 글을 시작하는 첫머리.","[書頭] 책의 윗난에 있는 빈자리.","[書頭] 제본할 때, 초벌 매어 놓은 책의 가장자리를 가지런하게 도려냄. 또는 그 가장자리.","[書蠹] 지나치게 책을 읽거나 공부하는 데만 열중하는 사람을 놀림조로 이르는 말.","[書蠹] 책을 읽기는 하나 그것을 활용할 줄 모르는 사람을 비유적으로 이르는 말."]},{"id":564,"category":"한자어","term":"선두","definition":"대열이나 행렬, 활동 따위에서 맨 앞.","example":"선두에 서다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[船頭] 배의 앞부분.","[禪頭] 선종에서 수행승의 첫째에 위치하는 승려."]},{"id":565,"category":"한자어","term":"발전","definition":"더 낫고 좋은 상태나 더 높은 단계로 나아감.","example":"과학의 발전에 기여하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[發展] 일이 어떤 방향으로 전개됨.","[發電] 전기를 일으킴.","[發電] 전보를 쳐서 보냄."]},{"id":566,"category":"한자어","term":"발달","definition":"신체, 정서, 지능 따위가 성장하거나 성숙함.","example":"신체의 발달.","exampleSource":"표준국어대사전 용례","otherMeanings":["[發達] 학문, 기술, 문명, 사회 따위의 현상이 보다 높은 수준에 이름.","[發達] 지리상의 어떤 지역이나 대상이 제법 크게 형성됨. 또는 기압, 태풍 따위의 규모가 점차 커짐."]},{"id":567,"category":"한자어","term":"계승","definition":"조상의 전통이나 문화유산, 업적 따위를 물려받아 이어 나감.","example":"전통문화의 계승과 발전.","exampleSource":"표준국어대사전 용례","otherMeanings":["[階乘] <I>n</I>이 하나의 자연수일 때에, 1에서 <I>n</I>까지의 모든 자연수의 곱을 <I>n</I>에 대하여 이르는 말. <I>n</I>!로 나타낸다. 4의 계승은 1×2×3×4이다.","[繼承] 선임자의 뒤를 이어받음.","[繼乘] 열차나 배를 타고 가다가 내려서 다른 열차나 배로 옮겨 탐."]},{"id":568,"category":"한자어","term":"경계","definition":"뜻밖의 사고가 생기지 않도록 조심하여 단속함.","example":"경계를 늦추다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[庚癸] 군중에서 양식을 빌리는 것을 이르는 말. 경(庚)은 서방으로 곡식을, 계(癸)는 북방으로 물을 주관한다는 데서 생긴 말이다.","[敬啓] 삼가 말씀드린다는 뜻으로 한문 투 편지의 첫머리에 쓰는 말.","[經界] 옳고 그른 경위가 분간되는 한계.","[經界] 사물이 어떠한 기준에 의하여 분간되는 한계.","[境界] 사물이 어떠한 기준에 의하여 분간되는 한계.","[境界] 지역이 구분되는 한계.","[境界] 인과의 이치에 따라 스스로 받는 과보.","[輕繫] 가벼운 죄를 짓고 옥에 갇힌 죄인.","[鏡戒] 분명히 타일러 다시는 같은 잘못을 저지르지 않도록 함.","[警戒] 옳지 않은 일이나 잘못된 일들을 하지 않도록 타일러서 주의하게 함.","[警戒] 적의 기습이나 간첩 활동 따위와 같은 예기치 못한 침입을 막기 위하여 주변을 살피면서 지킴.","[驚悸] 걸핏하면 잘 놀라고 가슴이 두근거리는 증상.","[驚悸] 놀란 것처럼 가슴이 두근거리는 증상."]},{"id":569,"category":"한자어","term":"배제","definition":"받아들이지 아니하고 물리쳐 제외함.","example":"폭력의 배제.","exampleSource":"표준국어대사전 용례","otherMeanings":["[背題] 백성이 낸 소장(訴狀) 뒤에 판결한 내용을 적는 일. 또는 그 내용.","[配劑] 여러 가지 약제를 배합함. 또는 그 약제.","[排擠] 물리쳐 어려운 지경에 빠뜨림."]},{"id":570,"category":"한자어","term":"거부","definition":"요구나 제의 따위를 받아들이지 않고 물리침.","example":"거부 의사를 표명하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[巨富] 대단히 많은 재산.","[巨富] 부자 가운데에서도 특히 큰 부자.","[拒斧] 사마귓과의 곤충을 통틀어 이르는 말."]},{"id":571,"category":"한자어","term":"특장","definition":"특별히 뛰어난 장점.","example":"흰 학이 구름을 박차고 하늘로 나는 듯하지 않소. 이것이 고려 예술의 특장이란 말요.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":572,"category":"한자어","term":"천분","definition":"타고난 재질이나 직분.","example":"천분의 문학성.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":573,"category":"한자어","term":"각설","definition":"말이나 글 따위에서, 이제까지 다루던 내용을 그만두고 화제를 다른 쪽으로 돌림.","example":"각설하고 어디 당신의 계획이나 들어 봅시다.","exampleSource":"제공 자료 예문","otherMeanings":["[各設] 따로따로 설치함.","[各設] 연회 따위를 따로따로 베풂.","[却說] 주로 글 따위에서, 화제를 돌려 다른 이야기를 꺼낼 때, 앞서 이야기하던 내용을 그만둔다는 뜻으로 다음 이야기의 첫머리에 쓰는 말."]},{"id":574,"category":"한자어","term":"설명","definition":"어떤 일이나 대상의 내용을 상대편이 잘 알 수 있도록 밝혀 말함. 또는 그런 말.","example":"새 기획안에 대한 설명이 끝나자 질문이 쏟아졌다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":575,"category":"한자어","term":"역설","definition":"일반적으로는 모순을 야기하지 아니하나 특정한 경우에 논리적 모순을 일으키는 논증. 모순을 일으키기는 하지만 그 속에 중요한 진리가 함축되어 있는 것으로 간주한다.","example":"신앙을 가지고 산다는 것은 이성으로는 믿기 어려운 역설을 순순히 받아들이는 것이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[力說] 자기의 뜻을 힘주어 말함. 또는 그런 말.","[逆說] 어떤 주의나 주장에 반대되는 이론이나 말."]},{"id":576,"category":"한자어","term":"언급","definition":"어떤 문제에 대하여 말함.","example":"언급을 회피하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":577,"category":"한자어","term":"정비","definition":"흐트러진 체계를 정리하여 제대로 갖춤.","example":"교육 제도 정비.","exampleSource":"표준국어대사전 용례","otherMeanings":["[正比] 비(比)를 반비(反比)에 상대하여 이르는 말.","[正妃] 정실인 왕비를 후궁에 상대하여 이르는 말.","[情費] 조세를 바칠 때에, 비공식으로 아전들에게 주던 잡비.","[鼎沸] 솥 안에서 물이 끓는 것과 같이 떠들썩하고 요란함을 비유적으로 이르는 말.","[整備] 기계나 설비가 제대로 작동하도록 보살피고 손질함.","[整備] 도로나 시설 따위가 제 기능을 하도록 정리함."]},{"id":578,"category":"한자어","term":"갱신","definition":"이미 있던 것을 고쳐 새롭게 함.","example":"자기 갱신.","exampleSource":"표준국어대사전 용례","otherMeanings":["몸을 움직임.","[更新] 법률관계의 존속 기간이 끝났을 때 그 기간을 연장하는 일. 계약으로 기간을 연장하는 명시적 갱신과 계약 없이도 인정되는 묵시적 갱신이 있다.","[更新] 기존의 내용을 변동된 사실에 따라 변경ㆍ추가ㆍ삭제하는 일."]},{"id":579,"category":"한자어","term":"각오","definition":"앞으로 해야 할 일이나 겪을 일에 대한 마음의 준비.","example":"비장한 각오.","exampleSource":"표준국어대사전 용례","otherMeanings":["[覺悟] 도리를 깨쳐 앎.","[覺寤] 잠에서 깸."]},{"id":580,"category":"한자어","term":"각성","definition":"깨달아 앎.","example":"각성을 촉구하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[各姓] 서로 다른 성씨.","[各姓] 성이 각각 다른 사람.","[角星] 이십팔수의 첫째 별자리에 있는 별들. 청명절의 0시 23분에 정남쪽에 보인다.","[角聲] 뿔로 만든 나팔을 부는 소리.","[覺性] 진리를 깨달아 아는 성품이나 소질.","[覺性] 조선 시대의 승려(1575~1660). 속성은 김(金). 호는 벽암(碧巖). 병자호란 때 승려들을 규합하여 청나라에 대항하였다. 저서에 ≪도중결의(圖中決疑)≫, ≪간화결의(看話決疑)≫ 따위가 있다.","[覺醒] 깨어 정신을 차림.","[覺醒] 정신을 차리고 주의 깊게 살피어 경계하는 태도."]},{"id":581,"category":"한자어","term":"강단","definition":"굳세고 꿋꿋하게 견디어 내는 힘.","example":"강단이 세다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[降壇] 단상에서 내려옴.","[剛斷] 어떤 일을 야무지게 결정하고 처리하는 힘.","[講壇] 강연이나 강의, 설교 따위를 하는 사람이 올라서도록 약간 높게 만든 자리."]},{"id":582,"category":"한자어","term":"공격","definition":"남을 비난하거나 반대하여 나섬.","example":"동료들에게 집중 공격을 받다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[公格] 관직(官職)이나 공직(公職)에 관한 격식.","[攻擊] 나아가 적을 침.","[攻擊] 운동 경기나 오락 따위에서 상대편을 이기기 위한 적극적인 행동.","[攻擊] 소송에서, 원고(原告)가 자신의 신청을 이유 있는 것으로 하기 위하여 법률상, 사실상의 진술 및 증거 신청을 하는 일."]},{"id":583,"category":"한자어","term":"도발","definition":"남을 집적거려 일이 일어나게 함.","example":"성적인 도발.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":584,"category":"한자어","term":"승복","definition":"납득하여 따름.","example":"적에게 승복하다.","exampleSource":"제공 자료 예문","otherMeanings":["[承服] 죄를 스스로 고백함.","[僧服] 승려의 옷."]},{"id":585,"category":"한자어","term":"판단","definition":"사물을 인식하여 논리나 기준 등에 따라 판정을 내림.","example":"상황 판단.","exampleSource":"표준국어대사전 용례","otherMeanings":["[判斷] 어떤 대상에 대하여 무슨 일인가를 판정하는 인간의 사유 작용."]},{"id":586,"category":"한자어","term":"잠적","definition":"종적을 아주 숨김.","example":"공직자들에게는 잠적이나 도피보다 떳떳하게 나서서 사태를 감당하는 자세가 필요하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[岑寂] ‘잠적하다01’의 어근.","[潛寂] ‘잠적하다02’의 어근."]},{"id":587,"category":"한자어","term":"은둔","definition":"세상일을 피하여 숨음.","example":"노 교수는 모든 명예를 버리고 은둔의 생활을 택했다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":588,"category":"한자어","term":"임박","definition":"어떤 때가 가까이 닥쳐옴.","example":"거의 숨져 갈 임박에 자주 네 이름을 부르더군. 그래 내가 네 대신을 했었지.","exampleSource":"표준국어대사전 용례","otherMeanings":["[荏粕] 들기름을 짜내고 남은 찌꺼기. 물고기의 먹이나 거름으로 쓴다."]},{"id":589,"category":"한자어","term":"각박하다","definition":"인정이 없고 삭막하다.","example":"세상 인심이 각박하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[刻薄, 하다] 땅이 거칠고 기름지지 아니하다.","[刻薄, 하다] 돈 따위를 지나치게 아껴 넉넉하지 않다."]},{"id":590,"category":"한자어","term":"막간","definition":"어떤 일의 한 단락이 끝나고 다음 단락이 시작될 동안.","example":"막간을 이용해서 안내 말씀을 드리겠습니다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[幕間] 연극에서, 한 막이 끝났을 때부터 다음 막이 시작될 때까지의 시간."]},{"id":591,"category":"한자어","term":"기반","definition":"기초가 되는 바탕. 또는 사물의 토대.","example":"기반을 다지다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[棋盤, /, 碁盤] 바둑을 두는 판. 네모진 나무 판 위에 가로세로 각각 열아홉 줄을 그어 생긴 361개의 십자형이 있으며 한 십자형을 한 집이라고 한다.","[羈絆] 말이나 소 따위를 부리기 위하여 머리와 목에서 고삐에 걸쳐 얽어매는 줄.","[羈絆] 굴레를 씌운다는 뜻으로, 자유를 구속하거나 억압함을 이르는 말."]},{"id":592,"category":"한자어","term":"주축","definition":"전체 가운데서 중심이 되어 영향을 미치는 존재나 세력.","example":"팀의 주축인 그의 부상으로 전력에 차질이 생겼다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[主軸] 공작 기계의 주축대에 끼워져 회전 절삭 운동을 하는 축. 한끝에 공작물이나 날붙이를 부착하는 장치가 있다.","[主軸] 원동기에서 동력을 직접 전하는 전동축.","[主軸] 일렬로 배열된 광학계에서, 렌즈의 중심과 초점을 연결한 선.","[主軸] 축성(軸性)이 있는 생물체의 가장 기본적인 축. 일반적으로 좌우 대칭인 동물에서는 머리에서 꼬리의 방향, 방사 대칭인 생물에서는 몸의 중앙을 지나는 상하 방향의 축을 이른다.","[主軸] 몇 개의 축을 가진 도형이나 물체에서 가장 주가 되는 축. 타원에서의 긴 축과 짧은 축, 2차 곡면의 대칭면이 교차하는 선 따위가 있다.","[走逐] 달아나고 뒤쫓음."]},{"id":593,"category":"한자어","term":"주제","definition":"대화나 연구 따위에서 중심이 되는 문제.","example":"논문의 주제.","exampleSource":"표준국어대사전 용례","otherMeanings":["변변하지 못한 몰골이나 몸치장.","변변하지 못한 처지.","[主祭] 제사를 주장하여 행함. 또는 그런 사람.","[主劑] 조제할 때에 주가 되는 약제.","[主題] 예술 작품에서 지은이가 나타내고자 하는 기본적인 사상.","[主題] 주된 제목.","[主題] 하나의 악곡을 이루는 중심 악상. 악곡의 전부 또는 일부분의 기초가 되어, 그 선율적ㆍ화성적ㆍ율동적 발전이 악곡을 다양하게 전개한다.","[酒製] 술을 이용하여 약의 찬 성질을 약화하거나 덥게 하거나 약 기운을 위로 올라가게 하여 기혈이 잘 돌게 하는 일.","[酒劑] 약품을 포도주 따위의 술에 녹여서 만든 약. 강장제로 쓴다.","[誅除] 죄를 물어 죽여 없앰."]},{"id":594,"category":"한자어","term":"전제","definition":"어떠한 사물이나 현상을 이루기 위하여 먼저 내세우는 것.","example":"전제 조건.","exampleSource":"표준국어대사전 용례","otherMeanings":["[田制] 논밭에 관한 제도.","[田齊] 중국 전국 시대에, 진(陳)나라에서 제나라로 망명한 전 씨(田氏)가 주(周)나라로부터 제후로 인정받아 기원전 386년에 성립한 나라. 기원전 221년에 진(秦)나라에 망하였다.","[全制] 완전히 제어함.","[全濟] 완전히 구제함.","[典制] 예전에, 국가의 법 규범이나 규칙 또는 그것을 만드는 사람을 이르던 말.","[典制] 예전에, 일을 맡는 것을 이르던 말.","[典製] 조선 시대에, 의복의 재봉에 관한 모든 일을 맡아보던 종칠품 내명부. 또는 그 품계.","[前帝] 이전의 황제.","[前提] 추리를 할 때, 결론의 기초가 되는 판단. 삼단 논법에서는 대전제, 소전제를 구별한다.","[前際] 삼생(三生)의 하나. 이 세상에 태어나기 이전의 생애를 이른다.","[剪除, /, 翦除] 불필요한 것을 잘라서 없애 버림.","[專制] 다른 사람의 의사는 존중하지 않고 제 생각대로만 일을 결정함.","[專制] 국가의 권력을 개인이 장악하고 그 개인의 의사에 따라 모든 일을 처리함.","[專製] 독점적으로 제조함.","[奠祭] 모세의 율법에 나오는 제사의 하나. 잔에 담은 포도주나 독주(毒酒)를 제단 받침에 붓는다.","[筌蹄] 고기를 잡는 통발과 토끼를 잡는 올가미라는 뜻으로, 목적을 달성하기 위한 방편을 이르는 말.","[筌蹄] 사물의 길잡이가 되는 것.","[筌蹄] 중국 남조의 사대부가 설법을 할 때에 손에 쥐던 불자(拂子) 따위를 이르는 말.","[煎劑] 생약을 오랫동안 달여서 만든 약. 열에 대한 안정성이 높은 약재 중에서, 장시간 가열해야만 약효 성분이 추출되는 것은 오랫동안 달여서 약을 만든다."]},{"id":595,"category":"한자어","term":"상이하다","definition":"서로 다르다.","example":"형은 나와 성격 면에서 매우 상이하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":596,"category":"한자어","term":"모방","definition":"다른 것을 본뜨거나 본받음.","example":"외국 문물에 대한 분별없는 모방.","exampleSource":"표준국어대사전 용례","otherMeanings":["[모, 方] 한자 부수의 하나. ‘於’, ‘旁’ 따위에 쓰인 ‘方’을 이른다.","[모, 房] 안방의 한 모퉁이에 붙어 있는 작은 방.","[毛紡] 모방적과 모방직을 통틀어 이르는 말.","[模倣, /, 摸倣, /, 摹倣] 사회 집단의 구성원들 사이에 나타나는 의식적ㆍ무의식적 반복 행위. 어떤 개인ㆍ집단의 행위나 표현이 다른 개인ㆍ집단에 의하여 비슷하게 반복되면서 사회의 결합 관계를 강화하게 되며, 어린이의 학습 과정이나 사회적 유행, 또는 전통의 계승에 있어서 중요한 의의를 가진다.","[模倣, /, 摸倣, /, 摹倣] 하나의 주선율을 일정한 시간을 두고 다른 성부에서 거듭 쓰는 방법.","[Maubant, Pierre Phillibert] 우리나라에 최초로 들어온, 프랑스의 천주교 신부(1803~1839). 조선 헌종 1년(1835)에 서울에 몰래 들어와 전도하다가 헌종 5년(1839) 기해사옥 때에 앵베르, 샤스탕과 함께 순교하였다. 1925년에 복자위(福者位)에 올랐다."]},{"id":597,"category":"한자어","term":"사건","definition":"사회적으로 문제를 일으키거나 주목을 받을 만한 뜻밖의 일.","example":"역사적인 사건.","exampleSource":"표준국어대사전 용례","otherMeanings":["[事件] 소송을 일으킨 일.","[事件] 어떤 실험이나 시행(試行)에서 일어날 수 있는 결과. 예를 들어 주사위를 던질 때 1이 나온다든가, 짝수가 나온다든가, 4 이상이 나온다든가 하는 따위이다.","[紗巾] 얇고 가벼운 비단인 사(紗)로 만든 두건."]},{"id":598,"category":"한자어","term":"전모","definition":"전체의 모습. 또는 전체의 내용.","example":"전모를 드러내다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[典謨] ≪서경≫의 <요전(堯典)>, <순전(舜典)>, <대우모(大禹謨)>, <고요모(皐陶謨)>, <익직(益稷)>의 각 편을 통틀어 이르는 말.","[前母] 재취(再娶)의 자식이 그 아버지의 전처를 이르는 말.","[旃毛] 모직으로 짠 옷감의 털.","[剪毛, /, 翦毛] 짐승의 털을 깎는 일.","[剪毛, /, 翦毛] 직물 표면에 나와 있는 잔털을 깎아 올을 뚜렷하게 하는 모직물 공정.","[傳模] 회화에서, 옛사람의 작품을 모사(模寫)하는 일.","[氈帽] 조선 시대에, 여자들이 나들이할 때 쓰던 모자의 하나. 대나무로 삿갓 모양의 테두리를 만들고 여기에 종이를 발라 기름에 결어 만든다.","[顚毛] 머리에 난 털.","[顚毛] 정수리의 머리털."]},{"id":599,"category":"한자어","term":"축적","definition":"지식, 경험, 자금 따위를 모아서 쌓음. 또는 모아서 쌓은 것.","example":"경험 축적.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":600,"category":"한자어","term":"이문","definition":"이익이 남는 돈.","example":"이문이 남다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[二門] 교리에 따라 나눈 불교의 큰 두 갈래. 본문과 적문, 섭수문과 절복문, 유문과 공문, 성도문과 정토문 따위이다.","[泥文, /, 尼文] 가야의 악사(?~?). 우륵의 제자로, 진흥왕 12년(551) 우륵과 낭성(娘城)에 머물다가 진흥왕에게 발탁되어 하림궁(河臨宮)에서 새로운 곡을 지어 연주하였다. 작품에 <까마귀>, <쥐>, <메추리> 따위가 있다.","[吏文] 조선 시대에 중국과 주고받던 문서에 쓰던 특수한 관용 공문의 용어나 문체. 자문(咨文), 서계(書契), 관자(關子), 감결(甘結), 보장(報狀), 제사(題辭) 따위와 같은 문서에 썼다.","[耳門] 귓구멍의 바깥쪽으로 열려 있는 곳.","[利文] 남에게 돈을 빌려 쓴 대가로 치르는 일정한 비율의 돈.","[里門] 동네 어귀에 세운 문.","[異聞] 신기하고 들을 만한 소문.","[異聞] 이상한 소문.","[移文] 중국 한대(漢代)의 공문서 가운데 같은 등급의 관아 사이에 주고받던 공문서. 때로는 격(檄)과 더불어 포고문의 성격을 띠기도 하였다.","[裏門] 뒤나 옆으로 난 문."]},{"id":601,"category":"한자어","term":"강보","definition":"어린아이의 작은 이불. 덮고 깔거나 어린아이를 업을 때 쓴다.","example":"강보에 싸인 아기.","exampleSource":"표준국어대사전 용례","otherMeanings":["[降寶] 발상(發祥)의 일곱째 장(章). 한문 가사 4언 1구로 되어 있다.","[康保] 편안히 보전함."]},{"id":602,"category":"한자어","term":"개인","definition":"국가나 사회, 단체 등을 구성하는 낱낱의 사람.","example":"개인 자격으로 참가하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[改印] 도장을 본디 모양과 다르게 고쳐 새김.","[改印] 신고된 인감(印鑑)을 바꿈.","[開印] 관아에서 연말에 사무를 마무리하고 넣어 둔 관인(官印)을, 연초에 다시 사무를 시작하면서 꺼내던 일.","[蓋印] 관인(官印)을 찍음."]},{"id":603,"category":"한자어","term":"객관","definition":"자기와의 관계에서 벗어나 제삼자의 입장에서 사물을 보거나 생각함.","example":"그는 감정을 배제하고 객관에 근거해 판단했다.","exampleSource":"제공 자료 예문","otherMeanings":["[客官] 관아의 사무에 직접적인 책임이 없던 벼슬아치.","[客官] 다른 관아에서 임시로 와서 사무를 보던 벼슬아치.","[客館] 나그네를 치거나 묵게 하는 집.","[客館] 고려ㆍ조선 시대에, 각 고을에 설치하여 외국 사신이나 다른 곳에서 온 벼슬아치를 대접하고 묵게 하던 숙소.","[客觀] 주관 작용의 객체가 되는 것으로 정신적ㆍ육체적 자아에 대한 공간적 외계. 또는 인식 주관에 대한 인식 내용.","[客觀] 세계나 자연 따위가 주관의 작용과는 독립하여 존재한다고 생각되는 것."]},{"id":604,"category":"한자어","term":"거리","definition":"두 개의 물건이나 장소 따위가 공간적으로 떨어진 길이.","example":"거리가 가깝다.","exampleSource":"표준국어대사전 용례","otherMeanings":["사람이나 차가 많이 다니는 길.","내용이 될 만한 재료.","제시한 시간 동안 해낼 만한 일.","제시한 수가 처리할 만한 것.","오이나 가지 따위를 묶어 세는 단위. 한 거리는 오이나 가지 오십 개를 이른다.","탈놀음, 꼭두각시놀음, 굿 따위에서, 장(場)을 세는 단위.","음악, 연극 따위에서 단락, 과장, 마당을 이르는 말.","[巨利] 큰 이익.","[巨履] 큰 신.","[距離] 일정한 시간 동안에 이동할 만한 공간적 간격.","[距離] 사람과 사람 사이에 느껴지는 간격. 보통 서로 마음을 트고 지낼 수 없다고 느끼는 감정을 이른다.","[距離] 비교하는 두 대상 사이의 차이.","[距離] 두 점 사이를 잇는 선분의 길이.","‘비하’의 뜻을 더하는 접미사.","‘주기적으로 일어나는 동안’의 뜻을 더하는 접미사."]},{"id":605,"category":"한자어","term":"산적","definition":"물건이나 일이 산더미같이 쌓임.","example":"문 앞에 쓰레기가 산적되어 있다.","exampleSource":"제공 자료 예문","otherMeanings":["[山賊] 산속에 근거지를 두고 드나드는 도둑.","[疝癪] 가슴이나 배가 쑤시고 아픈 병.","[散炙] 쇠고기 따위를 길쭉길쭉하게 썰어 갖은양념을 하여 대꼬챙이에 꿰어 구운 음식.","[散炙] 꼬챙이에 꿰지 아니한 적. 생선적에 쇠고기를 양념하여 한편에 붙이고 이것을 달걀 푼 것을 씌워 번철이나 프라이팬 따위에 지져서 만든다.","[散積] 석탄, 광물, 곡물 따위를 용기에 넣지 아니하고 그대로 쌓거나 실음.","[蒜炙] 마늘로 만든 적."]},{"id":606,"category":"한자어","term":"낙점","definition":"여러 후보가 있을 때 그중에 마땅한 대상을 고름.","example":"낙점을 받다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[落點] 조선 시대에, 이품 이상의 벼슬아치를 뽑을 때 임금이 이조에서 추천된 세 후보자 가운데 마땅한 사람의 이름 위에 점을 찍던 일.","[落點] 총알이나 폭탄, 화살 따위를 쏘아서 떨어진 지점."]},{"id":607,"category":"한자어","term":"파견","definition":"일정한 임무를 주어 사람을 보냄.","example":"파견 근무.","exampleSource":"표준국어대사전 용례","otherMeanings":["[破見] 올바른 견해를 깨뜨리고 잘못된 견해에 빠지며 옳지 못한 견해를 고집하여 불법의 바른 이치에 어긋나는 일. 법(法)을 비방함과 같아 악도(惡道)에 떨어지는 무거운 죄이다."]},{"id":608,"category":"한자어","term":"격식","definition":"격에 맞는 일정한 방식.","example":"격식을 갖추다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":609,"category":"한자어","term":"결정","definition":"행동이나 태도를 분명하게 정함. 또는 그렇게 정해진 내용.","example":"결정을 내리다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[決定] 법원이 행하는 판결ㆍ명령 이외의 재판.","[結晶] 원자, 이온, 분자 따위가 규칙적으로 일정한 법칙에 따라 배열되고, 외형도 대칭 관계에 있는 몇 개의 평면으로 둘러싸여 규칙 바른 형체를 이룸. 또는 그런 물질.","[結晶] 애써 노력하여 보람 있는 결과를 이루는 것이나 그 결과를 비유적으로 이르는 말.","[潔淨] ‘결정하다03’의 어근."]},{"id":610,"category":"한자어","term":"경사","definition":"축하할 만한 기쁜 일.","example":"경사가 나다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[京司] 서울에 있던 관아를 통틀어 이르는 말.","[京師] 한 나라의 중앙 정부가 있는 곳.","[剄死] 스스로 목을 찔러 죽음.","[勁士] 굳세고 강한 병사나 군대.","[勁士] 굳세고 바른 사람.","[敬事] 공경하여 섬김.","[敬事] 삼가 일을 함.","[傾斜] 비스듬히 기울어짐. 또는 그런 상태나 정도.","[傾瀉] 액체와 침전물을 분리하는 방법. 침전물을 가라앉힌 다음, 맑은 웃물을 기울여 쏟는다.","[經史] 경서(經書)와 사기(史記)를 아울러 이르는 말.","[經師] 경문(經文)을 읽거나 외는 법사.","[經師] 경문의 뜻을 풀어 가르치는 법사.","[經師] 경문을 쓰거나, 쓴 것을 표구하고 제본하는 사람.","[經絲] 피륙이나 그물을 짤 때, 세로 방향으로 놓인 실.","[輕士] 가볍게 차린 병사.","[輕士] 신분이 낮은 병사.","[競射] 활쏘기나 사격의 실력을 겨룸.","[警査] 경찰 공무원 계급의 하나. 경위의 아래, 경장의 위이다.","[驚事] 뜻밖에 매우 놀랄 일."]},{"id":611,"category":"한자어","term":"공감","definition":"남의 감정, 의견, 주장 따위에 대하여 자기도 그렇다고 느낌. 또는 그렇게 느끼는 기분.","example":"공감을 느끼다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":612,"category":"한자어","term":"도래","definition":"어떤 시기나 기회가 닥쳐옴.","example":"민주주의의 도래.","exampleSource":"표준국어대사전 용례","otherMeanings":["문이 저절로 열리지 못하게 하는 데 쓰는 갸름한 나무 메뚜기.","소나 염소 따위의 고삐가 자유롭게 돌 수 있도록 굴레 또는 목사리와 고삐 사이에 단 쇠나 나무로 된 고리 비슷한 물건.","낚싯줄이 꼬이지 아니하고 자유로이 감겼다 풀리도록 낚싯줄의 굴레와 고삐 사이를 이은 물건. 보통 쇠나 나무로 만들며 고리와 비슷한 모양이다.","둥근 물건의 둘레.","→ 어장10.","[渡來] 물을 건너옴.","[渡來] 외부에서 전해져 들어옴.","‘둥근’의 뜻을 더하는 접두사."]},{"id":613,"category":"한자어","term":"독려","definition":"감독하며 격려함.","example":"아내의 독려 덕분에 작업을 마칠 수 있었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":614,"category":"한자어","term":"동요","definition":"어떤 체제나 상황 따위가 혼란스럽고 술렁임.","example":"민심의 동요.","exampleSource":"표준국어대사전 용례","otherMeanings":["[動搖] 물체 따위가 흔들리고 움직임.","[動搖] 생각이나 처지가 확고하지 못하고 흔들림.","[童謠] 문학 장르의 하나로, 어린이들의 생활 감정이나 심리를 표현한 정형시. 형식상 음수율이 강화되어 음악성이 돋보이며 형식과 수사(修辭)를 중요시한다.","[童謠] 어린이를 위하여 동심(童心)을 바탕으로 지은 노래."]},{"id":615,"category":"한자어","term":"등기","definition":"국가 기관이 법정 절차에 따라 등기부에 부동산이나 동산ㆍ채권 등의 담보 따위에 관한 일정한 권리관계를 적는 일. 또는 적어 놓은 것.","example":"등기 서류.","exampleSource":"표준국어대사전 용례","otherMeanings":["[登記] 우편물 특수 취급의 하나. 우체국에서 우편물의 안전한 송달을 보증하기 위하여 우편물의 인수ㆍ배달 과정을 기록한다.","[等棄] 탐탁지 않게 여겨서 버림.","[謄記] 원본에서 베껴 옮김."]},{"id":616,"category":"한자어","term":"발령","definition":"명령을 내림. 또는 그 명령. 흔히 직책이나 직위와 관계된 경우를 이른다.","example":"승진 발령.","exampleSource":"표준국어대사전 용례","otherMeanings":["[發令] 긴급한 상황에 대한 경보(警報)를 발표함."]},{"id":617,"category":"한자어","term":"발부","definition":"증명서 따위를 발행하여 줌.","example":"사전 구속 영장 발부.","exampleSource":"표준국어대사전 용례","otherMeanings":["[髮膚] 머리털과 피부를 아울러 이르는 말."]},{"id":618,"category":"한자어","term":"방지","definition":"어떤 일이나 현상이 일어나지 못하게 막음.","example":"병충해 방지.","exampleSource":"표준국어대사전 용례","otherMeanings":["[方志] 한 지방에 관한 기록.","[方志] 바른 마음.","[放支] 돈이나 물품 따위를 정하여진 몫만큼 내줌.","[芳志] 주로 편지글 따위에서, 다른 사람의 친절한 마음을 높여 이르는 말.","[旁支] 본체에서 갈라져 나온 가닥."]},{"id":619,"category":"한자어","term":"변호사","definition":"법률에 규정된 자격을 가지고 소송 당사자나 관계인의 의뢰 또는 법원의 명령에 따라 피고나 원고를 변론하며 그 밖의 법률에 관한 업무에 종사하는 사람.","example":"변호사 개업.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":620,"category":"한자어","term":"병마","definition":"‘병04’을 악마에 비유하여 이르는 말.","example":"병마에 시달리다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[兵馬] 병사(兵士)와 군마(軍馬)를 아울러 이르는 말.","[兵馬] 군대, 무기, 군비(軍備) 따위의 전쟁에 관한 모든 일을 통틀어 이르는 말.","[兵馬] 군대에서 쓰는 말.","[病馬] 병든 말."]},{"id":621,"category":"한자어","term":"병폐","definition":"병통과 폐단을 아울러 이르는 말.","example":"병폐를 극복하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[病癈] 병으로 인하여 몸을 제대로 쓰지 못하게 됨.","[病斃] 병으로 죽음. 또는 그런 일."]},{"id":622,"category":"한자어","term":"보류","definition":"어떤 일을 당장 처리하지 아니하고 나중으로 미루어 둠.","example":"보류 결정을 내리다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[補流] 옮겨 간 바닷물을 채우기 위하여 이동하는 바닷물의 흐름."]},{"id":623,"category":"한자어","term":"봉변","definition":"뜻밖의 변이나 망신스러운 일을 당함. 또는 그 변.","example":"가까스로 봉변을 면하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":624,"category":"한자어","term":"붕괴","definition":"무너지고 깨어짐.","example":"붕괴 위험.","exampleSource":"표준국어대사전 용례","otherMeanings":["[崩壞] 불안정한 소립자가 스스로 분열하여 다른 종류의 소립자로 바뀌는 일. 또는 불안정한 원자핵이 방사선을 방출하거나 스스로 핵분열을 일으켜 다른 종류의 원자핵으로 바뀌는 일."]},{"id":625,"category":"한자어","term":"비밀","definition":"숨기어 남에게 드러내거나 알리지 말아야 할 일.","example":"비밀이 탄로 나다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[祕密] 밝혀지지 않았거나 알려지지 않은 내용.","[祕密] 참된 의미를 숨기고 가르침을 설하는 것. 언어나 문자 따위의 일반적인 방법으로는 전할 수 없는 깊은 뜻을 만다라, 인계(印契), 다라니, 의례 따위의 상징적인 방법을 통해서 나타낸다."]},{"id":626,"category":"한자어","term":"빙부","definition":"다른 사람의 장인(丈人)을 이르는 말.","example":"그는 빙부의 장례를 치르기 위해 고향으로 내려갔다.","exampleSource":"제공 자료 예문","otherMeanings":["[氷夫] 예전에, 강에서 얼음을 떠내는 일을 직업으로 하던 사람.","[氷膚] 얼음처럼 맑고 깨끗한 살결."]},{"id":627,"category":"한자어","term":"사경","definition":"죽을 지경. 또는 죽음에 임박한 경지.","example":"사경을 헤매다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[司經] 고려 시대에, 동궁(東宮)에 속한 육품 벼슬. 공양왕 2년(1390)에 설치하였는데, 좌우 두 사람이 있었다.","[司經] 조선 시대에, 경연청에 속한 정칠품 벼슬. 임금에게 경서(經書)를 강의하고 논평하는 일을 맡아보았다.","[四更] 하룻밤을 오경(五更)으로 나눈 넷째 부분. 새벽 1시에서 3시 사이이다.","[四京] 고려 시대에, 나라의 중심지로서 중요시하던 네 지역. 남경(南京), 동경(東京), 중경(中京), 서경(西京)을 이른다.","[四經] ≪시경≫, ≪서경≫, ≪역경≫, ≪춘추≫의 네 가지 경서(經書).","[四經] ≪좌씨춘추≫, ≪곡량춘추≫, ≪고문상서≫, ≪모시≫의 네 가지 경서.","[四境] 동, 서, 남, 북 사방의 지경이나 경계.","[四境] 천하 또는 세계를 이르는 말.","[沙耕, /, 砂耕] 농작물에 필요한 양분을 준 모래에 작물을 재배하는 일.","[沙耕, /, 砂耕] 세균을 보존하는 방법의 하나. 멸균시킨 모래를 시험관에 담고 그 속에 배양한 세균을 넣어 둔다.","[沙耕, /, 砂耕] 식물의 물 재배 방법의 하나. 깨끗한 모래나 자갈에 식물을 심고 배양액으로 기른다.","[沙磬] 경쇠의 하나.","[邪徑] 곧지 않은 구불구불한 길.","[邪徑] 부정한 마음이나 행위를 비유적으로 이르는 말.","[私徑] 사사로운 이익을 추구하는 떳떳하지 못한 길.","[私耕] 묘지기나 마름이 수고의 대가로 부쳐 먹는 논밭.","[私耕] 머슴이 주인에게서 한 해 동안 일한 대가로 받는 돈이나 물건.","[査經] 교인들이 모여 성경을 공부함.","[斜徑] 비탈진 언덕의 길.","[斜傾] 한쪽으로 비스듬히 기울어짐.","[斜頸] 목의 일부 근육이 뒤틀려 머리가 한쪽으로 기우는 증상. 또는 그 증상을 보이는 목. 목 근육이 선천적으로 짧아서 그런 경우가 많으며 후천적으로는 류머티즘, 뼈의 이상, 사시(斜視)나 심인 반응도 원인이 된다.","[寫經] 후세에 전하거나 축복을 받기 위하여 경문(經文)을 베끼는 일. 또는 그런 경전."]},{"id":628,"category":"한자어","term":"삭제","definition":"깎아 없애거나 지워 버림.","example":"회원들은 회칙에서 필요 없는 조항의 삭제를 요구했다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[削除] 화면(畫面)에 표시된 문자를 지우는 일. 또는 파일 내에 저장된 기록을 제거하거나 기억 장치에서 프로그램을 지우는 일.","[削蹄] 가축의 굽을 일정 기간마다 깎는 일. 다리 모양이 나빠지는 것을 방지하기 위하여 주로 말이나 소의 굽을 깎는다.","[朔祭] 왕실에서 음력 초하룻날마다 조상에게 지내던 제사."]},{"id":629,"category":"한자어","term":"속행","definition":"계속하여 행함.","example":"지난번에 연기된 경기는 이번 주 일요일에 속행될 것입니다.","exampleSource":"제공 자료 예문","otherMeanings":["[速行] 빨리 행함.","[速行] 빨리 감."]},{"id":630,"category":"한자어","term":"수렴","definition":"의견이나 사상 따위가 여럿으로 나뉘어 있는 것을 하나로 모아 정리함.","example":"여론 수렴.","exampleSource":"표준국어대사전 용례","otherMeanings":["[水廉] 무덤 안에 물이 괴어 송장이 해를 입음.","[水簾] 물의 발이라는 뜻으로, ‘폭포01’를 아름답게 이르는 말.","[收斂] 돈이나 물건 따위를 거두어들임.","[收斂] 방탕한 사람이 몸과 마음을 단속함.","[收斂] 오그라들게 함.","[收斂] 조세 따위를 거두어들임.","[收斂] 광선, 유체, 전류 따위가 한 점에 모이는 일.","[收斂] 동식물의 계통이 다른 군(群)이 같은 환경에 적응한 결과, 닮은 형질을 나타내며 진화하는 일. 오스트레일리아에 사는 유대류(有袋類)의 여러 종류는 다른 대륙의 포유류와 비슷하다.","[收斂] 수열에서, 어떤 일정한 수의 임의의 근방에 유한 개를 제외한 나머지 모든 항이 모여 있는 현상.","[收斂] 함수 <I>ƒ(x)</I>가 있을 때, 어떤 일정한 수의 임의의 근방에 <I>a</I>의 근방에 있는 모든 <I>x</I>의 함숫값이 모여 있는 현상.","[垂簾] 발을 드리움. 또는 그 발.","[垂簾] 임금이 어린 나이로 즉위하였을 때, 왕대비나 대왕대비가 이를 도와 정사를 돌보던 일. 왕대비가 신하를 접견할 때 그 앞에 발을 늘인 데서 유래한다.","[繡簾] 무늬를 놓아 드리운 발."]},{"id":631,"category":"한자어","term":"수발","definition":"받음과 보냄.","example":"공문서 수발.","exampleSource":"표준국어대사전 용례","otherMeanings":["신변 가까이에서 여러 가지 시중을 듦.","[秀拔] ‘수발하다03’의 어근.","[秀發] ‘수발하다04’의 어근.","[垂髮] 어린아이의 늘어뜨린 머리. 또는 어린 나이.","[隨發] 두 가지 이상의 일이 한꺼번에 일어남. 또는 그 일.","[鬚髮] 수염과 머리털을 아울러 이르는 말."]},{"id":632,"category":"한자어","term":"수여","definition":"증서, 상장, 훈장 따위를 줌.","example":"상장 수여.","exampleSource":"표준국어대사전 용례","otherMeanings":["[睡餘] 잠에서 깬 뒤."]},{"id":633,"category":"한자어","term":"순리","definition":"순한 이치나 도리. 또는 도리나 이치에 순종함.","example":"순리를 따르다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[巡吏] 순시하는 관리.","[殉利] 이익만 좇다가 몸을 망침.","[純利] 총이익에서 영업비, 잡비 따위의 총비용을 빼고 남은 순전한 이익.","[純理] 학문의 순수한 이치.","[循吏] 법을 잘 지키며 열심히 근무하는 관리.","[順利] 이익을 좇음.","[順利] 순조로운 것.","[醇醨] 진한 술과 묽은 술을 아울러 이르는 말.","[醇醨] 순후한 풍속과 경박한 풍속을 아울러 이르는 말."]},{"id":634,"category":"한자어","term":"순연","definition":"차례로 기일을 늦춤.","example":"기왕이니 내일 제 소원대로 반지를 사 주고 나서……이렇게, 할 수 없이 순연을 하기로 요량을 했습니다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[巡演] 여러 곳으로 돌아다니면서 하는 공연.","[純然] ‘순연하다02’의 어근.","[順緣] 늙은 사람부터 차례로 죽음.","[順緣] 진리의 가르침을 듣는 것과 같은 좋은 일이 인연이 되어 불도(佛道)로 들어가는 일."]},{"id":635,"category":"한자어","term":"옹색","definition":"형편이 넉넉하지 못하여 생활에 필요한 것이 없거나 부족함. 또는 그런 형편.","example":"돈을 다소라도 마련을 해 가지고 가야만…옹색이 덜할 것이었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":636,"category":"한자어","term":"용역","definition":"물질적 재화의 형태를 취하지 아니하고 생산과 소비에 필요한 노무를 제공하는 일.","example":"용역 회사.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":637,"category":"한자어","term":"의결","definition":"의논하여 결정함. 또는 그런 결정.","example":"이사회의 의결이 나오는 대로 조치가 취해질 것이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[疑結] 인과(因果) 따위를 의심하는 마음에서 일어나는 번뇌."]},{"id":638,"category":"한자어","term":"인용","definition":"남의 말이나 글을 자신의 말이나 글 속에 끌어 씀.","example":"인용 보도.","exampleSource":"표준국어대사전 용례","otherMeanings":["[仁勇] 어질고 용감함.","[認容] 인정하여 용납함."]},{"id":639,"category":"한자어","term":"자만","definition":"자신이나 자신과 관련 있는 것을 스스로 자랑하며 뽐냄.","example":"자만에 빠지다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[子滿] 임신 5~7개월에 배가 지나치게 커지고 가슴이 답답하며, 오줌을 잘 누지 못하고 몸이 붓는 병.","[自滿] 스스로 흡족하게 여김.","[滋蔓] 차차 늘어서 퍼짐."]},{"id":640,"category":"한자어","term":"적령","definition":"어떤 표준이나 규정에 알맞은 나이.","example":"취학 적령.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":641,"category":"한자어","term":"전세","definition":"부동산의 소유자에게 일정한 금액을 맡기고 그 부동산을 일정 기간 동안 빌려 쓰는 일. 또는 그 돈. 부동산을 돌려줄 때는 맡긴 돈의 전액을 되돌려받는다.","example":"전세 보증금.","exampleSource":"표준국어대사전 용례","otherMeanings":["[田稅] 논밭에 부과되는 조세.","[田稅] 고려 시대의 전시과나 조선 시대의 과전법에서 전조(田租)를 받는 사람이 다시 국가에 납부하는 세. 전조의 약 1/10, 수확량의 약 1/100을 낸다.","[前世] 지나간 시대.","[前世] 삼세의 하나. 이 세상에 태어나기 이전의 세상을 이른다.","[前歲] 이해의 바로 앞의 해.","[專貰] 계약에 의하여 일정 기간 동안 그 사람에게만 빌려주어 다른 사람의 사용을 금하는 일.","[專勢] 권세를 독차지함.","[傳世] 대대로 전함.","[傳貰] 전세를 받고 빌려주는 방. 또는 전세를 주고 빌려 쓰는 방.","[戰勢] 전쟁, 경기 따위의 형세나 형편.","[轉世] 이 세상에 다시 태어남."]},{"id":642,"category":"한자어","term":"전시","definition":"여러 가지 물품을 한곳에 벌여 놓고 보임.","example":"도서 전시.","exampleSource":"표준국어대사전 용례","otherMeanings":["[田矢] 사냥할 때 쓰는 화살.","[全市] 시(市)의 전체.","[前翅] 곤충류의 날개 가운데 앞에 있는 한 쌍의 날개.","[展示] 책, 편지 따위를 펴서 봄. 또는 펴서 보임.","[展翅] 곤충을 채집하여 표본으로 만드는 일.","[傳尸] 말기에 이른 폐결핵.","[傳示] 기술이나 지식 따위를 전하여 보임.","[殿試] 조선 시대에, 복시(覆試)에서 선발된 사람에게 임금이 친히 치르게 하던 과거. 문과 33명, 무과 28명의 합격자를 재시험하여 등급을 결정하였는데, 특별한 사유가 없는 한 떨어뜨리는 법은 없었다.","[廛市] 작은 규모로 물건을 파는 집.","[戰時] 전쟁이 벌어진 때."]},{"id":643,"category":"한자어","term":"절차","definition":"일을 치르는 데 거쳐야 하는 순서나 방법.","example":"수속 절차.","exampleSource":"표준국어대사전 용례","otherMeanings":["[切磋] 옥이나 돌을 갈고 닦는다는 뜻으로, 학문과 덕행을 닦음을 이르는 말."]},{"id":644,"category":"한자어","term":"정체성","definition":"변하지 아니하는 존재의 본질을 깨닫는 성질. 또는 그 성질을 가진 독립적 존재.","example":"청소년기는 자신의 정체성을 확립하는 시기이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[停滯性] 사물이 발전하거나 앞으로 나아가지 못하고 한곳에 머물러 있는 특성."]},{"id":645,"category":"한자어","term":"제시","definition":"어떠한 의사를 말이나 글로 나타내어 보임.","example":"근본적인 해결책 제시가 없이 정책이 겉돌고 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[祭詩] 시를 짓는 괴로움을 위로하기 위하여 자기가 지은 시를 제사 지내는 일.","[提示] 검사나 검열 따위를 위하여 물품을 내어 보임.","[提示] 오단(五段) 교수법에서, 새로운 교재를 아동에게 보이는 두 번째 단계.","[提撕] 기운을 내어 떨쳐 일어남.","[提撕] 몸에 지니어 가짐.","[睇視] 곁눈으로 봄.","[齊詩] 중국 제나라의 원고생이 전하였다고 하는 ≪시경≫. 오늘날 일부분만 전한다.","[題詩] 제목을 붙여 시를 지음. 또는 그 시."]},{"id":646,"category":"한자어","term":"주창","definition":"주의나 사상을 앞장서서 주장함.","example":"사람들은 그의 주창을 보수적이라고 비판했다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[主鬯] ‘황태자’를 달리 이르던 말. 종묘(宗廟)에서 제사를 지낼 때 울창주를 올린다고 하여 이렇게 이른다.","[主唱] 노래나 시 따위를 앞장서서 부름."]},{"id":647,"category":"한자어","term":"중화","definition":"서로 성질이 다른 물질이 융합하여 각각 그 특징이나 작용을 잃음. 또는 그런 일.","example":"이 물질은 여러 가지 독성 성분을 중화하는 역할을 한다.","exampleSource":"제공 자료 예문","otherMeanings":["[中火] 길을 가다가 점심을 먹음. 또는 그 점심.","[中和] 서로 다른 성질을 가진 것이 섞여 각각의 성질을 잃거나 그 중간의 성질을 띠게 함. 또는 그런 상태.","[中和] 감정이나 성격이 치우치지 아니하고 바른 상태.","[中和] 같은 양의 양전하와 음전하가 하나가 되어 전체로는 전하를 가지지 아니함. 또는 그런 일.","[中和] 산과 염기가 반응하여 서로의 성질을 잃음. 또는 그 반응.","[中和] 서로 다른 요소가 특정한 조건에서 변별 기능을 잃고 구별되지 아니함. 또는 그런 현상. 예를 들어, ‘낟’, ‘낫’, ‘낯’, ‘낱’ 따위에 쓰인 받침소리는 모두 ‘ㄷ’으로 발음된다.","[中華] 세계 문명의 중심이라는 뜻으로, 중국 사람들이 자기 나라를 이르는 말. 주변국에서 중국을 대접하여 이르는 말로도 쓰인다.","[衆花] 많은 꽃."]},{"id":648,"category":"한자어","term":"지축","definition":"대지의 중심.","example":"지축을 울리다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[支軸] 지레 따위의 지점(支點)에 있는 받침축.","[地軸] 지구의 자전축. 북극과 남극을 연결하는 축으로, 공전 궤도면에 대하여 66.5도가량 기울어져 있다."]},{"id":649,"category":"한자어","term":"진상","definition":"사물이나 현상의 거짓 없는 모습이나 내용.","example":"진상을 밝히다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[珍賞] 진귀한 것을 보고 기뻐서 즐김.","[振上] 양손에 아령 두 개를 쥐고 다리 사이에서 두세 번 흔들다가 앞쪽으로 머리 위까지 들어 올리는 운동.","[眞想] 참된 생각.","[眞像] 진짜 모습 그대로의 형상.","[陣上] 군대나 부대의 안.","[陳狀] 일의 사정이나 상황을 말함.","[進上] 진귀한 물품이나 지방의 토산물 따위를 임금이나 고관 따위에게 바침.","[進上] 겉보기에 허름하고 질이 나쁜 물건을 속되게 이르는 말.","[塵想] 속된 생각. 또는 세속의 잡념."]},{"id":650,"category":"한자어","term":"최면","definition":"암시에 의하여 인위적으로 이끌어 낸, 잠에 가까운 상태.","example":"최면에 빠지다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[催眠] 잠이 들게 함."]},{"id":651,"category":"한자어","term":"추종","definition":"남의 뒤를 따라서 좇음.","example":"그는 컴퓨터 분야에서는 타의 추종을 불허한다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[追從] 권력이나 권세를 가진 사람이나 자신이 동의하는 학설 따위를 별 판단 없이 믿고 따름.","[追蹤] 뒤를 밟아 쫓아간다는 뜻으로, 옛일을 더듬어 찾음을 이르는 말.","[追蹤] 다른 사람의 행동을 감시하거나 증거를 잡기 위하여 그 사람 몰래 뒤를 밟음.","[錘鐘] 추가 달린 괘종시계.","[騶從] 윗사람을 따라다니는 종."]},{"id":652,"category":"한자어","term":"편입","definition":"이미 짜인 한 동아리나 대열 따위에 끼어 들어감.","example":"그 어두운 열정은, 이제 밝고 떳떳한 삶으로의 편입이 불가능하다고 단정 짓게 되자마자 갑자기 그를 거세게 몰아친 것이었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[編入] 얽거나 짜 넣음.","[編入] 첫 학년에 입학하지 않고 어떤 학년에 도중에 들어가거나 다니던 학교를 그만두고 다른 학교에 들어감."]},{"id":653,"category":"한자어","term":"표지","definition":"표시나 특징으로 어떤 사물을 다른 것과 구별하게 함. 또는 그 표시나 특징.","example":"통행금지 표지.","exampleSource":"표준국어대사전 용례","otherMeanings":["[表紙] 책의 맨 앞뒤의 겉장.","[表紙] 읽던 곳이나 필요한 곳을 찾기 쉽도록 책갈피에 끼워 두는 종이쪽지나 끈.","[標紙] 증거의 표로 글을 적은 종이.","[標識] 다른 대상과 구별하여 어떤 대상을 확정하고, 그것을 인식할 수 있게 하는 표상적(表象的) 또는 개념적 특성."]},{"id":654,"category":"한자어","term":"게재","definition":"글이나 그림 따위를 신문이나 잡지 따위에 실음.","example":"그의 칼럼을 일주일에 한 번 신문에 게재하기로 했다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":655,"category":"한자어","term":"결제","definition":"증권 또는 대금을 주고받아 매매 당사자 사이의 거래 관계를 끝맺는 일.","example":"결제 자금.","exampleSource":"표준국어대사전 용례","otherMeanings":["[決濟] 일을 처리하여 끝을 냄.","[結制] 안거(安居) 제도를 준수함.","[結制] 안거를 시작함.","[駃騠] 빠르게 잘 달리는 말.","[駃騠] 수말과 암탕나귀 사이에서 난 일대(一代) 잡종. 외모는 당나귀와 비슷하고 노새보다 체질과 체격이 떨어진다. 몸이 약하고 성질이 사나워 실용 가치가 거의 없다. 수컷은 번식력이 전혀 없고 암컷은 간혹 수태하나 새끼는 매우 허약하다.","[闋制] 어버이의 삼년상을 마침."]},{"id":656,"category":"한자어","term":"계륵","definition":"닭의 갈비라는 뜻으로, 그다지 큰 소용은 없으나 버리기에는 아까운 것을 이르는 말. ≪후한서(後漢書)≫의 <양수전(楊修傳)>에 나오는 말이다.","example":"겨울이 되니 선풍기가 계륵 같은 물건이 되었다.","exampleSource":"제공 자료 예문","otherMeanings":["[鷄肋] 몸이 몹시 약한 사람을 비유적으로 이르는 말."]},{"id":657,"category":"한자어","term":"도탄","definition":"진구렁에 빠지고 숯불에 탄다는 뜻으로, 몹시 곤궁하여 고통스러운 지경을 이르는 말.","example":"도탄에 들다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":658,"category":"한자어","term":"동량","definition":"기둥과 들보로 쓸 만한 재목이라는 뜻으로, 집안이나 나라를 떠받치는 중대한 일을 맡을 만한 인재를 이르는 말.","example":"장차 나라의 동량이 될 어린이들.","exampleSource":"표준국어대사전 용례","otherMeanings":["[同量] 같은 분량.","[洞糧] 승려가 시주(施主)를 얻으려고 돌아다니는 일. 또는 그렇게 얻은 곡식.","[棟梁, /, 棟樑] 기둥과 들보를 아울러 이르는 말."]},{"id":659,"category":"한자어","term":"석권","definition":"돗자리를 만다는 뜻으로, 빠른 기세로 영토를 휩쓸거나 세력 범위를 넓힘을 이르는 말.","example":"중국 대륙의 석권.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":660,"category":"한자어","term":"숙환","definition":"오래 묵은 병.","example":"아버님께서는 숙환으로 고생하시다가 별세하셨다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[宿患] 오래된 걱정거리."]},{"id":661,"category":"한자어","term":"와중","definition":"일이나 사건 따위가 시끄럽고 복잡하게 벌어지는 가운데.","example":"많은 사람이 전란의 와중에 가족을 잃었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[渦中] 흐르는 물이 소용돌이치는 가운데.","[窩中] 굴의 안."]},{"id":662,"category":"한자어","term":"완벽","definition":"흠이 없는 구슬이라는 뜻으로, 결함이 없이 완전함을 이르는 말.","example":"완벽에 가까운 묘기.","exampleSource":"표준국어대사전 용례","otherMeanings":["[完璧] 빌린 물건을 정중히 돌려보냄. 중국 전국 시대 조나라의 인상여(藺相如)가 진(秦)나라의 소양왕이 열다섯 성(城)과 화씨(和氏)의 벽(璧)을 바꾸자고 하여 진나라에 갔으나 소양왕이 거짓말을 하고 있다는 것을 알고, 목숨을 걸고 그 벽을 고스란히 도로 찾아왔다는 데서 유래한다."]},{"id":663,"category":"한자어","term":"재연","definition":"한 번 하였던 행위나 일을 다시 되풀이함.","example":"상황 재연.","exampleSource":"표준국어대사전 용례","otherMeanings":["[再演] 연극이나 영화 따위를 다시 상연하거나 상영함.","[再緣] 결혼하였던 여자가 남편과 사별하거나 이혼하여 다른 남자와 결혼함.","[再燃] 꺼졌던 불이 다시 탐.","[再燃] 한동안 잠잠하던 일이 다시 문제가 되어 시끄러워짐.","[齋筵] 재식(齋食)을 마련하여 삼보(三寶)에 공양하는 법회."]},{"id":664,"category":"한자어","term":"재현","definition":"다시 나타남. 또는 다시 나타냄.","example":"즉 20세기에 들어와서 미술은 재현, 즉 모방을 버리고 표현을 주장하기에 이르렀다는 것이오.","exampleSource":"표준국어대사전 용례","otherMeanings":["[才賢] 재주가 뛰어나고 현명함. 또는 그런 사람.","[再現] 이미 경험하거나 학습한 정보를 다시 기억해 내는 일."]},{"id":665,"category":"한자어","term":"추호","definition":"매우 적거나 조금인 것을 비유적으로 이르는 말.","example":"당신을 모욕할 생각은 추호도 없었습니다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[秋毫] 가을철에 털갈이하여 새로 돋아난 짐승의 가는 털.","[追號] 죽은 임금에게 시호를 올림. 또는 그 시호.","[推戶] 지게문이나 사립문을 밀어서 엶."]},{"id":666,"category":"한자어","term":"각광","definition":"사회적 관심이나 흥미.","example":"각광을 받다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[脚光] 무대의 앞쪽 아래에 장치하여 배우를 비추는 광선."]},{"id":667,"category":"한자어","term":"간과","definition":"큰 관심 없이 대강 보아 넘김.","example":"나는 그 사실을 결코 간과하지 않았다.","exampleSource":"제공 자료 예문","otherMeanings":["[干戈] 방패와 창이라는 뜻으로, 전쟁에 쓰는 병기를 통틀어 이르는 말.","[干戈] 전쟁 또는 병란을 비유적으로 이르는 말.","[諫果] ‘감람03’을 달리 이르는 말. 남이 충고하는 말처럼, 처음에는 쓰고 떫으나 오래 씹을수록 달고 맛있는 과일이라는 뜻이다."]},{"id":668,"category":"한자어","term":"감안","definition":"여러 사정을 참고하여 생각함.","example":"기상 상황을 감안하여 출발 시간을 늦췄다.","exampleSource":"제공 자료 예문","otherMeanings":["[疳眼] 감병(疳病)으로 생기는 눈병. 눈이 깔깔하고 허는데 더 심해지면 짓무르기도 한다."]},{"id":669,"category":"한자어","term":"감수","definition":"책망이나 괴로움 따위를 달갑게 받아들임.","example":"전체를 위해서 개인의 희생이 감수될 수 있다는 생각은 옳지 않다.","exampleSource":"제공 자료 예문","otherMeanings":["[甘水] 맛이 단 물.","[甘遂] 대극과의 여러해살이풀. 줄기는 높이가 30cm 정도이고 붉은 보랏빛을 띠며, 자르면 젖 같은 흰색의 진이 나온다. 잎은 어긋나고 피침 모양이며, 줄기 끝에 긴 타원형의 잎이 돌려난다. 6~7월에 녹색을 띤 황색 꽃이 줄기 끝에 피고 열매는 삭과(蒴果)를 맺는다. 뿌리에는 독이 있는데 한방에서 부종(浮腫), 적취(積聚) 따위에 약으로 쓴다. 우리나라 각지에 분포한다.","[勘收] 자세히 조사하여 몰수함.","[淦水] 배의 밑바닥에 괴는 물.","[減水] 하천이나 호수 따위의 물이 줆. 또는 그 물.","[減收] 거두어들이는 것이 줆.","[減壽] 수명이 줆.","[減數] 돈이나 물품의 수를 줄임.","[減數] 어떤 수에서 다른 어떤 수를 뺄 때, 빼려는 수. ‘10-2=8’에서 ‘2’를 이른다.","[酣睡] 깊이 단잠을 잠.","[感受] 외부의 영향을 수동적으로 받아들임.","[感受] 외부 세계의 자극을 감각 신경이 받아들이는 일.","[感祟] 감기의 빌미.","[監守] 감독하고 지킴. 또는 그런 일을 맡은 사람.","[監收] 절에 딸린 땅을 관리하고 수입을 감독하는 직책. 또는 그 직책에 있는 사람.","[監修] 책의 저술이나 편찬 따위를 지도하고 감독함."]},{"id":670,"category":"한자어","term":"강구","definition":"좋은 대책과 방법을 궁리하여 찾아내거나 좋은 대책을 세움.","example":"대책 강구.","exampleSource":"표준국어대사전 용례","otherMeanings":["→ 말감고.","[江口] 강물이 바다로 흘러가는 어귀.","[江口] 강이나 내, 또는 좁은 바닷목에서 배가 건너다니는 일정한 곳.","[江鷗] 강에서 노는 갈매기.","[康衢] 사방으로 두루 통하는 번화한 큰 길거리.","[強仇] 강한 적수. 또는 만만찮은 상대.","[強求] 구하기 힘든 것을 억지로 구함.","[強求] 억지로 또는 강제로 요구함.","[強寇] 힘이 세고 강한 적이나 도둑.","[鋼球] 강철로 둥글게 만든 알.","[講求] 조사하여 구함."]},{"id":671,"category":"한자어","term":"개연성","definition":"절대적으로 확실하지 않으나 아마 그럴 것이라고 생각되는 성질.","example":"개연성이 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":672,"category":"한자어","term":"고사","definition":"제의나 권유 따위를 굳이 사양함.","example":"수차례의 고사 끝에 결국에는 그 제의를 받아들이게 되었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["동양화에서, 석간주(石間硃)라는 검붉은 흙에 먹을 섞어 만든 검붉은 색. 담채화, 수묵화, 진채화 따위에 쓴다.","[古史] 옛날 역사.","[古寺] 오래된 절.","[古事] 지나간 과거의 일.","[古祠] 오래된 낡은 사당(祠堂).","[古楂] 오래 묵은 나뭇등걸이나 그루터기.","[叩謝] 머리를 조아려서 고마운 마음을 나타냄.","[叩謝] 머리를 조아려서 죄를 빎.","[考思] 생각하고 헤아려 봄.","[考査] 자세히 생각하고 조사함.","[考査] 학생들의 학업 성적을 평가하는 시험.","[考査] 고려ㆍ조선 시대에, 관리의 근무 성적을 평가하여 결정하던 일. 승진과 좌천, 포상과 처벌에 반영하였다.","[告祀] 액운(厄運)은 없어지고 풍요와 행운이 오도록 집안에서 섬기는 신(神)에게 음식을 차려 놓고 비는 제사.","[告詞, /, 告辭] 의식(儀式) 때에 상급자가 글로 써서 읽어 축하하거나 훈시하는 말.","[姑捨] ‘고사하다05’의 어근.","[孤寺] 마을에서 멀리 떨어져 있는 외딴 절.","[故事] 유래가 있는 옛날의 일. 또는 그런 일을 표현한 어구.","[故事] 옛날부터 전해 오는 규칙이나 정례(定例).","[故事] 지나간 과거의 일.","[枯死] 나무나 풀 따위가 말라 죽음.","[苦使] 매우 혹독하게 일을 시키거나 부림.","[苦思] 괴롭거나 고통스러운 생각.","[苦思] 마음을 썩이며 깊이 생각함.","[苦詞] 괴로움을 말로 늘어놓음.","[苦辭] 간절히 사양함.","[庫司] 절의 모든 일을 감독하는 직책.","[庫舍] 예전에, 곳간으로 쓰려고 지은 집.","[庫紗] 여름 옷감으로 쓰는 비단의 하나. 감이 약간 두껍고 깔깔하며 윤이 나는데, 삶지 않은 명주실로 짠 생고사와 삶은 명주실로 짠 숙고사가 있다.","[高士] 인격이 높고 성품이 깨끗한 선비. 특히 산속에 숨어 살며 세속에 물들지 않은 덕망 있는 선비를 이른다.","[高砂] ‘타이완’의 다른 이름.","[高射] 공중에 높이 쏨.","[高師] 일제 강점기에, ‘고등 사범 학교’를 줄여 이르던 말.","[鼓詞] 산문(散文)의 이야기와 운문(韻文)의 창(唱)으로 구성된 중국의 창극. 우리나라 판소리와 비슷하여 긴 사설로 엮어진 노래에 북을 쳐 장단을 맞추는데, 송나라 때에 시작되어 베이징, 톈진(天津)을 중심으로 북방에서 유행하였다.","[篙師] 배를 부리는 일에 숙련된 나이든 뱃사공."]},{"id":673,"category":"한자어","term":"고취","definition":"의견이나 사상 따위를 열렬히 주장하여 불어넣음.","example":"민족주의 사상의 고취.","exampleSource":"표준국어대사전 용례","otherMeanings":["[高趣] 고상한 운치.","[鼓吹] 북을 치고 피리를 붊.","[鼓吹] 힘을 내도록 격려하여 용기를 북돋움.","[鼓吹] 군악을 아뢰던 악대. 중국 후한 때에 비롯되었다.","[鼓吹] 조선 시대에, 궁중 의식이나 임금이 나들이할 때 타악기와 취주 악기로 아뢰던 음악.","[鼓觜] 학춤에서 부리를 치는 동작."]},{"id":674,"category":"한자어","term":"공조","definition":"여러 사람이 함께 도와주거나 서로 도와줌.","example":"야권 공조.","exampleSource":"표준국어대사전 용례","otherMeanings":["[工曹] 고려 시대에, 육조(六曹) 가운데 산택(山澤)ㆍ공장(工匠)ㆍ영조(營造)를 맡아보던 관아. 충렬왕 24년에 설치하였는데 공민왕 5년(1356)에는 공부(工部)라 불렀으며, 한때 전공사(典工司)라고 하다가 공양왕 원년(1389)에 다시 이 이름으로 고쳤다.","[工曹] 조선 시대에, 육조(六曹) 가운데 산택ㆍ공장ㆍ영선(營繕)ㆍ도야(陶冶)를 맡아보던 정이품 아문. 태조 1년(1392)에 설치하여 고종 31년(1894)에 공무아문으로 이름을 고쳤다.","[工造] 조선 시대에, 공조(工曹)ㆍ군기시ㆍ상의원(尙衣院)ㆍ교서관 따위의 관아에 속한 장인들에게 준 종팔품 벼슬.","[公租] 국가 또는 지방 공공 단체가 필요한 경비로 사용하기 위하여 국민이나 주민으로부터 강제로 거두어들이는 금전. 국세와 지방세가 있다.","[功曹] 중국 한(漢)나라 때에, 군(郡)에 속하여 군리의 임면(任免) 및 상벌에 관한 일을 맡아보던 구실아치.","[恐鳥] 모아목의 새를 통틀어 이르는 말. 키는 2~3.5미터로 거대하나 날개가 없어 날지 못한다. 뉴질랜드에서 번성했던 새로서, 20여 종이 있었다고 추정되나 마오리족의 남획과 특수한 진화에 의하여 19세기 말에 멸종하였다.","[貢租] 공물로 바치는 조세.","[貢調] 공물을 바침."]},{"id":675,"category":"한자어","term":"귀결","definition":"어떤 결말이나 결과에 이름. 또는 그 결말이나 결과.","example":"당연한 귀결.","exampleSource":"표준국어대사전 용례","otherMeanings":["[歸結] 어떤 사태를 원인으로 하여 그 결과로 생기는 상태. 또는 일정한 논리적 전제로부터 이끌어 내게 되는 결론."]},{"id":676,"category":"한자어","term":"기인","definition":"어떠한 것에 원인을 둠.","example":"이번 사고는 운전자의 부주의에서 기인했다.","exampleSource":"제공 자료 예문","otherMeanings":["[其人] 고려ㆍ조선 시대에, 지방 호족 및 토호의 자제로서 중앙에 볼모로 와서 그 출신 지방의 행정에 고문(顧問) 구실을 하던 사람. 또는 그런 제도. 지방 세력을 견제하고 중앙 집권을 강화하기 위한 정책으로, 신라의 상수리 제도에서 유래하였다.","[其人] 조선 전기에, 궁중의 잡역을 위하여 소집한 지방 백성.","[奇人] 성격이나 말, 행동 따위가 보통 사람과 다른 별난 사람.","[起因] 일이 일어나게 된 까닭.","[基因] 근본이 되는 원인.","[飢人] 굶주린 사람.","[幾人] 몇 사람.","[棄人] 도리에서 벗어난 행동을 하여 버림을 받은 사람.","[棄人] 쓸모없이 된 사람.","[欺人] 사람을 속임.","[畸人] 독특한 지조와 행실이 있어서 세상의 풍속과 다른 면이 있는 사람.","[畸人] 몸의 어느 부분이 온전하지 못한 사람.","[旗人] 중국 청나라 때에 팔기에 딸렸던 사람. 팔기는 청나라 건국에 공이 많은 만주족의 군인들로 주로 짜였는데 일반 사람보다 좋은 대우를 받았다."]},{"id":677,"category":"한자어","term":"난항","definition":"여러 가지 장애 때문에 일이 순조롭게 진행되지 않음을 비유적으로 이르는 말.","example":"난항을 겪다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[亂杭] 적의 기병을 막으려고 굵은 말뚝을 불규칙하게 박아 동아줄로 얼기설기 얽어 놓은 장애물.","[難航] 폭풍우와 같은 나쁜 조건으로 배나 항공기가 몹시 어렵게 항행함."]},{"id":678,"category":"한자어","term":"단초","definition":"일이나 사건을 풀어 나갈 수 있는 첫머리.","example":"문제 해결의 단초를 제공하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[斷礎] 깨어져 조각이 난 주춧돌."]},{"id":679,"category":"한자어","term":"도모","definition":"어떤 일을 이루기 위하여 대책과 방법을 세움.","example":"부원들 간의 친목 도모를 위해 주말에 야유회를 가기로 했다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[叨冒] 지나치게 탐하는 욕심.","[桃毛] 복숭아의 털. 몸에 있는 나쁜 기운을 물리치는 약으로 쓴다.","[悼耄] 일곱 살 어린이와 여든 살 늙은이를 아울러 이르는 말.","[掏摸] 남의 몸이나 가방을 슬쩍 뒤져 금품을 훔치는 짓. 또는 그런 사람."]},{"id":680,"category":"한자어","term":"묵인","definition":"모르는 체하고 하려는 대로 내버려 둠으로써 슬며시 인정함.","example":"상급자의 묵인 아래 부정을 저지르다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":681,"category":"한자어","term":"반증","definition":"어떤 사실이나 주장이 옳지 아니함을 그에 반대되는 근거를 들어 증명함. 또는 그런 증거.","example":"우리에겐 그 사실을 뒤집을 만한 반증이 없다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[反證] 어떤 사실과 모순되는 것 같지만, 거꾸로 그 사실을 증명하는 것."]},{"id":682,"category":"한자어","term":"방증","definition":"사실을 직접 증명할 수 있는 증거가 되지는 않지만, 주변의 상황을 밝힘으로써 간접적으로 증명에 도움을 줌. 또는 그 증거.","example":"방증 자료.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":683,"category":"한자어","term":"부각","definition":"어떤 사물을 특징지어 두드러지게 함.","example":"상품명 선전은 효과가 단명한 데 비해 회사 자체의 이미지 부각은 그 수명이 영원하다는 주장과 함께 이를 위해 돈 대신 머리를 썼다.","exampleSource":"표준국어대사전 용례","otherMeanings":["다시마 조각, 깻잎, 고추 따위에 찹쌀 풀을 발라 말렸다가 기름에 튀긴 반찬.","[負角] ‘음각01’의 전 용어.","[俯角] 높은 곳에서 낮은 곳에 있는 지점을 내려다볼 때, 그 시선과 수평면이 이루는 각.","[浮刻] 조각에서, 평평한 면에 글자나 그림 따위를 도드라지게 새기는 일.","[腐刻] 약물을 써서 유리나 금속 따위에 조각함. 또는 그런 일."]},{"id":684,"category":"한자어","term":"상충","definition":"맞지 아니하고 서로 어긋남.","example":"두 나라 간의 이해관계의 상충으로 전쟁이 일어났다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[上衝] 위로 치밀어 오름.","[相沖] 사물이 서로 어울리지 아니하고 마주침.","[相沖] 방위, 일진(日辰), 시 따위가 서로 어울리지 아니하고 맞질림.","[桑蟲] 뽕나무하늘소의 애벌레. 뽕나무 줄기를 갉아 먹는 해충인데 한약재로 쓴다."]},{"id":685,"category":"한자어","term":"선양","definition":"명성이나 권위 따위를 널리 떨치게 함.","example":"그는 지역의 전통문화를 선양하는 데 힘썼다.","exampleSource":"제공 자료 예문","otherMeanings":["[煽揚] 부추기어 일으킴.","[禪讓] 임금의 자리를 물려줌.","[Shenyang[瀋陽]] 중국 만주 랴오닝성(遼寧省)에 있는 도시. 교통의 요지이며 중공업이 발달하였다. 성내에는 궁전이 있고, 교외에 동릉(東陵)ㆍ북릉(北陵) 따위의 청나라 명소가 있다. 1932년 일본에 의하여 만주국이 건국되면서 펑톈(奉天)으로 이름이 바뀌었다가 1950년에 다시 선양으로 바뀌었다. 랴오닝성의 성도(省都)이다."]},{"id":686,"category":"한자어","term":"시사","definition":"어떤 것을 미리 간접적으로 표현해 줌.","example":"낙관적인 시사를 던져 주다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[市肆] 시장 거리의 가게.","[市肆] 조선 시대에, 지금의 종로를 중심으로 설치한 상설 시장. 관아에서 임대하여 주고, 특정 상품에 대한 독점 판매권과 난전을 금지하는 특권을 주는 대신 관아에서 필요로 하는 물품을 바칠 의무를 부과하였다.","[侍史] 옆에 모시면서 문서를 작성하고 처리하는 사람.","[侍史] 편지 겉봉에 공경하는 뜻으로, 받는 사람의 이름 아래 쓰는 말.","[侍史] 고려 시대에, 감찰사(監察司)에 속한 종오품 벼슬. 충렬왕 원년(1275)에 어사대를 감찰사로 고칠 때에, 시어사를 고친 것이다.","[侍史] 고려 말기ㆍ조선 전기에, 사헌부에 속한 정사품 벼슬. 고려 공민왕 18년(1369)에 장령(掌令)을 고친 것으로, 태종 원년(1401)에 다시 장령으로 고쳤다.","[侍師] 스승을 모심. 또는 스승으로 모심.","[侍射] 임금이 활을 쏠 때에 곁에서 모시고 활을 쏘던 일.","[侍射] 임금이 활을 쏠 때, 곁에서 모시고 거들어 주는 일을 맡은 신하.","[施舍] 은덕을 베풀어 줌.","[施舍] 나그네가 짐을 풀고 숙박하게 해 줌. 또는 그런 곳.","[時仕] 아전이나 기생 등이 그 매인 관아에서 맡은 일을 함. 또는 그 일.","[時事] 그 당시에 일어난 여러 가지 사회적 사건.","[時祀] 음력 2월, 5월, 8월, 11월에 가묘에 지내는 제사.","[時祀] 음력 10월에 5대 이상의 조상 무덤에 지내는 제사.","[視事] 임금이 신하들과 나랏일을 돌보던 일.","[詩史] 시의 발생ㆍ변천ㆍ발달 과정에 관한 역사. 또는 그것에 관한 저술.","[詩史] 서사시의 하나. 역사적 사실을 소재로 해서 쓴 시이다.","[詩社] 시인들이 조직한 문학적 단체.","[詩思] 시적인 생각이나 상념.","[試射] 총이나 활 따위를 시험 삼아 쏘아 봄. 또는 그렇게 하는 일.","[試射] 사격에 필요한 여러 기구의 성능과 특성을 검토하고 결정하기 위하여 총이나 포를 쏘아 봄.","[試射] 활을 잘 쏘는 사람을 시험 보아 뽑던 일.","[詩詞] 시(詩)와 사(詞)를 아울러 이르는 말.","[試寫] 영화나 광고 따위를 일반에게 공개하기 전에 심사원, 비평가, 제작 관계자 등의 특정인에게 시험적으로 보이는 일."]},{"id":687,"category":"한자어","term":"심화","definition":"정도나 경지가 점점 깊어짐. 또는 깊어지게 함.","example":"빈부 격차의 심화가 사회적 문제로 부각되었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[心火] 마음속에서 북받쳐 나는 화.","[心火] 마음속의 울화로 몸과 마음이 답답하고 몸에 열이 높아지는 병.","[心火] 심장을 오행(五行)의 화(火)에 소속시켜 이르는 말.","[心火] 심장의 본질을 화(火)로 보아 심장의 정상적 생리 기능을 이르는 말.","[心火] 지압하는 부위. 가운뎃손가락 끝마디를 이른다.","[心畫] 마음을 나타내는 그림이라는 뜻으로, 문자나 필적을 이르는 말."]},{"id":688,"category":"한자어","term":"엄수","definition":"명령이나 약속 따위를 어김없이 지킴.","example":"교칙 엄수.","exampleSource":"표준국어대사전 용례","otherMeanings":["[閹豎] 조선 시대에, 내시부에 속하여 임금의 시중을 들거나 숙직 따위의 일을 맡아보던 남자. 모두 거세된 사람이었다.","[嚴囚] 달아나지 못하도록 엄중하게 가둠.","[嚴修] 의식 따위를 엄숙하게 치름."]},{"id":689,"category":"한자어","term":"영수","definition":"여러 사람 가운데 우두머리.","example":"여야 영수 회담.","exampleSource":"표준국어대사전 용례","otherMeanings":["[永壽] 오래도록 삶.","[英秀] ‘영수하다02’의 어근.","[英數] 영어와 수학을 아울러 이르는 말.","[瓴水] 지붕의 기와에서 흘러내리는 빗물이라는 뜻으로, 도저히 막지 못하는 형세를 비유적으로 이르는 말.","[零數] 10, 100, 1000 따위의 정수(整數)에 차지 못하거나 차고 남은 수.","[領水] 한 나라의 주권이 미치는 범위의 수역. 영해(領海) 외에 하천, 호소(湖沼), 항만 따위의 내수(內水)를 포함한다.","[領水] 영토에 인접한 해역으로서, 그 나라의 통치권이 미치는 범위. 연안해, 내해(內海), 만(灣), 해협 따위로 이루어지는데, 해수면이 가장 낮은 썰물 때의 해안선을 기준으로 폭 3해리까지가 보통이지만 나라에 따라 6해리, 12해리를 주장하기도 한다.","[領收, /, 領受] 돈이나 물품 따위를 받아들임.","[領袖] 장로교에서, 조직이 아직 갖추어지지 아니한 교회를 인도하는 임시 직분. 또는 그런 사람.","[營需] 군영(軍營)에 필요한 물품.","[贏輸] 이김과 짐.","[靈水] 신비스러운 효험이 있는 물.","[靈秀] ‘영수하다04’의 어근.","[靈邃] ‘영수하다05’의 어근.","[靈獸] 상서로운 짐승. 기린 따위를 이른다."]},{"id":690,"category":"한자어","term":"취재","definition":"작품이나 기사에 필요한 재료나 제재(題材)를 조사하여 얻음.","example":"취재 활동.","exampleSource":"표준국어대사전 용례","otherMeanings":["[取才] 재주를 시험하여 사람을 뽑음.","[臭載] 배에 실은 짐이 상하여 냄새가 나고 못 쓰게 됨.","[臭載] 짐을 실은 배가 뒤집어져 가라앉음."]},{"id":691,"category":"한자어","term":"쾌척","definition":"금품을 마땅히 쓸 자리에 시원스럽게 내놓음.","example":"사업가는 수재민을 위해 거액을 쾌척했다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":692,"category":"한자어","term":"간주","definition":"상태, 모양, 성질 따위가 그와 같다고 봄. 또는 그렇다고 여김.","example":"법원은 그 행위를 계약 위반으로 간주했다.","exampleSource":"제공 자료 예문","otherMeanings":["[間奏] 한 악곡의 도중에 어떤 기분을 나타내기 위하여 연주하는 부분. 협주곡의 독주부에 끼인 관현악의 합주 부분이나 노래가 잠시 그친 사이에 연주되는 기악 반주 따위이다.","[間奏] 악곡이나 오페라, 시의 낭독 사이에 삽입되는 기악 소곡.","[間柱] 기둥과 기둥 사이가 너무 멀어서 칸막이벽을 치거나 벽 바탕재를 건너 댈 수 없을 때 기둥 사이에 세우는 가는 기둥."]},{"id":693,"category":"한자어","term":"간파","definition":"속내를 꿰뚫어 알아차림.","example":"윤명선은…그의 처지며 그의 주위에서 생기고 있는 일이 무엇인지 대뜸 간파를 한 것 같았다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":694,"category":"한자어","term":"검침","definition":"전기, 수도, 가스 따위의 사용량을 알기 위하여 계량기의 숫자를 검사함.","example":"수돗물 검침이 잘못되어 요금이 많이 나왔다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[黔沈] ‘검침하다02’의 어근."]},{"id":695,"category":"한자어","term":"결연","definition":"인연을 맺음. 또는 그런 관계.","example":"의료 기관과 양로원의 결연을 추진했다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[決然] ‘결연하다01’의 어근.","[缺然] ‘결연하다02’의 어근.","[訣宴] 헤어짐을 아쉬워하여 베푸는 연회.","[結緣] 불보살이 중생을 구제하기 위하여 중생과 인연을 맺음.","[結緣] 중생이 불도를 닦기 위하여 삼보(三寶)와 인연을 맺음."]},{"id":696,"category":"한자어","term":"결의","definition":"뜻을 정하여 굳게 마음을 먹음. 또는 그런 마음.","example":"결의 대회.","exampleSource":"표준국어대사전 용례","otherMeanings":["[決疑] 의혹을 풂.","[決議] 의논하여 결정함. 또는 그런 결정.","[結義] 남남끼리 형제, 자매, 남매, 부자 따위 친족의 의리를 맺음."]},{"id":697,"category":"한자어","term":"경선","definition":"둘 이상의 후보가 경쟁하는 선거.","example":"경선으로 회장을 뽑다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[徑先] ‘경선하다’의 어근.","[徑線] 원이나 구 따위에서, 중심을 지나는 직선으로 그 둘레 위의 두 점을 이은 선분.","[經線] 지구를 남극과 북극을 지나는 평면으로 잘랐을 때, 그 평면과 지구 표면이 만나는 가상적인 선.","[傾船] 배를 기울어지게 하는 일.","[鯨船] 고래를 잡기 위하여 특별한 설비를 갖춘 배."]},{"id":698,"category":"한자어","term":"계시","definition":"사람의 지혜로써는 알 수 없는 진리를 신(神)이 가르쳐 알게 함.","example":"휴정은 부처의 계시를 받은 듯, 홀연히 시심(詩心)이 움직였다.","exampleSource":"표준국어대사전 용례","otherMeanings":["공장(工匠) 밑에서 일을 배우는 제자.","[계, 示] → 게시02.","[癸時] 이십사시(二十四時)의 둘째 시. 오전 영시 반에서 한 시 반까지이다.","[計示] 부기(簿記)에서, 거래 내용을 차변(借邊)과 대변(貸邊)으로 나누어 적는 일.","[計時] 기록 경기나 바둑 따위에서, 소요 시간을 재는 일. 또는 그 시간.","[啓示] 깨우쳐 보여 줌."]},{"id":699,"category":"한자어","term":"괘념","definition":"마음에 두고 걱정하거나 잊지 않음.","example":"급한 일이 있으면 괘념 말고 가 보게.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":700,"category":"한자어","term":"교시","definition":"가르쳐서 보임.","example":"승리는 신도들에게 여러 가지 지혜를 교시하였다.","exampleSource":"제공 자료 예문","otherMeanings":["[交市] 주로 나라와 나라 사이에서 물건을 사고팔고 하여 서로 바꿈.","[校是] 학교의 기본 교육 방침.","[校時] 학교의 수업 시간을 세는 단위. 흔히 40분 또는 45분, 50분 따위로 정한다.","[敎示] 길잡이로 삼는 가르침."]},{"id":701,"category":"한자어","term":"교정","definition":"남의 문장 또는 출판물의 잘못된 글자나 글귀 따위를 바르게 고침.","example":"출판 전에 원고의 오자를 교정했다.","exampleSource":"제공 자료 예문","otherMeanings":["[交情] 사귀는 정. 또는 사귀어 온 정.","[校正] 교정쇄와 원고를 대조하여 오자, 오식, 배열, 색 따위를 바르게 고침.","[校定] 출판물의 글자나 글귀를 검토하여 바르게 정하는 일.","[校庭] 학교의 마당이나 운동장.","[敎正] 가르쳐서 바르게 함.","[敎政] 교회를 다스리는 일.","[敎程] 가르치는 정도.","[敎程] 가르치는 순서와 방식.","[敎程] 학교에서 교과 과정에 따라 주된 교재로 사용하기 위하여 편찬한 책.","[敎程] 가르치는 과정.","[較正] 계기류의 정밀도 따위를 표준기와 비교하여 바로잡음.","[鉸釘] 강철 재료를 이어 붙이는 데 쓰는 못.","[矯正] 틀어지거나 잘못된 것을 바로잡음.","[矯正] 교도소나 소년원 따위에서 재소자의 잘못된 품성이나 행동을 바로잡음.","[矯正] 골절이나 탈구로 어긋난 뼈를 본디로 돌리는 일.","[矯情] 진심을 속이고 거짓으로 꾸밈.","[矯情] 마음속에서 우러나오는 감정을 억눌러 나타내지 않음.","[轎丁] 가마를 메는 사람."]},{"id":702,"category":"한자어","term":"구명","definition":"사물의 본질, 원인 따위를 깊이 연구하여 밝힘.","example":"고대 유물에 대한 문제의 구명에서 무엇보다도 긴요한 것은 객관적인 자료의 뒷받침이다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[九命] 중국 주나라 때, 관원의 아홉 가지 임명 순서.","[求命] 맹인이 무경(巫經)을 소리 내어 읽어 안택이나 살풀이 따위를 하는 일.","[苟命] 구차한 목숨.","[救命] 사람의 목숨을 구함.","[舊名] 고치기 전의 이름. 또는 예전에 부르던 이름.","[軀命] 몸과 목숨을 아울러 이르는 말."]},{"id":703,"category":"한자어","term":"궐위","definition":"어떤 직위나 관직 따위가 빔. 또는 그런 자리.","example":"대통령의 궐위 시에는 국무총리가 그 직을 대행한다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":704,"category":"한자어","term":"기우","definition":"앞일에 대해 쓸데없는 걱정을 함. 또는 그 걱정. 옛날 중국 기(杞)나라에 살던 한 사람이 ‘만일 하늘이 무너지면 어디로 피해야 좋을 것인가?’ 하고 침식을 잊고 걱정하였다는 데서 유래한다.","example":"기우를 덜다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[奇偶] 홀수와 짝수를 아울러 이르는 말.","[奇遇] 기이한 인연으로 만남.","[祈雨] 날이 가물 때에 비가 오기를 빎.","[氣宇] 기개와 도량을 아울러 이르는 말.","[基宇] 사물의 본질이나 본바탕.","[基宇] 사물이나 일 따위의 기본이 되는 것.","[基宇] 건물, 다리 따위와 같은 구조물의 무게를 받치기 위하여 만든 밑받침.","[寄寓] 임시로 남의 집에 몸을 의지하고 지냄.","[器宇] 사람의 재능과 도량을 아울러 이르는 말.","[騎牛] 소를 탐. 또는 탈것으로 이용하는 소.","[羈寓, /, 羇寓] 자기 고향이 아닌 고장에서 사는 일."]},{"id":705,"category":"한자어","term":"기탄","definition":"어렵게 여겨 꺼림.","example":"그는 아무런 기탄이 없이 말을 이었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":706,"category":"한자어","term":"기한","definition":"미리 한정하여 놓은 시기.","example":"납품 기한.","exampleSource":"표준국어대사전 용례","otherMeanings":["[祁寒] 매우 심한 추위.","[飢寒, /, 饑寒] 굶주리고 헐벗어 배고프고 추움.","[期限] 어느 때까지를 기약함.","[期限] 법률 행위의 효력의 발생 및 소멸, 채무 이행을 장래에 발생할 것이 확실한 사실에 의존시키는 일."]},{"id":707,"category":"한자어","term":"난삽하다","definition":"글이나 말이 매끄럽지 못하면서 어렵고 까다롭다.","example":"난삽한 문장.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":708,"category":"한자어","term":"낭패","definition":"계획한 일이 실패로 돌아가거나 기대에 어긋나 매우 딱하게 됨.","example":"낭패를 당하다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":709,"category":"한자어","term":"노략","definition":"떼를 지어 돌아다니며 사람을 해치거나 재물을 강제로 빼앗음.","example":"노략을 일삼다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":710,"category":"한자어","term":"동경","definition":"어떤 것을 간절히 그리워하여 그것만을 생각함.","example":"동경의 대상.","exampleSource":"표준국어대사전 용례","otherMeanings":["[同庚] 육십갑자가 같다는 뜻으로, 같은 나이를 이르는 말. 또는 나이가 같은 사람.","[同慶] 모두 함께 경축함.","[東京] 발해 때에 둔 오경(五京)의 하나.","[東京] 고려 시대에 둔 사경(四京) 가운데 지금의 경주에 해당하는 행정 구역.","[東京] ‘도쿄’를 우리 한자음으로 읽은 이름.","[東經] 지구 동반구의 경도. 본초 자오선을 0도로 하여 동쪽으로 180도까지의 경선이다.","[動徑] 점의 위치를 표시할 때, 기준이 되는 점으로부터 그 점까지 그은 직선을 벡터로 하는 선분.","[銅鏡] 구리로 만든 거울. 통일 신라 시대의 유물이다. 국보 제126-18호.","[憧憬] 마음이 스스로 들떠서 안정되지 아니함."]},{"id":711,"category":"한자어","term":"동정","definition":"일이나 현상이 벌어지고 있는 낌새.","example":"적의 동정을 살피다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[null] 한복의 저고리 깃 위에 조붓하게 덧대어 꾸미는 하얀 헝겊 오리.","[冬凊] 겨울에는 따뜻하게, 여름에는 서늘하게 한다는 뜻으로, 부모를 잘 섬기어 효도함을 이르는 말.","[同正] 고려 시대에, 육품 이하의 문관과 오품 이하의 무관에게 주던, 정직(正職)에 준하는 명예직. 처음으로 벼슬길에 오르는 경우에 주었으며 정직 이름 밑에 붙여 썼다.","[同定] 생물의 분류학상의 소속이나 명칭을 바르게 정하는 일.","[同定] 화학적 분석과 측정 따위로 해당 물질이 다른 물질과 동일한지 여부를 확인하는 일. 또는 그 물질의 소속과 명칭을 정하는 일.","[同情] 남의 어려운 처지를 자기 일처럼 딱하고 가엾게 여김.","[同情] 남의 어려운 사정을 이해하고 정신적으로나 물질적으로 도움을 베풂.","[東井] 이십팔수의 스물두째 별자리.","[東井] 음력 오월.","[東征] 동방을 정벌함. 또는 동으로 원정함.","[東庭] 집 안의 동쪽에 있는 뜰.","[東庭] 성균관의 명륜당 동쪽에 있는 뜰. 승학시를 보는 유생들이 앉던 곳이다.","[東淨] 절의 뒷간. 승방의 동쪽에 있었던 데에서 유래한다.","[動靜] 물질의 운동과 정지.","[動靜] 사람이 일상적으로 하는 일체의 행위.","[童貞] 이성과 한 번도 성교(性交)를 하지 아니하고 그대로 지키고 있는 순결. 또는 그런 사람."]},{"id":712,"category":"한자어","term":"동향","definition":"사람들의 사고, 사상, 활동이나 일의 형세 따위가 움직여 가는 방향.","example":"학계의 연구 동향.","exampleSource":"표준국어대사전 용례","otherMeanings":["[冬享] 겨울에 지내는 제사.","[同鄕] 고향이 같음. 또는 같은 고향.","[東向] 동쪽으로 향함. 또는 그 방향.","[動向] 어떤 특정한 사람이나 사물의 낱낱의 움직임."]},{"id":713,"category":"한자어","term":"발군","definition":"여럿 가운데에서 특별히 뛰어남.","example":"발군의 성적.","exampleSource":"표준국어대사전 용례","otherMeanings":["[發軍] 전쟁을 하기 위하여 군사를 일으킴.","[撥軍] 각 역참에 속하여 중요한 공문서를 교대 교대로 변방에 급히 전하던 군졸. 보발(步撥)과 기발(騎撥)이 있었다."]},{"id":714,"category":"한자어","term":"발굴","definition":"세상에 널리 알려지지 않거나 뛰어난 것을 찾아 밝혀냄.","example":"신인 발굴.","exampleSource":"표준국어대사전 용례","otherMeanings":["[發掘] 땅속이나 큰 덩치의 흙, 돌 더미 따위에 묻혀 있는 것을 찾아서 파냄."]},{"id":715,"category":"한자어","term":"발발하다","definition":"전쟁이나 큰 사건 따위가 갑자기 일어나다.","example":"전쟁이 발발하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["표정이나 행동이 밝고 활기가 있다.","[勃勃, 하다] 기운이나 기세가 끓어오를 듯이 성하다."]},{"id":716,"category":"한자어","term":"비루하다","definition":"행동이나 성질이 너절하고 더럽다.","example":"비루한 태도.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":717,"category":"한자어","term":"사의","definition":"감사하게 여기는 뜻.","example":"사의를 나타내다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[司衣] 고려 시대에, 성중관 가운데 임금의 의복에 관한 일을 맡아보던 벼슬아치.","[司儀] 신라 때에, 영객부에 속한 벼슬. 경덕왕 때 사지(舍知)를 고친 것으로, 혜공왕 때 다시 사지로 고쳤다.","[司儀] 고려 시대에, 태상시에 속한 벼슬. 박사(博士)의 다음이다.","[司議] 조선 시대에, 장례원(掌隷院)에 속하여 노비의 적(籍)과 소송에 관한 일을 맡아보던 정오품의 벼슬.","[四儀] 수행자가 생활에서 갖추어야 할 네 가지의 몸가짐. 행(行), 주(住), 좌(坐), 와(臥)이다.","[死義] 의를 위하여 죽음.","[死義] 죽음의 의의.","[私意] 개인의 의견.","[私意] 사사로운 마음. 또는 자기 욕심을 채우려는 마음.","[私誼] 개인 사이에 오래 사귀어 온 정분.","[私議] 사사로이 의논함. 또는 그런 의논.","[私議] 은밀히 비평함. 또는 뒤에서 비방함.","[私議] 사사로운 개인의 의견.","[私議] 시의(諡議)의 하나로, 명신(名臣)이 시호(諡號)를 못 얻었을 때 그 문하생들이 여러모로 생각하는 일.","[邪意] 사악한 마음.","[邪義] 종교의 부정한 가르침.","[邪議] 부정한 의논.","[邪議] 간악한 계략.","[事宜] 이치에 맞아 일이 마땅함.","[事意] 일의 내용.","[思義] 옳은 길을 그리며 생각함.","[思議] 생각하여 헤아림.","[射儀] 사술(射術)에 관한 의식.","[徙倚] 이리저리 왔다 갔다 함.","[斜欹] 비스듬히 기울어짐. 또는 그런 상태나 정도.","[蛇醫] 도롱뇽과의 동물. 몸의 길이는 15cm 정도이며, 갈색 바탕에 둥근 무늬가 있다. 머리는 납작하고 꼬리가 좌우로 편평하며 옆구리에 열세 줄의 홈이 있다. 물이 깨끗하고 수온이 낮은 개울, 못, 습지 따위의 낙엽 밑이나 땅속에 사는데 우리나라 특산종이다.","[蓑衣, /, 簑衣] 짚, 띠 따위로 엮어 허리나 어깨에 걸쳐 두르는 비옷. 예전에 주로 농촌에서 일할 때 비가 오면 사용하던 것으로 안쪽은 엮고 겉은 줄거리로 드리워 끝이 너털너털하게 만든다.","[寫意] 그림 따위를 그리고 싶은 마음.","[寫意] 의미를 옮겨 쓰는 일.","[寫意] 그림에서, 사물의 형태보다는 그 내용이나 정신에 치중하여 그리는 일.","[謝意] 잘못을 비는 뜻.","[謝儀] 상대편에게 고마움의 뜻으로 보내는 물품.","[辭意] 맡아보던 일자리를 그만두고 물러날 뜻.","[辭意] 글이나 말로 이야기되는 뜻."]},{"id":718,"category":"한자어","term":"사족","definition":"뱀을 다 그리고 나서 있지도 아니한 발을 덧붙여 그려 넣는다는 뜻으로, 쓸데없는 군짓을 하여 도리어 잘못되게 함을 이르는 말.","example":"설명 끝에 덧붙인 한마디는 오히려 사족이 되었다.","exampleSource":"교정 예문","otherMeanings":["[士族] 문벌이 좋은 집안. 또는 그 자손.","[士族] 선비나 무인(武人)의 집안. 또는 그 자손.","[四足] 짐승의 네발. 또는 네발 가진 짐승.","[四足] ‘사지06’를 속되게 이르는 말."]},{"id":719,"category":"한자어","term":"선처","definition":"형편에 따라 잘 처리함.","example":"선처를 부탁하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[先妻] 이혼이나 재혼을 하였을 때, 전에 혼인했던 여자를 이르는 말.","[善處] 사람이 죽은 뒤 다시 태어나는 좋은 곳."]},{"id":720,"category":"한자어","term":"선풍","definition":"돌발적으로 일어나 세상을 뒤흔드는 사건을 비유적으로 이르는 말.","example":"검거 선풍이 불어닥치다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[仙風] 신선과 같은 기질이나 풍채.","[旋風] 갑자기 생긴 저기압 주변으로 한꺼번에 모여든 공기가 나선 모양으로 일으키는 선회(旋回) 운동.","[颴風] 온대 및 한대 지방에서 발생하는 저기압계의 회오리바람. 폭풍ㆍ눈ㆍ비를 수반하며, 북반구에서는 오른쪽으로 돌고, 남반구에서는 왼쪽으로 돈다."]},{"id":721,"category":"한자어","term":"소개","definition":"공습이나 화재 따위에 대비하여 한곳에 집중되어 있는 주민이나 시설물을 분산함.","example":"본국 정부는 미국인 소개를 서두르고 있으나 특파원은 예외다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[紹介] 둘 사이에서 양편의 일이 진행되게 주선함.","[紹介] 서로 모르는 사람들 사이에서 양편이 알고 지내도록 관계를 맺어 줌.","[紹介] 잘 알려지지 아니하였거나, 모르는 사실이나 내용을 잘 알도록 하여 주는 설명.","[疏開] 땅을 파서 물이 흐르도록 함.","[疏開] 주로 적의 포격으로부터의 피해를 줄이고자, 전투 대형의 거리나 간격을 넓히는 일.","[疏槪] 임금에게 올린 글 내용의 줄거리."]},{"id":722,"category":"한자어","term":"송부","definition":"편지나 물품 따위를 부치어 보냄.","example":"송부를 받다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":723,"category":"한자어","term":"야기","definition":"일이나 사건 따위를 끌어 일으킴.","example":"혼란을 야기하다.","exampleSource":"제공 자료 예문","otherMeanings":["[夜氣] 밤공기의 차고 눅눅한 기운."]},{"id":724,"category":"한자어","term":"어용","definition":"자신의 이익을 위하여 권력자나 권력 기관에 영합하여 줏대 없이 행동하는 것을 낮잡아 이르는 말.","example":"어용 단체.","exampleSource":"표준국어대사전 용례","otherMeanings":["[御用] 임금이 쓰는 것을 이르던 말.","[御用] 정부에서 쓰는 일."]},{"id":725,"category":"한자어","term":"억장","definition":"썩 높은 것. 또는 그런 높이.","example":"억장 같은 근심도 심심초 한 모금 빨면 다 잊어지니까.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":726,"category":"한자어","term":"역임","definition":"여러 직위를 두루 거쳐 지냄.","example":"김 선생은 신문사에서 편집국장, 주필 등을 역임하면서 많은 공을 세웠다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":727,"category":"한자어","term":"입추","definition":"송곳을 세움.","example":"입추의 여지가 없다.","exampleSource":"제공 자료 예문","otherMeanings":["[立秋] 이십사절기의 하나. 대서(大暑)와 처서(處暑) 사이에 들며, 이때부터 가을이 시작된다고 한다. 양력으로는 8월 8일이나 9일경이다.","[立芻] 짚이나 풀로 사람 모양을 만들어 길 좌우에 세워 두고 칼이나 창으로 찌르는 무예."]},{"id":728,"category":"한자어","term":"종식","definition":"한때 매우 성하던 현상이나 일이 끝나거나 없어짐.","example":"냉전의 종식.","exampleSource":"표준국어대사전 용례","otherMeanings":["[種植, /, 種殖] 씨를 뿌리고 식물을 심는 일."]},{"id":729,"category":"한자어","term":"좌천","definition":"낮은 관직이나 지위로 떨어지거나 외직으로 전근됨을 이르는 말. 예전에 중국에서 오른쪽을 숭상하고 왼쪽을 멸시하였던 데서 유래한다.","example":"면 서기들한테는 책임을 물어 시말서를 쓰게 하고 좌천을 시켰다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":730,"category":"한자어","term":"주재","definition":"어떤 일을 중심이 되어 맡아 처리함.","example":"국무총리 주재로 가뭄 대책 회의를 열었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[主材] 주된 재료나 자재.","[主材] 신주(神主)를 만드는 데에 쓰는 나무.","[主宰] 어떤 일을 중심이 되어 맡아 처리하는 사람.","[舟載] 배에 짐을 실음.","[奏裁] 임금에게 아뢰어 재가를 청함.","[酒滓] 재강에 물을 타서 모주를 짜내고 남은 찌꺼기.","[駐在] 한곳에 머물러 있음.","[駐在] 직무상으로 파견되어 한곳에 머물러 있음."]},{"id":731,"category":"한자어","term":"지연","definition":"무슨 일을 더디게 끌어 시간을 늦춤. 또는 시간이 늦추어짐.","example":"출발 시간의 지연.","exampleSource":"표준국어대사전 용례","otherMeanings":["[地緣] 출신 지역에 따라 연결된 인연.","[紙鳶] 종이에 댓가지를 가로세로로 붙여 실을 맨 다음 공중에 높이 날리는 장난감. 꼭지연, 반달연, 치마연, 동이연, 초연, 박이연, 발연 따위가 있다.","[遲延] 병이나 증상이 늦게 나타나는 일. 선천성 병이 중년 이후에 나타나거나, 어떤 병에 감염된 후 한참 지나서 증상이 나타나는 경우를 이른다."]},{"id":732,"category":"한자어","term":"참가","definition":"모임이나 단체 또는 일에 관계하여 들어감.","example":"참가 대상.","exampleSource":"표준국어대사전 용례","otherMeanings":["[參加] 어떤 법률관계에 당사자 이외의 제삼자가 관여함.","[參暇] 선원에서, 볼일이 있어 15일 정도의 여가(餘暇)를 청함."]},{"id":733,"category":"한자어","term":"참척","definition":"자손이 부모나 조부모보다 먼저 죽는 일.","example":"참척의 아픔.","exampleSource":"표준국어대사전 용례","otherMeanings":["한 가지 일에만 정신을 골똘하게 씀."]},{"id":734,"category":"한자어","term":"창건","definition":"건물이나 조직체 따위를 처음으로 세우거나 만듦.","example":"선운사 창건 설화.","exampleSource":"표준국어대사전 용례","otherMeanings":["[蒼健] ‘창건하다02’의 어근."]},{"id":735,"category":"한자어","term":"창궐","definition":"못된 세력이나 전염병 따위가 세차게 일어나 걷잡을 수 없이 퍼짐.","example":"그녀의 허파를 파먹고 들어가는 폐균의 창궐을 어찌할 도리는 없었다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":736,"category":"한자어","term":"출현","definition":"나타나거나 또는 나타나서 보임.","example":"고대 국가의 출현.","exampleSource":"표준국어대사전 용례","otherMeanings":["[出現] 행성이나 위성에 가려졌던 천체가 다시 나타남."]},{"id":737,"category":"한자어","term":"치부","definition":"남에게 드러내고 싶지 아니한 부끄러운 부분.","example":"치부를 드러내다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[恥部] ‘음부07’를 달리 이르는 말.","[致富] 재물을 모아 부자가 됨.","[致賻] 임금이 특명으로 신하에게 부의(賻儀)를 내려 주던 일. 단문(袒免)의 종친, 시마(緦麻) 이상의 이성 왕친(異姓王親), 종이품 이상의 문무관, 공신(功臣), 공사(公事)로 외방에서 죽은 자와 전사자에게 행하였다.","[置簿] 금전이나 물건 따위가 들어오고 나감을 기록함. 또는 그런 장부.","[置簿] 마음속으로 그러하다고 보거나 여김."]},{"id":738,"category":"한자어","term":"타개하다","definition":"매우 어렵거나 막힌 일을 잘 처리하여 해결의 길을 열다.","example":"정부는 수출 부진을 타개하기 위해 새로운 경기 부양책을 내놓았다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":739,"category":"한자어","term":"토로","definition":"마음에 있는 것을 죄다 드러내어서 말함.","example":"적어도 이것은 나 일개인의 경험에 의하면 참으로 엄숙하리만치 현실적인 생활 사실의 적나라한 토로에 속한다.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":740,"category":"한자어","term":"한담","definition":"심심하거나 한가할 때 나누는 이야기. 또는 별로 중요하지 아니한 이야기.","example":"한담을 나누다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[寒痰] 담병(痰病)의 하나. 팔과 다리가 차고 마비되어서 근육이 군데군데 쑤시고 아프다."]},{"id":741,"category":"한자어","term":"함락","definition":"적의 성, 요새, 진지 따위를 공격하여 무너뜨림.","example":"그러나 경주 함락으로 사기가 충천한 견훤의 날래고 용맹스러운 부대에 왕건 군사가 대적할 수는 없었다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[陷落] 땅이 무너져 내려앉음."]},{"id":742,"category":"한자어","term":"결여","definition":"마땅히 있어야 할 것이 빠져서 없거나 모자람.","example":"객관성 결여.","exampleSource":"표준국어대사전 용례","otherMeanings":["[觖如] ‘결여하다02’의 어근."]},{"id":743,"category":"한자어","term":"암시","definition":"넌지시 알림. 또는 그 내용.","example":"암시가 깔리다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[暗示] 뜻하는 바를 간접적으로 나타내는 표현법.","[暗示] 감각, 관념, 의도 따위가 이성에 호소함이 없이 언어 자극을 통하여 다른 사람에게 전달되는 현상.","[暗視] 어두운 곳에서 물체를 보는 일. 적외선 장치를 사용한다."]},{"id":744,"category":"한자어","term":"개량","definition":"나쁜 점을 보완하여 더 좋게 고침.","example":"농기구 개량.","exampleSource":"표준국어대사전 용례","otherMeanings":["[改量] 다시 측량함."]},{"id":745,"category":"한자어","term":"보존","definition":"잘 보호하고 간수하여 남김.","example":"보존 창고.","exampleSource":"표준국어대사전 용례","otherMeanings":[]},{"id":746,"category":"한자어","term":"복원","definition":"원래대로 회복함.","example":"훼손된 문화재의 복원이 시급하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[伏願] 웃어른에게 엎드려 공손히 원함.","[復員] 전시 체제에 있던 군대를 평상 체제로 돌려 군인의 소집을 해제하는 일.","[復圓] 일식이나 월식에서, 태양이나 달이 달이나 지구의 그림자에서 완전히 빠져나온 순간."]},{"id":747,"category":"한자어","term":"실재","definition":"실제로 존재함.","example":"실재의 인물.","exampleSource":"표준국어대사전 용례","otherMeanings":["[實才] 글재주가 있는 사람.","[實才] 현실 문제를 처리할 수 있거나 실용에 도움이 되는 능력.","[實在] 변증법적 유물론에서, 인간의 의식으로부터 독립하여 객관적으로 존재하는 물질세계.","[實在] 관념론에서, 사물의 본질적 존재."]},{"id":748,"category":"한자어","term":"실체","definition":"실제의 물체. 또는 외형에 대한 실상(實相).","example":"사건의 실체를 파악하다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[失體] 체면이나 면목을 잃음.","[實體] 실수로 이루어진 체.","[實體] 늘 변하지 아니하고 일정하게 지속하면서 사물의 근원을 이루는 것."]},{"id":749,"category":"한자어","term":"시력","definition":"물체의 존재나 형상을 인식하는 눈의 능력. 눈으로 두 광점을 구별할 수 있는 능력으로, 광도나 그 밖의 조건이 동일할 때, 시각 세포의 분포 밀도가 클수록 시력이 좋다.","example":"시력이 떨어지다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[詩歷] 시의 창작에 종사하여 온 경력."]},{"id":750,"category":"한자어","term":"안목","definition":"사물을 보고 분별하는 견식.","example":"안목이 있다.","exampleSource":"표준국어대사전 용례","otherMeanings":["집의 칸살이나 모난 그릇의 안으로 잰 척수(尺數).","통로의 안쪽에 있는 위치.","[眼目] 주된 목표."]},{"id":751,"category":"한자어","term":"혜안","definition":"사물을 꿰뚫어 보는 안목과 식견.","example":"아마도 형은 앞날을 내다볼 줄 아는 혜안을 갖고 있었던 것 같았다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[慧眼] 오안의 하나. 우주의 진리를 밝게 보는 눈이다. 모든 현상에 대한 집착을 버리고, 차별의 현상계를 보지 않는 지혜이다."]},{"id":752,"category":"한자어","term":"혼돈","definition":"마구 뒤섞여 있어 갈피를 잡을 수 없음. 또는 그런 상태.","example":"혼돈에 빠지다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[混沌, /, 渾沌] 하늘과 땅이 아직 나누어지기 전의 상태.","[餛飩] 밀가루나 쌀가루 반죽을 둥글게 빚어 그 속에 소를 넣어 찐 떡."]},{"id":753,"category":"한자어","term":"변별","definition":"사물의 옳고 그름이나 좋고 나쁨을 가림.","example":"변별(別) 진짜는 가짜와 반드시 변별되기 마련이다.","exampleSource":"제공 자료 예문","otherMeanings":["[辨別] 세상에 대한 경험이나 식견에서 나오는 생각이나 판단."]},{"id":754,"category":"한자어","term":"보결","definition":"결원이 생겼을 때에 그 빈자리를 채움.","example":"보결 입학.","exampleSource":"표준국어대사전 용례","otherMeanings":["[保結] 선비가 과거에 응시할 때나 관리가 승진할 때에 그 신분을 증명하던 보증서.","[保結] 관가에서 출생 신분을 증명하기 위하여 발행하던 증명 서류.","[補缺] 결점을 고쳐서 보충함."]},{"id":755,"category":"한자어","term":"보조","definition":"주되는 것에 상대하여 거들거나 도움. 또는 그런 사람.","example":"보조 병력.","exampleSource":"표준국어대사전 용례","otherMeanings":["[步調] 걸음걸이의 속도나 모양 따위의 상태.","[步調] 여럿이 함께 일을 할 때의 진행 속도나 조화(調和).","[補助] 보태어 도움.","[補租] 나라에서 정한 조세 이외에 지방의 벼슬아치나 토호들이 수시로 거두어들이던 세금.","[輔助] 노력이나 행동으로 남을 도와줌.","[寶祚] 임금의 자리."]},{"id":756,"category":"한자어","term":"보수","definition":"건물이나 시설 따위의 낡거나 부서진 것을 손보아 고침.","example":"하수도 보수.","exampleSource":"표준국어대사전 용례","otherMeanings":["[步數] 걸음의 수. 거리를 대강 잴 때 사용한다.","[步數] 장기나 바둑에서, 어려운 수를 푸는 방법.","[保手] ‘보증 수표’를 줄여 이르는 말.","[保囚] 보석 보증금을 받거나 보증인을 세우고 형사 피고인을 구류에서 풀어 주는 일.","[保守] 보전하여 지킴.","[保守] 새로운 것이나 변화를 적극적으로 받아들이기보다는 전통적인 것을 옹호하며 유지하려 함.","[保授] 보석(保釋)된 사람이나 도망갈 가능성이 있는 사람을 유력자가 책임을 지고 맡던 일.","[保授] 가까운 친척이나 그 이웃 사람이 잔호를 책임지고 맡던 일.","[報囚] 죄를 논하여 결정하는 일.","[報酬] 고맙게 해 준 데 대하여 보답을 함. 또는 그 보답.","[報酬] 일한 대가로 주는 돈이나 물품.","[報酬] 행위를 촉진하거나 학습 분위기를 조성하기 위하여 사람이나 동물에게 주는 물질이나 칭찬.","[報讐] 남이 저에게 해를 준 대로 저도 그에게 해를 줌.","[補數] 각 자리의 숫자의 합이 어느 일정한 수가 되게 하는 수. 예를 들어 10의 7에 대한 보수는 3이다.","[寶樹] 극락에 일곱 줄로 벌여 있는 보물 나무. 금, 은, 유리, 파리, 마노, 거거, 산호 나무이다."]},{"id":757,"category":"한자어","term":"보상","definition":"어떤 것에 대한 대가로 갚음.","example":"노고에 대해 보상을 받다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[報償] 남에게 진 빚 또는 받은 물건을 갚음.","[報償] 행위를 촉진하거나 학습 분위기를 조성하기 위하여 사람이나 동물에게 주는 물질이나 칭찬.","[補償] 남에게 끼친 손해를 갚음.","[補償] 국가 또는 단체가 적법한 행위에 의하여 국민이나 주민에게 가한 재산상의 손실을 갚아 주기 위하여 제공하는 대상(代償).","[補償] 신체적으로나 정신적으로 열등함을 의식할 때, 다른 측면의 일을 잘 해냄으로써 그것을 보충하려는 마음의 작용.","[褓商] 물건을 보자기에 싸서 메고 다니며 파는 사람.","[輔相] 대신을 거느리며 임금을 도와 나라를 다스림. 또는 그런 사람.","[寶相] 부처의 존엄한 모습."]},{"id":758,"category":"한자어","term":"복기","definition":"바둑에서, 한 번 두고 난 바둑의 판국을 비평하기 위하여 두었던 대로 다시 처음부터 놓아 봄.","example":"비가 오는 날은 바둑판 앞에 앉아 명대국집을 펴 놓고 혼자 복기를 하거나….","exampleSource":"표준국어대사전 용례","otherMeanings":["[服忌] 근친의 상(喪)을 당하여 상제로서 일을 봄.","[服朞] 기년복을 입음.","[腹鰭] 물고기의 배에 달린 지느러미. 좌우에 한 쌍이 있으며 몸의 균형을 잡고 몸을 나아가게 하는 역할을 한다."]},{"id":759,"category":"한자어","term":"복합어","definition":"하나의 실질 형태소에 접사가 붙거나 두 개 이상의 실질 형태소가 결합된 말. ‘덧신’, ‘먹이’와 같은 파생어와, ‘집안’, ‘공부방’과 같은 합성어로 나뉜다.","example":"‘돌다리’는 두 형태소가 결합한 복합어이다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":760,"category":"한자어","term":"동음어","definition":"소리는 같으나 뜻이 다른 단어.","example":"‘배’는 뜻이 여러 개인 동음어의 예로 볼 수 있다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":761,"category":"한자어","term":"다의어","definition":"두 가지 이상의 뜻을 가진 단어. ‘다리’는 원래 ‘사람이나 짐승의 몸통 아래에 붙어서 몸을 받치며 서거나 걷거나 뛰게 하는 부분’을 가리키지만, ‘책상 다리’, ‘지겟다리’처럼 ‘물건의 하체 부분’을 가리키기도 하는데, 이러한 단어를 이른다.","example":"‘손’은 여러 의미로 쓰이는 다의어이다.","exampleSource":"제공 자료 예문","otherMeanings":[]},{"id":762,"category":"한자어","term":"답보","definition":"상태가 나아가지 못하고 한 자리에 머무르는 일. 또는 그런 상태.","example":"협상은 진전 없이 답보 상태에 머물렀다.","exampleSource":"제공 자료 예문","otherMeanings":["→ 답치기.","[答報] 응답으로 보고함. 또는 그런 보고."]},{"id":763,"category":"한자어","term":"양심","definition":"사물의 가치를 변별하고 자기의 행위에 대하여 옳고 그름과 선과 악의 판단을 내리는 도덕적 의식.","example":"양심의 가책을 받다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[兩心] 두 마음.","[兩心] 겉 다르고 속 다른 마음.","[養心] 심성(心性)을 수양함."]},{"id":764,"category":"한자어","term":"신념","definition":"굳게 믿는 마음.","example":"신념을 지키다.","exampleSource":"표준국어대사전 용례","otherMeanings":["[宸念] 임금의 생각 또는 걱정."]}];
